css:
.dag-util {
  width: 100%;
  height: var(--dag-util-h, 680px);
  container-type: inline-size;
  container-name: dag-util;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-util-bg);
  color: var(--dag-util-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-util-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-util-focus, var(--dag-util-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-util-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-util-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-util-num { font-variant-numeric: tabular-nums; }
  & .dag-util-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-util-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-util-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

.dag-util {
  /* re-theme with these four */
  --dag-util-bg: oklch(0.972 0.01 85);
  --dag-util-ink: oklch(0.24 0.02 65);
  --dag-util-accent: oklch(0.6 0.165 38);
  --dag-util-heat: oklch(0.43 0.085 168);
  /* derived */
  --dag-util-card: color-mix(in oklch, var(--dag-util-bg), white 70%);
  --dag-util-side: color-mix(in oklch, var(--dag-util-bg), var(--dag-util-ink) 3%);
  --dag-util-line: color-mix(in oklch, var(--dag-util-ink) 12%, transparent);
  --dag-util-hair: color-mix(in oklch, var(--dag-util-ink) 6.5%, transparent);
  --dag-util-mute: color-mix(in oklch, var(--dag-util-ink) 66%, var(--dag-util-bg));
  --dag-util-faint: color-mix(in oklch, var(--dag-util-ink) 44%, var(--dag-util-bg));
  --dag-util-heat-lo: color-mix(in oklch, var(--dag-util-heat) 5%, var(--dag-util-card));
  --dag-util-sand: oklch(0.83 0.065 78);
  --dag-util-sage: oklch(0.76 0.055 140);
  --dag-util-stone: oklch(0.7 0.012 70);
  --dag-util-ochre: oklch(0.7 0.13 78);
  --dag-util-slate: oklch(0.52 0.07 250);
  --dag-util-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-util-out: cubic-bezier(.16, 1, .3, 1);
  --dag-util-spring: linear(0, .08 3%, .32 8%, .66 14%, .93 21%, 1.06 27%, 1.09 32%, 1.06 39%, 1.01 50%, .995 62%, 1);
  color-scheme: light;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1px var(--dag-util-line);
}

.dag-util__app {
  height: 100%;
  display: grid;
  grid-template-columns: 184px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "rail top" "rail main";
}

/* ---------- rail ---------- */
.dag-util__rail {
  grid-area: rail;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 18px 12px 14px;
  background: var(--dag-util-side);
  border-right: 1px solid var(--dag-util-line);
  border-radius: 16px 0 0 16px;
}
.dag-util__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .dag-util__mark { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; color: var(--dag-util-card); background: var(--dag-util-ink); flex: none; }
  & .dag-util__bt { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-size: 14.5px; font-weight: 750; letter-spacing: -.025em; }
  & small { font-size: 11px; color: var(--dag-util-faint); }
}
.dag-util__nav { display: grid; gap: 2px; }
.dag-util__nb {
  width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 9px;
  color: var(--dag-util-mute); font-weight: 560;
  transition: background-color .18s, color .18s, box-shadow .18s;
  & span { white-space: nowrap; }
  &:hover { color: var(--dag-util-ink); background: var(--dag-util-hair); }
  &[aria-current="page"] {
    color: var(--dag-util-ink); background: var(--dag-util-card);
    box-shadow: 0 0 0 1px var(--dag-util-line), 0 3px 8px -6px color-mix(in oklch, var(--dag-util-ink) 50%, transparent);
    & .dag-util-i { color: var(--dag-util-accent); }
  }
}
.dag-util__railcard {
  margin-top: auto; display: grid; gap: 6px; padding: 12px; border-radius: 11px;
  background: var(--dag-util-card); box-shadow: 0 0 0 1px var(--dag-util-line);
  & p { font-size: 12px; line-height: 1.35; color: var(--dag-util-mute); }
  & p b { color: var(--dag-util-ink); font-weight: 650; }
  & small { font-size: 11px; color: var(--dag-util-faint); }
}
.dag-util__subm {
  height: 5px; border-radius: 5px; background: var(--dag-util-hair); overflow: hidden;
  & i { display: block; height: 100%; width: calc(10 / 14 * 100%); background: var(--dag-util-heat); border-radius: inherit; transform-origin: left; animation: dag-util-growx 1.1s var(--dag-util-out) .3s both; }
}
.dag-util__eb { font: 600 10.5px/1.3 var(--dag-util-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-util-accent); }

/* ---------- header ---------- */
.dag-util__top {
  grid-area: top;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "title seg" "bar bar";
  align-items: end;
  gap: 12px 18px;
  padding: 18px 22px 12px;
}
.dag-util__title {
  grid-area: title; min-width: 0;
  & h2 { font-size: clamp(19px, 2.3cqi, 27px); font-weight: 720; letter-spacing: -.035em; line-height: 1.08; margin-top: 4px; }
}
.dag-util__seg {
  grid-area: seg; display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dag-util-hair);
  & button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dag-util-mute); white-space: nowrap; transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dag-util-ink); }
  & button[aria-checked="true"] { background: var(--dag-util-card); color: var(--dag-util-ink); box-shadow: 0 1px 3px -1px color-mix(in oklch, var(--dag-util-ink) 40%, transparent), 0 0 0 1px var(--dag-util-line); }
}
.dag-util__bar { grid-area: bar; display: flex; align-items: center; justify-content: space-between; gap: 10px 18px; flex-wrap: wrap; }
.dag-util__chips {
  display: flex; flex-wrap: wrap; gap: 6px;
  & button {
    height: 28px; padding: 0 11px 0 8px; border-radius: 99px; display: inline-flex; align-items: center; gap: 7px;
    font-size: 12px; font-weight: 600; color: var(--dag-util-mute);
    box-shadow: inset 0 0 0 1px var(--dag-util-line);
    transition: background-color .18s, color .18s, box-shadow .18s;
  }
  & button i { width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--c); transition: background-color .18s; }
  & button[aria-pressed="true"] { color: var(--dag-util-ink); background: var(--dag-util-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, var(--dag-util-line)); }
  & button[aria-pressed="true"] i { background: var(--c); }
  & button:hover { color: var(--dag-util-ink); }
  & small { font: 600 10.5px var(--dag-util-mono); color: var(--dag-util-faint); }
}
.dag-util__legend {
  display: flex; align-items: center; gap: 6px; font: 500 10.5px var(--dag-util-mono); color: var(--dag-util-faint);
  & .dag-util__ramp { width: 72px; height: 8px; border-radius: 3px; background: linear-gradient(90deg, var(--dag-util-heat-lo), var(--dag-util-heat)); box-shadow: inset 0 0 0 1px var(--dag-util-hair); }
  & .dag-util__sw { width: 12px; height: 8px; border-radius: 2px; margin-left: 8px; }
  & .dag-util__sw--over { background: repeating-linear-gradient(-45deg, var(--dag-util-accent) 0 2px, color-mix(in oklch, var(--dag-util-accent) 60%, var(--dag-util-card)) 2px 4px); }
  & .dag-util__sw--leave { background: repeating-linear-gradient(-45deg, var(--dag-util-line) 0 1.5px, transparent 1.5px 3.5px); box-shadow: inset 0 0 0 1px var(--dag-util-line); }
}

/* ---------- main ---------- */
.dag-util__main {
  grid-area: main;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
  padding: 0 22px 18px;
}
.dag-util__kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.dag-util__kpi {
  display: grid; gap: 2px; padding: 11px 14px 12px; border-radius: 12px; background: var(--dag-util-card); box-shadow: inset 0 0 0 1px var(--dag-util-line);
  & .dag-util__kl { font-size: 11.5px; font-weight: 550; color: var(--dag-util-mute); }
  & .dag-util__kv { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 680; letter-spacing: -.035em; line-height: 1.1; }
  & .dag-util__ks { font-size: 11.5px; color: var(--dag-util-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &.dag-util__kpi--warn .dag-util__kv { color: var(--dag-util-accent); }
}
.dag-util__view { min-height: 0; display: grid; }
.dag-util__mixv { grid-template-columns: minmax(0, 1.45fr) minmax(0, 1fr); gap: 12px; }
.dag-util__panel {
  min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 13px;
  background: var(--dag-util-card); box-shadow: inset 0 0 0 1px var(--dag-util-line);
  overflow: hidden;
}
.dag-util__ph {
  padding: 14px 18px 10px;
  & h3 { font-size: 14px; font-weight: 680; letter-spacing: -.015em; }
  & p { font-size: 12px; color: var(--dag-util-faint); margin-top: 1px; }
  &.dag-util__ph--row { display: flex; justify-content: space-between; align-items: start; gap: 12px; flex-wrap: wrap; }
}

/* ---------- heatmap ---------- */
.dag-util__hs { flex: 1; min-height: 0; }
.dag-util__grid {
  --n: 12;
  display: grid;
  grid-template-columns: minmax(150px, 1.55fr) repeat(var(--n), minmax(30px, 1fr)) minmax(104px, .95fr) 56px;
  column-gap: 3px;
  row-gap: 3px;
  padding: 0 14px 12px;
  min-width: 660px;
}
.dag-util__row {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
  align-items: center;
  min-height: 30px;
  border-radius: 8px;
  transition: background-color .15s;
}
.dag-util__row--head {
  position: sticky; top: 0; z-index: 4; min-height: 0;
  padding: 12px 0 6px; background: var(--dag-util-card);
  align-items: end;
  font: 500 10.5px/1.15 var(--dag-util-mono); color: var(--dag-util-faint);
  & .dag-util__wk { text-align: center; display: grid; transition: color .15s; }
  & > :first-child { position: sticky; left: 0; z-index: 2; background: var(--dag-util-card); }
  & .dag-util__sort { white-space: nowrap; }
  & .dag-util__wk b { font-weight: 650; color: var(--dag-util-mute); }
  & .dag-util__wk span { min-height: 1.15em; }
}
.dag-util__sort {
  display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 6px; margin-left: -6px; border-radius: 6px;
  font: 600 10.5px var(--dag-util-mono); letter-spacing: .05em; text-transform: uppercase; color: var(--dag-util-faint);
  transition: color .15s, background-color .15s;
  & svg { width: 10px; height: 10px; opacity: 0; transition: opacity .15s, rotate .25s var(--dag-util-out); }
  &:hover { color: var(--dag-util-ink); background: var(--dag-util-hair); }
  [aria-sort="ascending"] > &, [aria-sort="descending"] > & { color: var(--dag-util-ink); }
  [aria-sort="ascending"] > & svg { opacity: 1; rotate: 180deg; }
  [aria-sort="descending"] > & svg { opacity: 1; }
}
.dag-util__h-end { text-align: right; }
.dag-util__row--team {
  min-height: 52px; margin-bottom: 6px; padding-bottom: 6px;
  border-bottom: 1px solid var(--dag-util-line); border-radius: 0;
  position: relative;
}
.dag-util__teamlbl {
  grid-row: 1; display: grid; line-height: 1.2; padding-left: 4px; position: sticky; left: 0; z-index: 2; background: var(--dag-util-card); align-self: stretch; align-content: center;
  & b { font-size: 12.5px; font-weight: 680; }
  & small { font-size: 11px; color: var(--dag-util-faint); }
}
.dag-util__tb {
  grid-row: 1; height: 44px; display: flex; align-items: end; justify-content: center; position: relative;
  & i {
    width: 74%; max-width: 34px; height: calc(min(var(--v), 1.15) / 1.15 * 100%);
    border-radius: 4px 4px 2px 2px;
    display: grid; justify-items: center; align-content: start; padding-top: 3px;
    font: 650 9.5px/1 var(--dag-util-mono); font-style: normal; color: oklch(0.99 0 0 / .9);
    background: color-mix(in oklch, var(--dag-util-heat) 78%, var(--dag-util-card));
    transform-origin: bottom; animation: dag-util-growy .75s var(--dag-util-out) both; animation-delay: calc(var(--c) * 32ms + 120ms);
    transition: background-color .15s;
  }
  &.is-low i { background: color-mix(in oklch, var(--dag-util-heat) 38%, var(--dag-util-card)); color: color-mix(in oklch, var(--dag-util-ink) 75%, transparent); }
}
.dag-util__tl {
  grid-row: 1; grid-column: 2 / -3; align-self: end; height: 0; position: relative; pointer-events: none;
  margin-bottom: calc(var(--t) / 1.15 * 44px);
  border-top: 1.5px dashed var(--dag-util-accent);
  & span { position: absolute; right: 0; bottom: 3px; font: 650 10px var(--dag-util-mono); color: var(--dag-util-accent); background: var(--dag-util-card); padding: 0 3px; border-radius: 3px; }
}
.dag-util__teamp { grid-row: 1; padding-left: 8px; font: 650 15px var(--dag-util-mono); letter-spacing: -.03em; }
.dag-util__teamv { grid-row: 1; }

.dag-util__who {
  position: sticky; left: 0; z-index: 2; background: var(--dag-util-card); border-radius: 8px; min-width: 0;
}
.dag-util__pb {
  width: 100%; display: flex; align-items: center; gap: 9px; text-align: left; padding: 2px 6px 2px 2px; border-radius: 8px; min-width: 0;
  transition: background-color .15s;
  & .dag-util__av { width: 24px; height: 24px; border-radius: 50%; flex: none; display: grid; place-items: center; font: 680 9.5px/1 system-ui, sans-serif; letter-spacing: .02em; color: var(--dag-util-card); background: var(--c); }
  & span:last-child { display: grid; min-width: 0; line-height: 1.15; }
  & b { font-size: 12.5px; font-weight: 610; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 10.5px; color: var(--dag-util-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:hover { background: var(--dag-util-hair); }
}
.dag-util__cell {
  --x: 0;
  height: 26px; border-radius: 5px; display: grid; place-items: center; position: relative;
  font: 600 10.5px/1 var(--dag-util-mono); letter-spacing: -.02em;
  color: color-mix(in oklch, var(--dag-util-ink) 72%, transparent);
  background: color-mix(in oklch, var(--dag-util-heat) calc(var(--v) * 90%), var(--dag-util-heat-lo));
  box-shadow: inset 0 0 0 calc(var(--x) * 1.5px) color-mix(in oklch, var(--dag-util-ink) 45%, transparent);
  cursor: pointer; outline: none;
  transition: opacity .2s, scale .25s var(--dag-util-out), box-shadow .15s;
  animation: dag-util-pop .55s var(--dag-util-out) both;
  animation-delay: calc((var(--r) + var(--c)) * 16ms);
  &.is-hi { color: oklch(0.995 0 0 / .94); }
  &.is-over { color: oklch(0.995 0 0); background: repeating-linear-gradient(-45deg, var(--dag-util-accent) 0 3px, color-mix(in oklch, var(--dag-util-accent) 78%, var(--dag-util-card)) 3px 6px); }
  &.is-leave { color: var(--dag-util-faint); background: repeating-linear-gradient(-45deg, var(--dag-util-line) 0 1.5px, transparent 1.5px 4.5px); box-shadow: inset 0 0 0 1px var(--dag-util-hair); }
  &:hover, &:focus-visible { scale: 1.14; z-index: 3; box-shadow: 0 0 0 2px var(--dag-util-card), 0 0 0 3.5px var(--dag-util-ink), 0 6px 14px -6px color-mix(in oklch, var(--dag-util-ink) 60%, transparent); }
}
.dag-util__bul {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; padding-left: 10px;
  & em { font: 650 12px var(--dag-util-mono); font-style: normal; min-width: 34px; text-align: right; letter-spacing: -.03em; }
}
.dag-util__bb {
  position: relative; height: 8px; border-radius: 4px; background: var(--dag-util-hair);
  & i { position: absolute; inset: 0 auto 0 0; width: calc(min(var(--u), 1.2) / 1.2 * 100%); border-radius: inherit; background: var(--dag-util-heat); transform-origin: left; animation: dag-util-growx .8s var(--dag-util-out) both; animation-delay: calc(var(--r) * 22ms + 150ms); }
  & b { position: absolute; top: -4px; bottom: -4px; left: calc(var(--t) / 1.2 * 100%); width: 2px; margin-left: -1px; border-radius: 1px; background: var(--dag-util-ink); }
  &.is-over i { background: var(--dag-util-accent); }
}
.dag-util__var { text-align: right; font: 650 11.5px var(--dag-util-mono); padding-right: 2px; color: var(--dag-util-heat); &.is-neg { color: var(--dag-util-accent); } }

/* once the entry animation has played, reordering rows must not replay it */
.dag-util__grid.is-settled { & .dag-util__cell, & .dag-util__bb i, & .dag-util__tb i { animation: none; } }

/* crosshair: the hovered or focused cell lights its row and its week column */
.dag-util__grid:has(.dag-util__cell:is(:hover, :focus-visible)) .dag-util__cell { opacity: .42; }
.dag-util__grid .dag-util__row:has(.dag-util__cell:is(:hover, :focus-visible)) {
  background: var(--dag-util-hair);
  & .dag-util__cell { opacity: 1; }
  & .dag-util__pb b { color: var(--dag-util-accent); }
}
.dag-util__grid:has([data-w="0"]:is(:hover, :focus-visible)) [data-w="0"],
.dag-util__grid:has([data-w="1"]:is(:hover, :focus-visible)) [data-w="1"],
.dag-util__grid:has([data-w="2"]:is(:hover, :focus-visible)) [data-w="2"],
.dag-util__grid:has([data-w="3"]:is(:hover, :focus-visible)) [data-w="3"],
.dag-util__grid:has([data-w="4"]:is(:hover, :focus-visible)) [data-w="4"],
.dag-util__grid:has([data-w="5"]:is(:hover, :focus-visible)) [data-w="5"],
.dag-util__grid:has([data-w="6"]:is(:hover, :focus-visible)) [data-w="6"],
.dag-util__grid:has([data-w="7"]:is(:hover, :focus-visible)) [data-w="7"],
.dag-util__grid:has([data-w="8"]:is(:hover, :focus-visible)) [data-w="8"],
.dag-util__grid:has([data-w="9"]:is(:hover, :focus-visible)) [data-w="9"],
.dag-util__grid:has([data-w="10"]:is(:hover, :focus-visible)) [data-w="10"],
.dag-util__grid:has([data-w="11"]:is(:hover, :focus-visible)) [data-w="11"] {
  --x: 1;
  opacity: 1;
  &.dag-util__wk { color: var(--dag-util-ink); & b { color: var(--dag-util-accent); } }
  &.dag-util__tb i { background: var(--dag-util-heat); }
}

/* ---------- time mix ---------- */
.dag-util__mixrows { display: grid; gap: 16px; padding: 6px 18px 8px; overflow: auto; }
.dag-util__mr {
  display: grid; grid-template-columns: 118px minmax(0, 1fr) 62px; align-items: center; gap: 12px;
  & .dag-util__mrl { display: grid; justify-items: start; line-height: 1.2; }
  & .dag-util__mrl b { font-size: 13px; font-weight: 650; }
  & .dag-util__focus { font-size: 11px; color: var(--dag-util-faint); border-radius: 4px; padding: 1px 0; transition: color .15s; }
  & .dag-util__focus:hover { color: var(--dag-util-accent); text-decoration: underline; text-underline-offset: 2px; }
  & .dag-util__mrt { text-align: right; font: 600 11.5px var(--dag-util-mono); color: var(--dag-util-mute); white-space: nowrap; }
  &.dag-util__mr--all .dag-util__stack { height: 34px; }
}
.dag-util__stack {
  display: flex; gap: 2px; height: 26px; border-radius: 7px; overflow: hidden;
  animation: dag-util-wipe .9s var(--dag-util-out) both; animation-delay: calc(var(--i) * 80ms);
  & > span {
