  ws.forEach((i, k) => { if (ws.length <= 8 || k % 2 === 0 || k === ws.length - 1) g += `<text class="dag-util__ax" x="${x(k)}" y="${Hh - 8}" text-anchor="middle">${WEEKS[i].label}</text>`; });
