    : `<b>${H(a.bill - a.tgtH)} h</b> above target over ${n} weeks${a.over ? ` — and over 100% of available hours in <b>${a.over} week${a.over > 1 ? 's' : ''}</b>. Worth checking workload before it shows.` : '.'}`;
  /* week-by-week stacked bars */
