    parts.forEach(([key, v, c]) => { if (v <= 0) return; rects += `<rect x="${x0}" y="${Y(acc + v)}" width="${bw}" height="${Y(acc) - Y(acc + v)}" fill="${c}" rx="1.5"/>`; acc += v; });
    const foc = S.openW === i;
    rects += w.avail ? `<line x1="${x0 - 2}" x2="${x0 + bw + 2}" y1="${Y(p.target * w.avail)}" y2="${Y(p.target * w.avail)}" stroke="var(--dag-util-accent)" stroke-width="2" stroke-linecap="round"/>` : '';
    bars += `<g class="dag-util__wb" data-wb="${i}" style="--i:${k}">${rects}<rect x="${x0 - slot * .19}" y="${pt}" width="${slot}" height="${VH - pt - pb}" fill="transparent"${foc ? ' class="is-focus" rx="4" style="fill:color-mix(in oklch, var(--dag-util-ink) 6%, transparent)"' : ''}/></g>`;
    if (n <= 8 || k % 2 === 0 || foc) bars += `<text x="${x0 + bw / 2}" y="${VH - 4}" text-anchor="middle" style="font:${foc ? 700 : 500} 9.5px var(--dag-util-mono);fill:var(--dag-util-${foc ? 'ink' : 'faint'})">${WEEKS[i].day}/${WEEKS[i].mn}</text>`;
  });
  const nbr = CATS.slice(1, 5).map((c) => ({ c, v: a[c.k] }));
  const nmax = Math.max(1, ...nbr.map((x) => x.v));
  drawer.innerHTML = `
    <header class="dag-util__dh" style="--c:${discColor(p.disc)}">
      <span class="dag-util__av" aria-hidden="true">${p.ini}</span>
      <div><h3>${p.name}</h3><p>${p.role} · ${p.days === 4 ? '4-day week' : 'full time'} · £${p.rate}/h</p></div>
      <div class="dag-util__dnav">
        <button type="button" class="dag-util__ib" data-step="-1" aria-label="Previous person">${ICON.prev}</button>
        <button type="button" class="dag-util__ib" data-step="1" aria-label="Next person">${ICON.next}</button>
        <button type="button" class="dag-util__ib" data-close aria-label="Close detail">${ICON.close}</button>
      </div>
    </header>
    <div class="dag-util__db dag-util-scroll">
      <div class="dag-util__big"><strong class="dag-util-num">${Math.round(a.util * 100)}<small>%</small></strong><span class="dag-util__pill${a.var < 0 ? ' is-neg' : ''}">${PP(a.var)} pp vs ${PCT(p.target)} target</span><p>${sentence}</p></div>
      <div class="dag-util__stats">
        <div><span>Billable</span><b>${H(a.bill)} h</b></div>
        <div><span>Available</span><b>${H(a.avail)} h</b></div>
        <div><span>At rate card</span><b>${GBP(a.value)}</b></div>
        <div><span>Leave &amp; holidays</span><b>${a.ld} day${a.ld === 1 ? '' : 's'}</b></div>
      </div>
      <section class="dag-util__dsec"><h4>Week by week · billable, other, leave</h4><div class="dag-util__wbars"><svg viewBox="0 0 ${VW} ${VH}" aria-hidden="true">${bars}</svg></div></section>
      <section class="dag-util__dsec"><h4>Non-billable · ${H(nb)} h</h4><ul class="dag-util__nbl">${nbr.map((x) => `<li><span>${x.c.label}</span><i style="--c:${x.c.c};--w:${(x.v / nmax * 100).toFixed(1)}%"></i><b>${H(x.v)} h</b></li>`).join('')}</ul></section>
    </div>`;
  drawer.setAttribute('aria-label', `${p.name}, utilisation detail`);
}

/* ------------------------------------------------------------------ views */
function setView(v) {
  S.view = v;
  $$('.dag-util__nb').forEach((b) => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dag-util__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  $('[data-legend]').style.visibility = v === 'grid' ? '' : 'hidden';
  hideTip();
  if (v === 'mix') renderMix();
  if (v === 'trend') { renderSeriesBtns(); renderTrend(); }
}
function renderAll() {
  renderLabel();
  renderKpis();
  renderGrid();
  if (S.view === 'mix') renderMix();
  if (S.view === 'trend') { renderSeriesBtns(); renderTrend(); }
  if (S.open) renderDrawer();
}
function setRange(n) {
  if (S.range === n) return;
  S.range = n;
  $$('[data-range]').forEach((b) => { const on = +b.dataset.range === n; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  if (!weeksIdx().includes(S.focus.w)) S.focus.w = 11;
  renderAll();
}
function toggleDisc(k) {
  if (S.on.has(k) && S.on.size === 1) { toast('At least one discipline stays on'); return; }
  S.on.has(k) ? S.on.delete(k) : S.on.add(k);
  S.hide.delete(k);
  renderChips();
  renderAll();
}

/* ------------------------------------------------------------------ events */
root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if ((el = t.closest('[data-range]'))) return setRange(+el.dataset.range);
  if ((el = t.closest('[data-disc]'))) return toggleDisc(el.dataset.disc);
  if ((el = t.closest('[data-sort]'))) return setSort(el.dataset.sort);
  if ((el = t.closest('[data-open]'))) return openDrawer(el.dataset.open, null, el);
  if ((el = t.closest('.dag-util__cell'))) { S.focus = { p: el.dataset.p, w: +el.dataset.w }; rove(); return openDrawer(el.dataset.p, +el.dataset.w, el); }
  if ((el = t.closest('[data-focus]'))) return focusDisc(el.dataset.focus);
  if ((el = t.closest('[data-series]'))) return toggleSeries(el.dataset.series);
  if ((el = t.closest('[data-step]'))) return stepDrawer(+el.dataset.step);
  if (t.closest('[data-close]') || t.closest('.dag-util__scrim')) return closeDrawer();
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && S.open) { e.preventDefault(); closeDrawer(); return; }
  const r = e.target.closest && e.target.closest('[role="radio"]');
  if (r && /^Arrow(Left|Right|Up|Down)$/.test(e.key)) {
    e.preventDefault();
    const g = $$('[role="radio"]', r.parentElement);
    const i = (g.indexOf(r) + (/Right|Down/.test(e.key) ? 1 : -1) + g.length) % g.length;
    g[i].focus();
    g[i].click();
  }
});
root.addEventListener('pointermove', (e) => {
  const t = e.target;
  if (t.closest('.dag-util__chart')) return;
  let el;
  if ((el = t.closest('.dag-util__cell'))) return cellTip(el, e.clientX, e.clientY);
  if ((el = t.closest('.dag-util__tb'))) {
    const i = +el.dataset.team, list = visible();
    let A = 0, B = 0, L = 0;
    list.forEach((p) => { A += p.weeks[i].avail; B += p.weeks[i].bill; L += p.weeks[i].leave; });
    return showTip(`<span class="dag-util__tt">Whole team · w/c ${WEEKS[i].label}</span>${row('Utilisation', PCT(A ? B / A : 0))}${row('Billable', H(B) + ' h', 'var(--dag-util-heat)')}${row('Available', H(A) + ' h')}${L ? row('Leave & holidays', H(L) + ' h') : ''}${i === BANK ? row('Bank holiday', 'Mon 31 Aug') : ''}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('.dag-util__stack > span'))) {
    const c = CATS.find((x) => x.k === el.dataset.k);
    return showTip(`<span class="dag-util__tt">${el.dataset.g === 'All' ? 'Whole studio' : el.dataset.g}</span>${row(c.label, H(+el.dataset.h) + ' h', c.k === 'leave' ? '' : c.c)}${row('Share', ((+el.dataset.h / +el.dataset.t) * 100).toFixed(1) + '%')}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('[data-load]'))) {
    const p = byId[el.dataset.load], a = agg(p, weeksIdx());
    return showTip(`<span class="dag-util__tt">${p.name}</span>${CATS.slice(1, 5).map((c) => row(c.label, H(a[c.k]) + ' h', c.c)).join('')}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('[data-wb]'))) {
    const p = byId[S.open], i = +el.dataset.wb, w = p && p.weeks[i];
    if (!w) return;
    return showTip(`<span class="dag-util__tt">w/c ${WEEKS[i].label}</span>${row('Billable', H(w.bill) + ' h', 'var(--dag-util-heat)')}${row('Other', H(w.logged - w.bill) + ' h', 'var(--dag-util-sand)')}${w.leave ? row('Leave', H(w.leave) + ' h') : ''}${w.avail ? row('Target', H(p.target * w.avail) + ' h', 'var(--dag-util-accent)') : ''}`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerleave', hideTip);

/* ------------------------------------------------------------------ mount */
renderChips();
$$('[data-range]').forEach((b) => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
renderAll();

css:
.dag-burn {
  width: 100%;
  height: var(--dag-burn-h, 680px);
  container-type: inline-size;
  container-name: dag-burn;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-burn-bg);
  color: var(--dag-burn-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-burn-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-burn-focus, var(--dag-burn-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-burn-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-burn-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-burn-num { font-variant-numeric: tabular-nums; }
  & .dag-burn-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-burn-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-burn-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

.dag-burn {
  /* re-theme with these four */
  --dag-burn-bg: oklch(0.185 0.007 255);
  --dag-burn-ink: oklch(0.95 0.005 255);
  --dag-burn-accent: oklch(0.89 0.18 127);
  --dag-burn-warm: oklch(0.8 0.145 68);
  /* derived */
  --dag-burn-bad: oklch(0.69 0.19 27);
  --dag-burn-panel: color-mix(in oklch, var(--dag-burn-bg), var(--dag-burn-ink) 4%);
  --dag-burn-raise: color-mix(in oklch, var(--dag-burn-bg), var(--dag-burn-ink) 8%);
  --dag-burn-line: color-mix(in oklch, var(--dag-burn-ink) 11%, transparent);
  --dag-burn-hair: color-mix(in oklch, var(--dag-burn-ink) 6%, transparent);
  --dag-burn-mute: color-mix(in oklch, var(--dag-burn-ink) 68%, var(--dag-burn-bg));
  --dag-burn-faint: color-mix(in oklch, var(--dag-burn-ink) 44%, var(--dag-burn-bg));
  --dag-burn-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-burn-out: cubic-bezier(.16, 1, .3, 1);
  --dag-burn-spring: linear(0, .09 3%, .34 8.5%, .69 15%, .95 22%, 1.07 28%, 1.08 33%, 1.04 41%, 1 53%, .995 66%, 1);
  color-scheme: dark;
  border-radius: 16px;
  font-size: 13px;
}

.dag-burn__app {
  height: 100%;
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "rail top" "rail main";
}

/* ---------- rail ---------- */
.dag-burn__rail {
  grid-area: rail; min-height: 0;
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 16px 0;
  border-right: 1px solid var(--dag-burn-line);
}
.dag-burn__logo {
  width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; margin-bottom: 14px;
  color: var(--dag-burn-bg); background: var(--dag-burn-accent);
  & .dag-burn-i { stroke-width: 2.2; }
}
.dag-burn__rb {
  position: relative; width: 56px; padding: 8px 0 7px; border-radius: 11px;
  display: grid; justify-items: center; gap: 4px;
  color: var(--dag-burn-faint); font-size: 10.5px; font-weight: 560; letter-spacing: .01em;
  transition: color .18s, background-color .18s;
  &:hover { color: var(--dag-burn-ink); background: var(--dag-burn-hair); }
  &[aria-current="page"] { color: var(--dag-burn-ink); background: var(--dag-burn-raise); }
  &[aria-current="page"] .dag-burn-i { color: var(--dag-burn-accent); }
  &[aria-current="page"]::before { content: ""; position: absolute; left: -8px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dag-burn-accent); }
}
.dag-burn__badge {
  position: absolute; top: 3px; right: 9px; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 9px;
  display: grid; place-items: center; font: 700 10px/1 var(--dag-burn-mono); font-style: normal;
  color: var(--dag-burn-bg); background: var(--dag-burn-bad);
  &:empty { display: none; }
}

/* ---------- header ---------- */
.dag-burn__top {
  grid-area: top; display: flex; align-items: end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap;
  padding: 18px 22px 12px;
}
.dag-burn__eb { font: 600 10.5px/1.3 var(--dag-burn-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dag-burn-faint); }
.dag-burn__title h2 { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 680; letter-spacing: -.035em; line-height: 1.1; margin-top: 4px; }
.dag-burn__tools { display: flex; align-items: center; gap: 14px; }
.dag-burn__asof { font: 500 11px var(--dag-burn-mono); color: var(--dag-burn-faint); }
.dag-burn__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dag-burn-hair); box-shadow: inset 0 0 0 1px var(--dag-burn-line);
  & button { height: 26px; padding: 0 11px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dag-burn-mute); transition: background-color .18s, color .18s; }
  & button:hover { color: var(--dag-burn-ink); }
  & button[aria-checked="true"] { background: var(--dag-burn-ink); color: var(--dag-burn-bg); }
}

/* ---------- main & views ---------- */
.dag-burn__main { grid-area: main; min-height: 0; padding: 0 22px 18px; display: grid; }
.dag-burn__view { min-height: 0; display: grid; gap: 12px; }
.dag-burn__panel {
  min-height: 0; min-width: 0; border-radius: 13px; background: var(--dag-burn-panel);
  box-shadow: inset 0 0 0 1px var(--dag-burn-line);
  display: flex; flex-direction: column; overflow: hidden;
}
.dag-burn__ph {
  padding: 14px 16px 6px;
  & h3 { font-size: 13.5px; font-weight: 650; letter-spacing: -.01em; }
  & p { font-size: 11.5px; color: var(--dag-burn-faint); margin-top: 1px; }
}

/* portfolio */
.dag-burn__pv {
  grid-template-columns: minmax(0, .92fr) minmax(0, 1.35fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "tot tot" "scat tbl";
}
.dag-burn__totals {
  grid-area: tot; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px;
  border-radius: 13px; overflow: hidden; background: var(--dag-burn-line); box-shadow: inset 0 0 0 1px var(--dag-burn-line);
  & > div { background: var(--dag-burn-panel); padding: 12px 16px 13px; display: grid; gap: 3px; }
  & span { font-size: 11.5px; color: var(--dag-burn-mute); }
  & b { font: 600 clamp(18px, 2.1cqi, 24px)/1.1 var(--dag-burn-mono); letter-spacing: -.04em; }
  & small { font: 500 11px var(--dag-burn-mono); color: var(--dag-burn-faint); }
  & .is-bad b { color: var(--dag-burn-bad); }
  & .is-good b { color: var(--dag-burn-accent); }
}
.dag-burn__scat { grid-area: scat; }
.dag-burn__scbox { flex: 1; min-height: 200px; position: relative; margin: 0 8px 8px; }
.dag-burn__scsvg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dag-burn__gl { stroke: var(--dag-burn-hair); }
  & .dag-burn__ax { fill: var(--dag-burn-faint); font: 500 10px var(--dag-burn-mono); }
  & .dag-burn__axt { fill: var(--dag-burn-mute); font: 600 10px var(--dag-burn-mono); letter-spacing: .06em; text-transform: uppercase; }
  & .dag-burn__zone { fill: var(--dag-burn-bad); opacity: .07; }
  & .dag-burn__diag { stroke: var(--dag-burn-faint); stroke-dasharray: 4 4; }
  & .dag-burn__pt { cursor: pointer; outline: none; }
  & .dag-burn__pt circle { fill: color-mix(in oklch, var(--c) 30%, transparent); stroke: var(--c); stroke-width: 1.75; transition: r .3s var(--dag-burn-spring), fill .2s; }
  & .dag-burn__pt text { fill: var(--dag-burn-mute); font: 600 10.5px system-ui, sans-serif; transition: fill .2s; }
  & .dag-burn__pt .dag-burn__ptin { animation: dag-burn-pop .7s var(--dag-burn-spring) both; animation-delay: calc(var(--i) * 70ms + 150ms); transform-box: fill-box; transform-origin: center; }
  & .dag-burn__pt:is(:hover, :focus-visible, .is-sel) circle { fill: color-mix(in oklch, var(--c) 55%, transparent); stroke-width: 2.5; }
  & .dag-burn__pt:is(:hover, :focus-visible, .is-sel) text { fill: var(--dag-burn-ink); }
  & .dag-burn__pt:focus-visible circle { stroke: var(--dag-burn-ink); }
}
.dag-burn__tbl { grid-area: tbl; }
.dag-burn__tw { flex: 1; min-height: 0; }
.dag-burn__tbl table {
  font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dag-burn-panel); text-align: left; padding: 12px 10px 8px; font: 600 10.5px var(--dag-burn-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dag-burn-faint); border-bottom: 1px solid var(--dag-burn-line); white-space: nowrap; }
  & th:first-child, & td:first-child { padding-left: 16px; }
  & th:last-child, & td:last-child { padding-right: 16px; }
  & th button { font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; display: inline-flex; align-items: center; gap: 4px; border-radius: 4px; transition: color .15s; }
  & th button:hover { color: var(--dag-burn-ink); }
  & th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; border-top-color: currentColor; margin-top: 4px; opacity: 0; transition: opacity .15s, rotate .25s var(--dag-burn-out); }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dag-burn-ink); }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; margin-top: -4px; }
  & td { padding: 9px 10px; border-bottom: 1px solid var(--dag-burn-hair); vertical-align: middle; font-variant-numeric: tabular-nums; }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover, & tbody tr.is-sel { background: var(--dag-burn-hair); }
  & tbody tr:focus-visible { outline: 2px solid var(--dag-burn-accent); outline-offset: -2px; }
  & tfoot td { border-bottom: 0; border-top: 1px solid var(--dag-burn-line); font-weight: 650; color: var(--dag-burn-mute); position: sticky; bottom: 0; background: var(--dag-burn-panel); }
  & .dag-burn__r { text-align: right; }
}
.dag-burn__pj { display: grid; line-height: 1.25; & b { font-weight: 600; } & small { font-size: 11.5px; color: var(--dag-burn-faint); } }
.dag-burn__mono { font-family: var(--dag-burn-mono); font-size: 12px; letter-spacing: -.02em; }
.dag-burn__bc {
  display: block; position: relative; width: 100%; min-width: 92px; height: 10px; border-radius: 5px; background: var(--dag-burn-hair);
  & i { position: absolute; inset: 0 auto 0 0; width: calc(min(var(--b), 1.15) / 1.15 * 100%); border-radius: inherit; background: var(--dag-burn-warm); transform-origin: left; animation: dag-burn-growx .8s var(--dag-burn-out) both; animation-delay: calc(var(--i) * 50ms + 100ms); }
  & b { position: absolute; top: -3px; bottom: -3px; width: 2px; margin-left: -1px; left: calc(var(--c) / 1.15 * 100%); border-radius: 1px; background: var(--dag-burn-accent); box-shadow: 0 0 0 2px var(--dag-burn-panel); }
  & .dag-burn__fee { position: absolute; top: 0; bottom: 0; left: calc(1 / 1.15 * 100%); width: 1px; background: var(--dag-burn-faint); }
  &.is-over i { background: var(--dag-burn-bad); }
}
.dag-burn__bct { display: flex; gap: 8px; white-space: nowrap; justify-content: space-between; font: 500 10.5px var(--dag-burn-mono); color: var(--dag-burn-faint); margin-top: 4px; }
.dag-burn__pill {
  display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px; border-radius: 10px;
  font: 650 10.5px var(--dag-burn-mono); letter-spacing: .02em; white-space: nowrap;
  color: var(--c); background: color-mix(in oklch, var(--c) 14%, transparent);
  &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
}

/* burn view */
.dag-burn__bv {
  grid-template-columns: minmax(0, 1fr) 286px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "proj proj" "chart side";
}
.dag-burn__proj { grid-area: proj; display: flex; align-items: center; gap: 12px 22px; flex-wrap: wrap; }
.dag-burn__pick { display: flex; align-items: center; gap: 6px; min-width: 0; }
.dag-burn__pname { display: grid; min-width: 0; line-height: 1.2; padding: 0 4px; & b { font-size: 15px; font-weight: 650; letter-spacing: -.02em; white-space: nowrap; } & span { font-size: 11.5px; color: var(--dag-burn-faint); white-space: nowrap; } }
.dag-burn__ib {
  width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--dag-burn-mute); flex: none;
  box-shadow: inset 0 0 0 1px var(--dag-burn-line); transition: background-color .15s, color .15s;
  &:hover { background: var(--dag-burn-hair); color: var(--dag-burn-ink); }
  & .dag-burn-i { width: 16px; height: 16px; }
}
.dag-burn__pk {
  display: flex; flex-wrap: wrap; gap: 4px 22px; margin: 0 0 0 auto;
  & div { display: grid; line-height: 1.2; }
  & dt { font-size: 10.5px; color: var(--dag-burn-faint); }
  & dd { font: 600 14px var(--dag-burn-mono); letter-spacing: -.04em; margin: 0; }
  & .is-bad dd { color: var(--dag-burn-bad); }
  & .is-good dd { color: var(--dag-burn-accent); }
  & .is-warm dd { color: var(--dag-burn-warm); }
}
.dag-burn__chartp { grid-area: chart; padding: 12px 6px 6px 8px; }
.dag-burn__key {
  display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 0 8px 6px; font-size: 11.5px; color: var(--dag-burn-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 16px; height: 0; border-top: 2.5px solid var(--c); }
  & .k-burn { --c: var(--dag-burn-warm); }
  & .k-ev { --c: var(--dag-burn-accent); }
  & .k-plan { --c: var(--dag-burn-faint); border-top-style: dashed; border-top-width: 1.5px; }
  & .k-fee { --c: var(--dag-burn-ink); border-top-style: dotted; border-top-width: 2px; }
  & .k-fc { --c: var(--dag-burn-warm); border-top-style: dashed; height: 8px; background: color-mix(in oklch, var(--dag-burn-warm) 20%, transparent); }
}
.dag-burn__cv {
  flex: 1; min-height: 220px; position: relative; border-radius: 8px; cursor: crosshair;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
}
.dag-burn__side { grid-area: side; min-height: 0; display: grid; align-content: start; gap: 12px; }
.dag-burn__whatif {
  padding: 14px 16px 16px; gap: 14px;
  & h3 { font-size: 13.5px; font-weight: 650; }
}
.dag-burn__sl {
  display: grid; gap: 8px; font-size: 12px; color: var(--dag-burn-mute);
  & span { display: flex; justify-content: space-between; gap: 8px; }
  & output { font: 650 12px var(--dag-burn-mono); color: var(--dag-burn-ink); }
  & input { width: 100%; margin: 0; }
}
.dag-burn__cr {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; align-items: center;
  & b { display: block; font-size: 12.5px; font-weight: 600; }
  & small { display: block; font-size: 11.5px; color: var(--dag-burn-faint); line-height: 1.35; }
}
.dag-burn__sw {
  width: 36px; height: 21px; border-radius: 11px; position: relative; flex: none;
  background: var(--dag-burn-line); transition: background-color .2s;
  & i { position: absolute; top: 2.5px; left: 2.5px; width: 16px; height: 16px; border-radius: 50%; background: var(--dag-burn-ink); transition: translate .35s var(--dag-burn-spring); }
  &[aria-checked="true"] { background: var(--dag-burn-accent); }
  &[aria-checked="true"] i { translate: 15px 0; background: var(--dag-burn-bg); }
  &:disabled { opacity: .4; }
}
.dag-burn__bridge { padding: 14px 16px 14px; gap: 8px; & h3 { font-size: 13.5px; font-weight: 650; } }
.dag-burn__wf { position: relative; }
.dag-burn__wfsvg {
  width: 100%; height: auto;
  & .dag-burn__wb { transform-box: fill-box; transform-origin: bottom; animation: dag-burn-growy .7s var(--dag-burn-out) both; animation-delay: calc(var(--i) * 90ms); transition: y .5s var(--dag-burn-out), height .5s var(--dag-burn-out); }
  & .dag-burn__wl { fill: var(--dag-burn-mute); font: 500 9.5px var(--dag-burn-mono); }
  & .dag-burn__wv { fill: var(--dag-burn-ink); font: 650 10px var(--dag-burn-mono); }
  & .dag-burn__wc { stroke: var(--dag-burn-faint); stroke-dasharray: 2 2; }
  & .dag-burn__wt { stroke: var(--dag-burn-accent); stroke-width: 1.5; stroke-dasharray: 4 3; }
}
.dag-burn__wfn { font-size: 12px; color: var(--dag-burn-mute); line-height: 1.45; & b { color: var(--dag-burn-ink); font-weight: 650; } }

/* alerts */
.dag-burn__av { grid-template-columns: minmax(0, 1fr); }
.dag-burn__alerts { padding-bottom: 6px; }
.dag-burn__al {
  padding: 4px 12px 8px; display: grid; gap: 8px; align-content: start;
  &.dag-burn-scroll { flex: 0 1 auto; min-height: 0; }
}
.dag-burn__alert {
  display: grid; grid-template-columns: 4px minmax(0, 1fr) auto; gap: 14px; align-items: center;
  padding: 12px 14px 12px 0; border-radius: 11px; background: var(--dag-burn-raise);
  animation: dag-burn-rise .5s var(--dag-burn-out) both; animation-delay: calc(var(--i) * 60ms);
  & > i { align-self: stretch; border-radius: 0 3px 3px 0; background: var(--c); }
  & h4 { font-size: 13px; font-weight: 620; letter-spacing: -.01em; }
  & p { font-size: 12px; color: var(--dag-burn-mute); margin-top: 2px; }
  & p b { color: var(--dag-burn-ink); font-family: var(--dag-burn-mono); font-weight: 600; font-size: 11.5px; }
  & .dag-burn__aa { display: flex; gap: 6px; }
}
.dag-burn__btn {
  height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600; white-space: nowrap;
  color: var(--dag-burn-ink); box-shadow: inset 0 0 0 1px var(--dag-burn-line); transition: background-color .15s, box-shadow .15s;
  &:hover { background: var(--dag-burn-hair); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dag-burn-ink) 22%, transparent); }
  &.dag-burn__btn--pri { background: var(--dag-burn-ink); color: var(--dag-burn-bg); box-shadow: none; }
  &.dag-burn__btn--pri:hover { background: var(--dag-burn-accent); }
}
.dag-burn__snz {
  margin: 4px 12px 8px; border-top: 1px solid var(--dag-burn-line); padding-top: 8px;
  & summary { cursor: pointer; font: 600 11px var(--dag-burn-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dag-burn-faint); padding: 6px 4px; border-radius: 6px; list-style: none; display: flex; gap: 8px; align-items: center; }
  & summary::-webkit-details-marker { display: none; }
