  &[open] summary::before { rotate: 45deg; }
  & summary:hover { color: var(--dag-burn-ink); }
  & .dag-burn__al { padding: 4px 0 0; }
  & .dag-burn__alert { opacity: .6; }
}
.dag-burn__empty { padding: 26px 16px; text-align: center; color: var(--dag-burn-faint); font-size: 12.5px; }

/* ---------- tooltip & toast ---------- */
.dag-burn__tip {
  position: absolute; left: 0; top: 0; z-index: 40; pointer-events: none;
  min-width: 170px; padding: 9px 11px; border-radius: 10px;
  background: color-mix(in oklch, var(--dag-burn-bg), var(--dag-burn-ink) 13%); color: var(--dag-burn-ink);
  box-shadow: 0 0 0 1px var(--dag-burn-line), 0 16px 34px -14px oklch(0 0 0 / .7);
  font-size: 12px; line-height: 1.45; font-variant-numeric: tabular-nums;
  opacity: 0; transition: opacity .12s;
  &.is-on { opacity: 1; }
  & .dag-burn__tt { display: block; font: 600 10.5px var(--dag-burn-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dag-burn-faint); margin-bottom: 4px; }
  & .dag-burn__tr { display: flex; justify-content: space-between; gap: 18px; }
  & .dag-burn__tr span { color: var(--dag-burn-mute); display: inline-flex; align-items: center; gap: 6px; }
  & .dag-burn__tr i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & .dag-burn__tr b { font: 600 11.5px var(--dag-burn-mono); }
}
.dag-burn__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50; pointer-events: none;
  padding: 10px 16px; border-radius: 10px; max-width: min(440px, calc(100% - 32px));
  background: var(--dag-burn-ink); color: var(--dag-burn-bg); font-size: 12.5px; font-weight: 600;
  translate: -50% 16px; opacity: 0; transition: translate .45s var(--dag-burn-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@keyframes dag-burn-growx { from { transform: scaleX(0); } }
@keyframes dag-burn-growy { from { transform: scaleY(0); } }
@keyframes dag-burn-pop { from { transform: scale(0); opacity: 0; } }
@keyframes dag-burn-rise { from { opacity: 0; transform: translateY(8px); } }

/* scroll-driven fade for long alert lists, only where supported */
@supports (animation-timeline: view()) {
  .dag-burn__al.dag-burn-scroll .dag-burn__alert {
    animation: dag-burn-rise linear both;
    animation-timeline: view();
    animation-range: entry 0% entry 60%;
  }
}

/* ---------- container responsiveness ---------- */
@container dag-burn (max-width: 980px) {
  .dag-burn__bv { grid-template-columns: minmax(0, 1fr) 248px; }
  .dag-burn__pk { margin-left: 0; }
}
@container dag-burn (max-width: 760px) {
  .dag-burn__app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "rail" "top" "main"; }
  .dag-burn__rail { flex-direction: row; justify-content: flex-start; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dag-burn-line); }
  .dag-burn__logo { margin: 0 8px 0 0; }
  .dag-burn__rb { width: auto; grid-auto-flow: column; padding: 7px 10px; gap: 6px; font-size: 12px; }
  .dag-burn__rb[aria-current="page"]::before { display: none; }
  .dag-burn__badge { position: static; }
  .dag-burn__top { padding: 14px 16px 10px; }
  .dag-burn__main { display: block; overflow: auto; padding: 0 16px 16px; scrollbar-width: thin; }
  .dag-burn__view { grid-template-columns: minmax(0, 1fr) !important; grid-template-areas: none !important; grid-template-rows: none !important; }
  .dag-burn__view > * { grid-area: auto !important; }
  .dag-burn__totals { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dag-burn__scbox { min-height: 260px; }
  .dag-burn__tw { max-height: 420px; }
  .dag-burn__cv { min-height: 280px; }
  .dag-burn__chartp { min-height: 330px; }
  .dag-burn__al.dag-burn-scroll { max-height: none; }
}
@container dag-burn (max-width: 460px) {
  .dag-burn__rb span { display: none; }
  .dag-burn__asof { display: none; }
  .dag-burn__tbl th:nth-child(3), .dag-burn__tbl td:nth-child(3) { display: none; }
  .dag-burn__alert { grid-template-columns: 4px minmax(0, 1fr); & .dag-burn__aa { grid-column: 2; } }
}

@media (prefers-reduced-motion: reduce) {
  .dag-burn {
    & *, & *::before, & *::after { animation: none !important; transition-duration: .01ms !important; }
    & .dag-burn__toast, & .dag-burn__tip { transition: opacity .15s !important; }
  }
}

