const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const PCT = (x) => Math.round(x * 100) + '%';
const K = (x) => (x < 0 ? '−' : '') + '£' + (Math.abs(x) >= 99500 ? Math.round(Math.abs(x) / 1000) : (Math.abs(x) / 1000).toFixed(1).replace(/\.0$/, '')) + 'k';
const HR = (x) => Math.round(x).toLocaleString('en-GB') + ' h';

/* ------------------------------------------------------------------ data */
/* Weeks count from Mon 6 Apr 2026. Week 24 (w/c 21 Sep) is the last closed timesheet week. */
const W0 = Date.UTC(2026, 3, 6), NOW = 25;
const wk = (k) => { const d = new Date(W0 + k * 6048e5); return { d: d.getUTCDate(), m: d.getUTCMonth(), label: d.getUTCDate() + ' ' + MON[d.getUTCMonth()] }; };
const fri = (k) => { const d = new Date(W0 + k * 6048e5 - 3 * 864e5); return d.getUTCDate() + ' ' + MON[d.getUTCMonth()]; };
const SC = (t) => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t));
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
/*  id        client                    project                      type          fee    start wks rate cost freelance exp  burned complete  pending change request                    lead */
const RAW = [
  ['vela', 'Vela Insurance', 'Claims app rebuild', 'Fixed fee', 186000, 4, 26, 118, 61, 14000, 3200, .88, .74, { amt: 18000, label: 'Offline claim drafts' }, 'Hana Sato'],
  ['copper', 'Copperleaf Tea', 'Subscription storefront', 'Fixed fee', 94500, 10, 18, 112, 58, 6500, 1800, .70, .76, null, 'Rafi Haddad'],
  ['north', 'Northgate Housing Trust', 'Tenant portal alpha', 'Capped T&M', 128000, 8, 24, 105, 57, 0, 2400, .61, .58, { amt: 12000, label: 'Accessibility audit' }, 'June Okafor'],
  ['marlow', 'Marlow Bikes', 'Bike configurator', 'Fixed fee', 152000, 0, 28, 120, 62, 22000, 5100, .96, .89, null, 'Tomas Reyes'],
  ['ashby', 'Ashby Museum', 'Collections website', 'Fixed fee', 68000, 14, 16, 104, 56, 4800, 900, .52, .60, null, 'Elena Petrov'],
  ['lumen', 'Lumen Dental', 'Booking flow optimisation', 'Capped T&M', 42000, 16, 12, 110, 58, 0, 600, .71, .64, null, 'Priya Banerjee'],
  ['parcel', 'Parcelpoint Logistics', 'Driver app v2', 'Fixed fee', 214000, 12, 30, 116, 60, 26000, 4300, .38, .41, { amt: 24000, label: 'Route-optimisation API' }, 'Felix Brandt']
];
const PROJ = RAW.map((r, n) => {
  const [id, client, name, type, fee, start, weeks, rate, cost, freelance, expenses, bNow, cNow, cr, lead] = r;
  const e = NOW - start, rand = rng(911 + n * 4241);
  const planCum = (j) => fee * SC(j / weeks);
  /* weekly hours shaped like the plan, scaled to land on the burn to date, in half hours */
  const raw = Array.from({ length: e }, (_, j) => (planCum(j + 1) - planCum(j)) * (.82 + rand() * .36));
  const k = bNow * fee / raw.reduce((s, v) => s + v, 0);
  const hours = raw.map((v) => Math.round(v * k / rate * 2) / 2);
  const burnCum = [0];
  hours.forEach((h) => burnCum.push(burnCum[burnCum.length - 1] + h * rate));
  const ref = SC(e / weeks);
  const compCum = [0].concat(Array.from({ length: e }, (_, j) => Math.round(cNow * Math.pow(SC((j + 1) / weeks) / ref, 1.12) * 1000) / 1000));
  return { id, client, name, type, fee, start, weeks, e, rate, cost, freelance, expenses, cr, lead, hours, burnCum, compCum, planCum };
});
const byId = Object.fromEntries(PROJ.map((p) => [p.id, p]));
const FLOOR = .3;

/* Earned value forecasting. Everything on screen derives from here. */
function fc(p, opt = {}) {
  const eff = opt.eff || 0, cr = opt.cr && p.cr ? p.cr.amt : 0;
  const burned = p.burnCum[p.e], c = p.compCum[p.e], ev = c * p.fee, cpi = ev / burned;
  const fee = p.fee + cr, remaining = p.fee * (1 - c) + cr;
  const eac = burned + remaining / cpi * (1 + eff / 100);
  const low = burned + remaining * (1 + eff / 100) / (cpi + .1);
  const high = burned + remaining * (1 + eff / 100) / Math.max(.5, cpi - .1);
  const labour = eac / p.rate * p.cost, margin = fee - labour - p.freelance - p.expenses;
  const sold = p.fee - p.fee / p.rate * p.cost - p.freelance - p.expenses;
  const status = eac > fee * 1.05 || margin / fee < .25 ? 'risk' : cpi < .97 || margin / fee < .33 ? 'watch' : 'ok';
  return { burned, c, ev, cpi, fee, cr, eac, low, high, labour, margin, mpct: margin / fee, sold, spct: sold / p.fee, status, hours: burned / p.rate };
}
const ST = { ok: ['On track', 'var(--dag-burn-accent)'], watch: ['Watch', 'var(--dag-burn-warm)'], risk: ['At risk', 'var(--dag-burn-bad)'] };
const pill = (s) => `<span class="dag-burn__pill" style="--c:${ST[s][1]}">${ST[s][0]}</span>`;

/* ------------------------------------------------------------------ state & helpers */
const S = { view: 'portfolio', unit: 'gbp', sel: 'vela', sort: { key: 'cpi', dir: 1 }, eff: {}, cr: {}, hx: null, snoozed: new Set(), drawP: 1 };
const opt = (p) => ({ eff: S.eff[p.id] || 0, cr: !!S.cr[p.id] });
const tip = $('.dag-burn__tip');
function showTip(html, x, y) {
  tip.innerHTML = html;
  tip.classList.add('is-on');
  const rb = root.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let l = x - rb.left + 16, t = y - rb.top + 16;
  if (l + tw > rb.width - 8) l = x - rb.left - tw - 16;
  if (t + th > rb.height - 8) t = y - rb.top - th - 14;
  tip.style.translate = `${Math.max(8, l)}px ${Math.max(8, t)}px`;
}
const hideTip = () => tip.classList.remove('is-on');
const trow = (l, v, c) => `<div class="dag-burn__tr"><span>${c ? `<i style="--c:${c}"></i>` : ''}${l}</span><b>${v}</b></div>`;
let toastT = 0;
function toast(m) { const t = $('.dag-burn__toast'); t.textContent = m; t.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('is-on'), 2600); }
const money = (p, v) => (S.unit === 'hrs' ? HR(v / p.rate) : K(v));

/* ------------------------------------------------------------------ portfolio */
function renderTotals() {
  let F = 0, B = 0, M = 0, over = 0, risk = 0;
  PROJ.forEach((p) => { const f = fc(p); F += p.fee; B += f.burned; M += f.margin; over += Math.max(0, f.eac - p.fee); if (f.status === 'risk') risk++; });
  const H = PROJ.reduce((s, p) => s + p.fee / p.rate, 0), BH = PROJ.reduce((s, p) => s + p.burnCum[p.e] / p.rate, 0);
  $('.dag-burn__totals').innerHTML = `
    <div><span>Live fees</span><b class="dag-burn-num">${S.unit === 'hrs' ? HR(H) : K(F)}</b><small>${PROJ.length} projects</small></div>
    <div><span>Burned to date</span><b class="dag-burn-num">${S.unit === 'hrs' ? HR(BH) : K(B)}</b><small>${PCT(B / F)} of fees</small></div>
    <div class="${M / F < FLOOR ? 'is-bad' : 'is-good'}"><span>Forecast margin</span><b class="dag-burn-num">${(M / F * 100).toFixed(1)}%</b><small>${K(M)} · floor ${PCT(FLOOR)}</small></div>
    <div class="${over ? 'is-bad' : ''}"><span>Forecast over fee</span><b class="dag-burn-num">${K(over)}</b><small>${risk} project${risk === 1 ? '' : 's'} at risk</small></div>`;
}
const sortVal = { name: (p) => p.client, fee: (p) => p.fee, cpi: (p) => fc(p).cpi, margin: (p) => fc(p).mpct };
function renderTable() {
  const { key, dir } = S.sort;
  const list = PROJ.slice().sort((a, b) => { const x = sortVal[key](a), y = sortVal[key](b); return dir * (typeof x === 'string' ? x.localeCompare(y) : x - y); });
  $('.dag-burn__tbl tbody').innerHTML = list.map((p, i) => {
    const f = fc(p), b = f.burned / p.fee;
    return `<tr data-row="${p.id}" tabindex="0" class="${p.id === S.sel ? 'is-sel' : ''}" aria-label="${p.client}, ${p.name}: open burn-up">
      <td><span class="dag-burn__pj"><b>${p.client}</b><small>${p.name}</small></span></td>
      <td class="dag-burn__r dag-burn__mono">${S.unit === 'hrs' ? HR(p.fee / p.rate) : K(p.fee)}</td>
      <td><span class="dag-burn__bc${b > f.c + .05 ? ' is-over' : ''}" style="--b:${b.toFixed(3)};--c:${f.c};--i:${i}"><i></i><span class="dag-burn__fee"></span><b></b></span><span class="dag-burn__bct"><span>${PCT(b)} burned</span><span>${PCT(f.c)} done</span></span></td>
      <td class="dag-burn__r dag-burn__mono" style="color:${f.cpi < .95 ? 'var(--dag-burn-bad)' : f.cpi < 1 ? 'var(--dag-burn-warm)' : 'var(--dag-burn-accent)'}">${f.cpi.toFixed(2)}</td>
      <td class="dag-burn__r"><span class="dag-burn__mono">${(f.mpct * 100).toFixed(1)}%</span><br>${pill(f.status)}</td>
    </tr>`;
  }).join('');
  let F = 0, B = 0, M = 0;
  PROJ.forEach((p) => { const f = fc(p); F += p.fee; B += f.burned; M += f.margin; });
  $('.dag-burn__tbl tfoot').innerHTML = `<tr><td>Portfolio</td><td class="dag-burn__r dag-burn__mono">${S.unit === 'hrs' ? HR(PROJ.reduce((s, p) => s + p.fee / p.rate, 0)) : K(F)}</td><td class="dag-burn__mono" style="font-size:11px">${PCT(B / F)} of fees burned</td><td></td><td class="dag-burn__r dag-burn__mono">${(M / F * 100).toFixed(1)}%</td></tr>`;
  $$('.dag-burn__tbl th[aria-sort]').forEach((th) => { const k = th.querySelector('[data-sort]').dataset.sort; th.setAttribute('aria-sort', k !== key ? 'none' : dir > 0 ? 'ascending' : 'descending'); });
}
function renderScatter() {
  const box = $('.dag-burn__scbox'), svg = $('.dag-burn__scsvg'), W = box.clientWidth, H = box.clientHeight;
