    ? `<button type="button" class="dag-burn__btn" data-restore="${a.id}">Restore</button>`
    : `<button type="button" class="dag-burn__btn" data-snooze="${a.id}">Snooze 7 days</button><button type="button" class="dag-burn__btn dag-burn__btn--pri" data-openp="${a.p.id}"${a.cr ? ' data-withcr="1"' : ''}>${a.cr ? 'Model it' : 'Open burn-up'}</button>`}</div></li>`;
  $('[data-al="open"]').innerHTML = open.length ? open.map((a, i) => li(a, i, false)).join('') : '<li class="dag-burn__empty">Nothing needs a decision. Snoozed alerts return on Fri 9 Oct.</li>';
  $('[data-al="snoozed"]').innerHTML = sn.map((a, i) => li(a, i, true)).join('') || '<li class="dag-burn__empty">No snoozed alerts</li>';
  $('[data-snc]').textContent = sn.length;
  $('[data-badge]').textContent = open.filter((a) => a.sev !== 'info').length || '';
}

/* ------------------------------------------------------------------ views */
function setView(v) {
  S.view = v;
  $$('[data-go]').forEach((b) => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dag-burn__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  hideTip();
  const p = byId[S.sel];
  $('[data-h]').textContent = v === 'portfolio' ? 'Project profitability' : v === 'burn' ? 'Burn-up & forecast' : 'Alerts';
  $('[data-crumb]').textContent = v === 'burn' ? `Delivery · ${p.client}` : `Delivery · ${PROJ.length} live projects`;
  if (v === 'portfolio') { renderTotals(); renderTable(); renderScatter(); }
  if (v === 'burn') { renderProject(); animateDraw(); }
  if (v === 'alerts') renderAlerts();
}
function openProject(id, withCr) {
  S.sel = id;
  if (withCr) S.cr[id] = true;
  S.hx = null;
  setView('burn');
}
function step(d) {
  const i = PROJ.findIndex((p) => p.id === S.sel);
  S.sel = PROJ[(i + d + PROJ.length) % PROJ.length].id;
  S.hx = null;
  $('[data-crumb]').textContent = `Delivery · ${byId[S.sel].client}`;
  renderProject();
  animateDraw();
}
function setUnit(u) {
  if (S.unit === u) return;
  S.unit = u;
  $$('[data-unit]').forEach((b) => { const on = b.dataset.unit === u; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  if (S.view === 'portfolio') { renderTotals(); renderTable(); }
  if (S.view === 'burn') { renderProject(); drawBurn(); }
  if (S.view === 'alerts') toast(u === 'hrs' ? 'Burn-up and portfolio now measured in hours' : 'Burn-up and portfolio now measured in £ fee');
}

/* ------------------------------------------------------------------ events */
root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if ((el = t.closest('[data-unit]'))) return setUnit(el.dataset.unit);
  if ((el = t.closest('[data-sort]'))) { const k = el.dataset.sort; S.sort = S.sort.key === k ? { key: k, dir: -S.sort.dir } : { key: k, dir: k === 'name' || k === 'cpi' || k === 'margin' ? 1 : -1 }; return renderTable(); }
  if ((el = t.closest('[data-row]'))) return openProject(el.dataset.row);
  if ((el = t.closest('[data-pt]'))) return openProject(el.dataset.pt);
  if ((el = t.closest('[data-step]'))) return step(+el.dataset.step);
  if ((el = t.closest('[data-cr]'))) {
    if (el.disabled) return;
    S.cr[S.sel] = !S.cr[S.sel];
    renderProject(); drawBurn();
    return toast(S.cr[S.sel] ? `Forecast includes the ${K(byId[S.sel].cr.amt)} change request` : 'Change request removed from the forecast');
  }
  if ((el = t.closest('[data-snooze]'))) { S.snoozed.add(el.dataset.snooze); renderAlerts(); return toast('Snoozed until Fri 9 Oct'); }
  if ((el = t.closest('[data-restore]'))) { S.snoozed.delete(el.dataset.restore); renderAlerts(); return toast('Alert restored'); }
  if ((el = t.closest('[data-openp]'))) return openProject(el.dataset.openp, !!el.dataset.withcr);
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if ((e.key === 'Enter' || e.key === ' ') && t.matches && t.matches('[data-row], [data-pt]')) { e.preventDefault(); t.click(); return; }
  const r = t.closest && t.closest('[role="radio"]');
  if (r && /^Arrow(Left|Right|Up|Down)$/.test(e.key)) {
    e.preventDefault();
    const g = $$('[role="radio"]', r.parentElement), i = (g.indexOf(r) + (/Right|Down/.test(e.key) ? 1 : -1) + g.length) % g.length;
    g[i].focus(); g[i].click();
  }
  if (t.closest && t.closest('tbody') && /^Arrow(Up|Down)$/.test(e.key)) {
    const rows = $$('tbody tr[data-row]'), i = rows.indexOf(t.closest('tr'));
    const n = rows[clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, rows.length - 1)];
    if (n) { e.preventDefault(); n.focus(); }
  }
});
root.addEventListener('input', (e) => {
  if (!e.target.matches('[data-effort]')) return;
  S.eff[S.sel] = +e.target.value;
  renderProject();
  drawBurn();
});
root.addEventListener('pointermove', (e) => {
  const t = e.target;
  if (t.closest('.dag-burn__cv')) return;
  let el;
  if ((el = t.closest('[data-pt]'))) {
    const p = byId[el.dataset.pt], f = fc(p);
    return showTip(`<span class="dag-burn__tt">${p.client}</span>${trow('Fee burned', PCT(f.burned / p.fee), 'var(--dag-burn-warm)')}${trow('Complete', PCT(f.c), 'var(--dag-burn-accent)')}${trow('CPI', f.cpi.toFixed(2))}${trow('Forecast margin', (f.mpct * 100).toFixed(1) + '%')}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('.dag-burn__bc'))) {
    const p = byId[el.closest('[data-row]').dataset.row], f = fc(p);
    return showTip(`<span class="dag-burn__tt">${p.client}</span>${trow('Burned', `${money(p, f.burned)} · ${PCT(f.burned / p.fee)}`, 'var(--dag-burn-warm)')}${trow('Earned', `${money(p, f.ev)} · ${PCT(f.c)}`, 'var(--dag-burn-accent)')}${trow('Fee', money(p, p.fee))}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('.dag-burn__wb'))) {
    const p = byId[S.sel], f = fc(p, opt(p)), i = +el.dataset.i;
    const rows = [['Fee', f.fee, f.cr ? `incl. ${K(f.cr)} CR` : p.type], ['Labour at cost', f.labour, `${HR(f.eac / p.rate)} × £${p.cost}/h`], ['Freelancers', p.freelance, 'committed POs'], ['Expenses', p.expenses, 'travel, licences, print'], ['Margin', f.margin, `${(f.mpct * 100).toFixed(1)}% of fee`]][i];
    return showTip(`<span class="dag-burn__tt">${rows[0]}</span>${trow(rows[2], K(rows[1]))}`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerleave', hideTip);

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (S.view === 'portfolio') renderScatter();
  if (S.view === 'burn') drawBurn();
});
ro.observe($('.dag-burn__scbox'));
ro.observe(cvBox);

/* ------------------------------------------------------------------ mount */
$$('[data-unit]').forEach((b) => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
renderAlerts();
setView('portfolio');

css:
.dag-retainer {
  width: 100%;
  height: var(--dag-retainer-h, 680px);
  container-type: inline-size;
  container-name: dag-retainer;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-retainer-bg);
  color: var(--dag-retainer-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-retainer-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-retainer-focus, var(--dag-retainer-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-retainer-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-retainer-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-retainer-num { font-variant-numeric: tabular-nums; }
  & .dag-retainer-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-retainer-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-retainer-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

@property --dag-retainer-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dag-retainer-pace { syntax: "<number>"; inherits: true; initial-value: 0; }

.dag-retainer {
  /* re-theme with these four */
  --dag-retainer-bg: oklch(0.975 0.007 235);
  --dag-retainer-ink: oklch(0.27 0.035 255);
  --dag-retainer-accent: oklch(0.56 0.1 192);
  --dag-retainer-warm: oklch(0.77 0.15 72);
  /* derived */
  --dag-retainer-bad: oklch(0.62 0.19 25);
  --dag-retainer-card: color-mix(in oklch, var(--dag-retainer-bg), white 75%);
  --dag-retainer-line: color-mix(in oklch, var(--dag-retainer-ink) 12%, transparent);
  --dag-retainer-hair: color-mix(in oklch, var(--dag-retainer-ink) 6%, transparent);
  --dag-retainer-mute: color-mix(in oklch, var(--dag-retainer-ink) 68%, var(--dag-retainer-bg));
  --dag-retainer-faint: color-mix(in oklch, var(--dag-retainer-ink) 46%, var(--dag-retainer-bg));
  --dag-retainer-track: color-mix(in oklch, var(--dag-retainer-ink) 9%, var(--dag-retainer-card));
  --dag-retainer-soft: color-mix(in oklch, var(--dag-retainer-accent) 10%, var(--dag-retainer-card));
  --dag-retainer-serif: ui-serif, "New York", "Iowan Old Style", Georgia, serif;
  --dag-retainer-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-retainer-out: cubic-bezier(.22, 1, .36, 1);
  --dag-retainer-spring: linear(0, .06 2.5%, .25 7%, .56 13%, .87 20%, 1.04 26%, 1.09 31%, 1.07 37%, 1.02 47%, .995 60%, 1);
  color-scheme: light;
  border-radius: 18px;
  box-shadow: inset 0 0 0 1px var(--dag-retainer-line);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
}

/* ---------- top bar ---------- */
.dag-retainer__bar {
  display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 12px;
  padding: 12px 18px; border-bottom: 1px solid var(--dag-retainer-line);
}
.dag-retainer__brand {
  display: flex; align-items: center; gap: 10px; min-width: 0;
  & .dag-retainer__mark { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--dag-retainer-ink); color: var(--dag-retainer-card); flex: none; }
  & b { display: block; font: 600 16px/1.1 var(--dag-retainer-serif); letter-spacing: -.01em; white-space: nowrap; }
  & small { display: block; font-size: 11px; color: var(--dag-retainer-faint); }
}
.dag-retainer__tabs {
  display: inline-flex; gap: 2px; padding: 4px; border-radius: 12px; background: var(--dag-retainer-hair);
  & button { height: 32px; padding: 0 14px 0 11px; border-radius: 9px; display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 600; color: var(--dag-retainer-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button .dag-retainer-i { width: 16px; height: 16px; }
  & button:hover { color: var(--dag-retainer-ink); }
  & button[aria-selected="true"] { background: var(--dag-retainer-card); color: var(--dag-retainer-ink); box-shadow: 0 1px 3px -1px color-mix(in oklch, var(--dag-retainer-ink) 35%, transparent), 0 0 0 1px var(--dag-retainer-line); }
  & button[aria-selected="true"] .dag-retainer-i { color: var(--dag-retainer-accent); }
}
.dag-retainer__month { justify-self: end; display: flex; align-items: center; gap: 6px; }
.dag-retainer__ml {
  display: grid; text-align: center; min-width: 136px; line-height: 1.15;
  & b { font: 600 15px var(--dag-retainer-serif); }
  & small { font-size: 11px; color: var(--dag-retainer-faint); }
}
.dag-retainer__ib {
  width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; color: var(--dag-retainer-mute);
  box-shadow: inset 0 0 0 1px var(--dag-retainer-line); transition: background-color .15s, color .15s;
  &:hover:not(:disabled) { background: var(--dag-retainer-hair); color: var(--dag-retainer-ink); }
  &:disabled { opacity: .35; }
  & .dag-retainer-i { width: 16px; height: 16px; }
}

/* ---------- main ---------- */
.dag-retainer__main { min-height: 0; padding: 16px 20px 18px; display: grid; }
.dag-retainer__view { min-height: 0; display: grid; gap: 14px; }
.dag-retainer__panel { min-height: 0; min-width: 0; border-radius: 14px; background: var(--dag-retainer-card); box-shadow: inset 0 0 0 1px var(--dag-retainer-line); display: flex; flex-direction: column; overflow: hidden; }

/* clients */
.dag-retainer__cv { grid-template-rows: auto minmax(0, 1fr); }
.dag-retainer__sum {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0;
  & > div { padding: 2px 18px 2px 0; display: grid; gap: 2px; }
  & > div + div { padding-left: 18px; border-left: 1px solid var(--dag-retainer-line); }
  & span { font-size: 11.5px; color: var(--dag-retainer-mute); }
  & b { font: 500 clamp(22px, 2.6cqi, 30px)/1.05 var(--dag-retainer-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums lining-nums; }
  & small { font-size: 11.5px; color: var(--dag-retainer-faint); }
  & .is-bad b { color: var(--dag-retainer-bad); }
}
.dag-retainer__cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 12px; align-content: start; padding: 2px; margin: -2px; }
.dag-retainer__card {
  display: grid; grid-template-columns: 116px minmax(0, 1fr); grid-template-rows: auto 1fr auto; gap: 4px 16px;
  text-align: left; padding: 16px 16px 14px; border-radius: 15px; background: var(--dag-retainer-card);
  box-shadow: inset 0 0 0 1px var(--dag-retainer-line);
  transition: box-shadow .2s, translate .35s var(--dag-retainer-out);
  animation: dag-retainer-rise .6s var(--dag-retainer-out) both; animation-delay: calc(var(--i) * 60ms);
  &:hover { translate: 0 -2px; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dag-retainer-accent) 45%, var(--dag-retainer-line)), 0 14px 26px -18px color-mix(in oklch, var(--dag-retainer-ink) 60%, transparent); }
  & .dag-retainer__gauge { grid-row: 1 / 4; align-self: center; }
  & .dag-retainer__cn { display: grid; line-height: 1.2; }
  & .dag-retainer__cn b { font: 600 17px var(--dag-retainer-serif); letter-spacing: -.01em; }
  & .dag-retainer__cn small { font-size: 12px; color: var(--dag-retainer-faint); }
  & .dag-retainer__lines { display: grid; gap: 3px; align-content: center; font-size: 12px; color: var(--dag-retainer-mute); }
  & .dag-retainer__lines b { color: var(--dag-retainer-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & .dag-retainer__mini { display: flex; gap: 1.5px; height: 6px; border-radius: 3px; overflow: hidden; margin-top: 6px; }
  & .dag-retainer__mini i { flex: 0 1 var(--w); background: var(--c); }
}
.dag-retainer__state {
  justify-self: start; display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 11px;
  font-size: 11.5px; font-weight: 650; color: var(--c); background: color-mix(in oklch, var(--c) 12%, transparent);
  & svg { width: 12px; height: 12px; }
}

/* gauge: a conic arc whose sweep is a registered number, so it transitions */
.dag-retainer__gauge {
  --dag-retainer-p: 0; --dag-retainer-pace: 0;
  --fill: var(--dag-retainer-accent);
  position: relative; width: 116px; aspect-ratio: 1;
  transition: --dag-retainer-p 1.25s var(--dag-retainer-spring), --dag-retainer-pace .9s var(--dag-retainer-out);
  &.is-warm { --fill: var(--dag-retainer-warm); }
  &.is-over { --fill: var(--dag-retainer-bad); }
  & .dag-retainer__ring, & .dag-retainer__ovr { position: absolute; border-radius: 50%; }
  & .dag-retainer__ring {
    inset: 0;
    background: conic-gradient(from 225deg, var(--fill) 0 calc(min(var(--dag-retainer-p), 1) * 270deg), var(--dag-retainer-track) 0 270deg, transparent 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 10px), #000 calc(100% - 9.5px));
  }
  & .dag-retainer__ovr {
    inset: 14px;
    background: conic-gradient(from 225deg, var(--dag-retainer-bad) 0 calc(max(var(--dag-retainer-p) - 1, 0) * 270deg), transparent 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 4px), #000 calc(100% - 3.5px));
    opacity: .85;
  }
  & .dag-retainer__tick {
    position: absolute; left: calc(50% - 1px); top: -3px; width: 2px; height: calc(50% + 3px); transform-origin: 50% 100%;
    rotate: calc(-135deg + min(var(--dag-retainer-pace), 1) * 270deg);
    background: linear-gradient(var(--dag-retainer-ink) 0 15px, transparent 15px);
    border-radius: 1px;
  }
  & .dag-retainer__gv {
    position: absolute; inset: 0; display: grid; place-content: center; text-align: center; line-height: 1.05;
    & b { font: 500 25px var(--dag-retainer-serif); letter-spacing: -.03em; font-variant-numeric: tabular-nums lining-nums; }
    & small { font-size: 10.5px; color: var(--dag-retainer-faint); margin-top: 3px; }
  }
}

/* detail */
.dag-retainer__dv { grid-template-columns: 188px minmax(0, 1fr) 292px; }
.dag-retainer__clist {
  display: grid; align-content: start; gap: 4px; margin: -2px; padding: 2px;
  & button { display: grid; gap: 5px; text-align: left; padding: 9px 10px; border-radius: 11px; transition: background-color .15s, box-shadow .15s; }
  & button:hover { background: var(--dag-retainer-hair); }
  & button[aria-current="true"] { background: var(--dag-retainer-card); box-shadow: inset 0 0 0 1px var(--dag-retainer-line), 0 4px 12px -10px var(--dag-retainer-ink); }
  & b { font-size: 12.5px; font-weight: 620; display: flex; justify-content: space-between; gap: 8px; }
  & b em { font: 600 11px var(--dag-retainer-mono); font-style: normal; color: var(--dag-retainer-mute); }
  & .dag-retainer__lb { height: 4px; border-radius: 2px; background: var(--dag-retainer-track); overflow: hidden; }
  & .dag-retainer__lb i { display: block; height: 100%; width: calc(min(var(--p), 1) * 100%); background: var(--c); border-radius: inherit; transition: width .6s var(--dag-retainer-out); }
}
.dag-retainer__chartp { padding: 14px 16px 12px; gap: 8px; }
.dag-retainer__dh {
  display: flex; align-items: start; justify-content: space-between; gap: 6px 14px; flex-wrap: wrap;
  & h3 { font: 600 19px/1.15 var(--dag-retainer-serif); letter-spacing: -.015em; }
  & p { font-size: 12px; color: var(--dag-retainer-faint); margin-top: 2px; }
  & p b { color: var(--dag-retainer-ink); font-weight: 650; }
}
.dag-retainer__chart { flex: 1; min-height: 190px; position: relative; cursor: crosshair; border-radius: 8px; }
.dag-retainer__svg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dag-retainer__gl { stroke: var(--dag-retainer-hair); }
  & .dag-retainer__ax { fill: var(--dag-retainer-faint); font: 500 10px var(--dag-retainer-mono); }
  & .dag-retainer__we { fill: var(--dag-retainer-ink); opacity: .028; }
  & .dag-retainer__od { fill: var(--dag-retainer-bad); opacity: .07; }
  & .dag-retainer__al { stroke: var(--dag-retainer-ink); stroke-width: 1.25; stroke-dasharray: 2 3; }
  & .dag-retainer__all { fill: var(--dag-retainer-ink); font: 600 10px var(--dag-retainer-mono); }
  & .dag-retainer__pace { fill: none; stroke: var(--dag-retainer-faint); stroke-width: 1.5; stroke-dasharray: 5 4; }
  & .dag-retainer__used { fill: none; stroke: var(--dag-retainer-accent); stroke-width: 2.5; stroke-linejoin: round; stroke-dasharray: 1; animation: dag-retainer-draw 1.1s var(--dag-retainer-out) both; }
  & .dag-retainer__used.is-over { stroke: var(--dag-retainer-bad); }
  & .dag-retainer__area { fill: var(--dag-retainer-accent); opacity: .1; animation: dag-retainer-fade .8s .3s both; }
  & .dag-retainer__proj { fill: none; stroke: var(--dag-retainer-accent); stroke-width: 2; stroke-dasharray: 4 4; opacity: .7; }
  & .dag-retainer__today { stroke: var(--dag-retainer-ink); stroke-width: 1; opacity: .35; }
  & .dag-retainer__xh { stroke: var(--dag-retainer-ink); opacity: .4; }
  & .dag-retainer__dot { fill: var(--dag-retainer-card); stroke: var(--dag-retainer-accent); stroke-width: 2.25; }
}
.dag-retainer__split {
  display: grid; gap: 7px;
