/*   id        client                   retainer                  h/mo  rate  overage  rollover cap   mix                                                              usage of allowance Jun..Oct      rolled into June */
const RAW = [
  ['copper', 'Copperleaf Tea', 'Always-on social', 60, 95, 110, .1, { content: .35, social: .35, design: .15, report: .05, account: .1 }, [.96, 1.04, .9, 1.08, .12], 2.5],
