/* ------------------------------------------------------------------ detail view */
function renderClientList() {
  $('.dag-retainer__clist').innerHTML = CLIENTS.map((c) => {
    const L = ledger(c)[S.mi], st = status(c, L);
    return `<button type="button" data-pick="${c.id}"${c.id === S.sel ? ' aria-current="true"' : ''}><b>${c.name}<em>${Math.round(L.used / L.allowance * 100)}%</em></b><span class="dag-retainer__lb"><i style="--p:${(L.used / L.allowance).toFixed(3)};--c:${st.c === 'var(--dag-retainer-faint)' ? 'var(--dag-retainer-accent)' : st.c}"></i></span></button>`;
  }).join('');
}
const chart = $('.dag-retainer__chart'), svg = $('.dag-retainer__svg');
let geo = null;
function cumByDay(c) {
