  return { per, cum };
}
function renderDetail() {
  const c = byId[S.sel], M = MONTHS[S.mi], L = ledger(c)[S.mi], st = status(c, L);
  $('.dag-retainer__dh').innerHTML = `<div><h3>${c.name}</h3><p>${c.plan} · ${L.rollIn ? `<b>${c.h} h</b> + <b>${HH(L.rollIn)} h</b> rolled in = <b>${HH(L.allowance)} h</b>` : `<b>${c.h} h</b>, nothing rolled in,`} in ${MONTHN[M.m]} · ${GBP(c.rate)}/h, overage ${GBP(c.over)}/h</p></div><span class="dag-retainer__state" style="--c:${st.c}">${st.t}</span>`;
  renderSplit(L);
  renderChart();
