  $('.dag-retainer__split').innerHTML = mixBar(L, 'dag-retainer__sbar') + `<ul>${keys.map((k) => `<li><i style="--c:${TYPES[k].c}"></i>${TYPES[k].label} <b>${HH(L.byType[k])} h</b></li>`).join('')}</ul>`;
}
function renderChart() {
  const W = chart.clientWidth, H = chart.clientHeight;
  if (!W || !H) return;
