  [1, 8, 15, 22, M.n].forEach((d) => { g += `<text class="dag-retainer__ax" x="${x(d - .5)}" y="${H - 6}" text-anchor="middle">${d} ${MONTHN[M.m].slice(0, 3)}</text>`; });
  g += `<line class="dag-retainer__al" x1="${pad.l}" x2="${W - pad.r}" y1="${y(L.allowance)}" y2="${y(L.allowance)}"/><text class="dag-retainer__all" x="${W - pad.r - 2}" y="${y(L.allowance) - 5}" text-anchor="end">${HH(L.allowance)} h allowance</text>`;
  let pd = '';
