  g += `<path class="dag-retainer__pace" d="${pd}"/>`;
  let ud = `M${x(0)} ${y(0)}`;
  for (let d = 1; d <= last; d++) ud += `L${x(d).toFixed(1)} ${y(cum[d]).toFixed(1)}`;
  g += `<path class="dag-retainer__area" d="${ud}L${x(last)} ${y(0)}Z"/><path class="dag-retainer__used${L.used > L.allowance ? ' is-over' : ''}" pathLength="1" d="${ud}"/>`;
  if (M.today) {
    g += `<line class="dag-retainer__today" x1="${x(last)}" x2="${x(last)}" y1="${pad.t}" y2="${H - pad.b}"/><path class="dag-retainer__proj" d="M${x(last)} ${y(cum[last])}L${x(M.n)} ${y(L.projected)}"/><text class="dag-retainer__all" x="${x(M.n) - 2}" y="${y(L.projected) + (L.projected > L.allowance ? -6 : 13)}" text-anchor="end" style="fill:var(--dag-retainer-accent)">${HH(L.projected)} h at this pace</text>`;
  }
  g += '<g class="dag-retainer__xg"></g>';
