  svg.querySelector('.dag-retainer__xg').innerHTML = `<line class="dag-retainer__xh" x1="${x(d)}" x2="${x(d)}" y1="${pad.t}" y2="${H - pad.b}"/>` + (has ? `<circle class="dag-retainer__dot" cx="${x(d)}" cy="${y(cum[d])}" r="4.5"/>` : '');
  const ents = c.entries[S.mi].filter((e) => e.d === d), types = {};
  ents.forEach((e) => { types[e.type] = (types[e.type] || 0) + e.h; });
  const rb = chart.getBoundingClientRect();
  showTip(`<span class="dag-retainer__tt">${DOW[dt.dow]} ${d} ${MONTHN[M.m]}</span>` +
    (has ? (per[d] ? Object.keys(types).map((k) => trow(TYPES[k].label, HH(types[k]) + ' h', TYPES[k].c)).join('') : trow(dt.dow === 0 || dt.dow === 6 ? 'Weekend' : M.hol.includes(d) ? 'Bank holiday' : 'Nothing logged', '0 h')) +
      trow('Cumulative', HH(cum[d]) + ' h') + trow('Pace', HH(pace) + ' h') + trow(cum[d] >= pace ? 'Ahead of pace' : 'Behind pace', HH(Math.abs(cum[d] - pace)) + ' h')
