chart.addEventListener('pointermove', (e) => {
  if (!geo) return;
  const rb = chart.getBoundingClientRect(), { pad, W, M } = geo;
  cross(Math.ceil((e.clientX - rb.left - pad.l) / ((W - pad.l - pad.r) / M.n)), e.clientX, e.clientY);
});
const clearX = () => { S.hx = null; const xg = svg.querySelector('.dag-retainer__xg'); if (xg) xg.innerHTML = ''; hideTip(); };
chart.addEventListener('pointerleave', clearX);
chart.addEventListener('blur', clearX);
chart.addEventListener('keydown', (e) => {
  if (!geo || !/^(ArrowLeft|ArrowRight|Home|End)$/.test(e.key)) return;
  e.preventDefault();
  cross(e.key === 'Home' ? 1 : e.key === 'End' ? geo.M.n : (S.hx == null ? geo.last : S.hx + (e.key === 'ArrowRight' ? 1 : -1)));
});
function renderLog(newId) {
