/* ------------------------------------------------------------------ statements */
function renderStatements() {
  const M = MONTHS[S.mi], rows = CLIENTS.map((c) => ({ c, L: ledger(c)[S.mi] }));
  $('[data-sttitle]').textContent = `${MONTHN[M.m]} statements`;
  const tot = rows.reduce((a, { L }) => ({ A: a.A + L.allowance, U: a.U + L.used, R: a.R + L.rollOut, X: a.X + L.lapsed, O: a.O + L.overage, G: a.G + L.overGBP }), { A: 0, U: 0, R: 0, X: 0, O: 0, G: 0 });
  $('[data-stsub]').textContent = M.state === 'closed' ? `Closed and invoiced on ${M.invoiced}.` : M.state === 'closing' ? `Closes Mon 5 Oct. ${GBP(tot.G)} of overage to invoice across ${rows.filter((r) => r.L.overage).length} clients.` : 'October is still running — statements are drafted after month end.';
  const bulk = $('[data-bulk]'), pending = rows.filter((r) => !S.approved[r.c.id]).length;
  bulk.hidden = M.state !== 'closing';
  bulk.disabled = S.busy || !pending;
  bulk.textContent = S.busy ? 'Approving…' : pending ? `Approve all (${pending})` : 'All approved';
  bulk.title = pending ? 'Approve every September statement and raise overage invoices' : 'Every September statement is approved';
  $('.dag-retainer__stp tbody').innerHTML = rows.map(({ c, L }, i) => {
    let act;
    if (M.state === 'closed') act = `<span class="dag-retainer__badge">${ICON.ok.replace('<svg', '<svg width="13" height="13"')}Invoiced ${M.invoiced}</span>`;
    else if (M.state === 'open') act = '<span class="dag-retainer__badge">Draft</span>';
    else if (S.approved[c.id]) act = `<button type="button" class="dag-retainer__act is-done" disabled title="Already approved">${L.overage ? `Invoice ${S.approved[c.id]} raised` : 'Approved'}</button>`;
    else act = `<button type="button" class="dag-retainer__act${L.overage ? ' is-pri' : ''}" data-approve="${c.id}">${L.overage ? `Raise ${GBP(L.overGBP)}` : 'Approve'}</button>`;
    return `<tr style="--i:${i}"><td><span class="dag-retainer__cl"><b>${c.name}</b><small>${c.plan}</small></span></td><td class="dag-retainer__r">${c.h} h</td><td class="dag-retainer__r ${L.rollIn ? '' : 'is-muted'}">${HH(L.rollIn)} h</td><td class="dag-retainer__r">${HH(L.used)} h</td><td class="dag-retainer__r ${L.rollOut ? '' : 'is-muted'}">${M.state === 'open' ? '—' : HH(L.rollOut) + ' h'}</td><td class="dag-retainer__r ${L.lapsed ? '' : 'is-muted'}">${M.state === 'open' ? '—' : HH(L.lapsed) + ' h'}</td><td class="dag-retainer__r ${L.overage ? 'is-bad' : 'is-muted'}">${HH(L.overage)} h${L.overage ? ` · ${GBP(L.overGBP)}` : ''}</td><td class="dag-retainer__r">${act}</td></tr>`;
  }).join('');
  $('.dag-retainer__stp tfoot').innerHTML = `<tr><td>${rows.length} retainers</td><td class="dag-retainer__r">${CLIENTS.reduce((s, c) => s + c.h, 0)} h</td><td class="dag-retainer__r">${HH(rows.reduce((s, r) => s + r.L.rollIn, 0))} h</td><td class="dag-retainer__r">${HH(tot.U)} h</td><td class="dag-retainer__r">${M.state === 'open' ? '—' : HH(tot.R) + ' h'}</td><td class="dag-retainer__r">${M.state === 'open' ? '—' : HH(tot.X) + ' h'}</td><td class="dag-retainer__r ${tot.O ? 'is-bad' : ''}">${HH(tot.O)} h · ${GBP(tot.G)}</td><td></td></tr>`;
}
let invNo = 2611;
function approve(id) {
  const c = byId[id], L = ledger(c)[S.mi];
  S.approved[id] = L.overage ? 'INV-' + invNo++ : true;
  return L.overage ? `Invoice ${S.approved[id]} for ${GBP(L.overGBP)} raised to ${c.name}` : `${c.name} September statement approved`;
}
function approveAll() {
  const ids = CLIENTS.filter((c) => !S.approved[c.id]).map((c) => c.id);
  if (!ids.length || S.busy) return;
  S.busy = true;
  const prog = $('.dag-retainer__prog');
  prog.style.setProperty('--dag-retainer-p', 0);
  renderStatements();
  let k = 0;
  const next = () => {
    if (!root.isConnected) return;
    approve(ids[k++]);
    prog.style.setProperty('--dag-retainer-p', k / ids.length);
    if (k < ids.length) { renderStatements(); setTimeout(next, RM ? 0 : 220); return; }
    S.busy = false;
    renderStatements();
    toast(`${ids.length} statements approved · overage invoices raised`);
    setTimeout(() => { if (root.isConnected) prog.style.setProperty('--dag-retainer-p', 0); }, 1200);
  };
  setTimeout(next, RM ? 0 : 160);
}

/* ------------------------------------------------------------------ views */
function setView(v) {
  S.view = v;
  $$('[role="tab"]').forEach((b) => { const on = b.dataset.go === v; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
  $$('.dag-retainer__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  hideTip();
  renderView();
}
function renderView() {
  renderMonth();
  if (S.view === 'clients') renderClients();
  if (S.view === 'detail') { renderClientList(); renderDetail(); }
  if (S.view === 'statements') renderStatements();
}
function stepMonth(d) {
  const n = clamp(S.mi + d, 0, MONTHS.length - 1);
  if (n === S.mi) return;
  S.mi = n; S.hx = null;
  renderView();
}

/* ------------------------------------------------------------------ events */
root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if ((el = t.closest('[data-month]'))) return stepMonth(+el.dataset.month);
  if ((el = t.closest('[data-client]'))) { S.sel = el.dataset.client; return setView('detail'); }
  if ((el = t.closest('[data-pick]'))) { S.sel = el.dataset.pick; S.hx = null; renderClientList(); renderDetail(); $(`[data-pick="${S.sel}"]`).focus({ preventScroll: true }); return; }
  if ((el = t.closest('[data-del]'))) {
    const c = byId[S.sel], id = +el.dataset.del, list = c.entries[S.mi], i = list.findIndex((x) => x.id === id);
    if (i < 0) return;
    const [gone] = list.splice(i, 1);
    renderClientList(); renderDetail();
    return toast(`Removed ${HH(gone.h)} h from ${c.name}`);
  }
  if ((el = t.closest('[data-approve]'))) { const m = approve(el.dataset.approve); renderStatements(); return toast(m); }
  if (t.closest('[data-bulk]')) return approveAll();
});
root.addEventListener('submit', (e) => {
  e.preventDefault();
  const f = e.target, err = $('.dag-retainer__err', f), can = canLog();
  if (!can.ok) return;
  $$('[aria-invalid]', f).forEach((el) => el.removeAttribute('aria-invalid'));
  const h = parseFloat(f.hours.value), note = f.note.value.trim();
  let bad = null;
  if (!(h >= .25 && h <= 10) || Math.abs(h * 4 - Math.round(h * 4)) > 1e-9) bad = [f.hours, 'Hours must be between 0.25 and 10, in quarter hours.'];
  else if (note.length < 3) bad = [f.note, 'Add a short note so the statement makes sense to the client.'];
  if (bad) { bad[0].setAttribute('aria-invalid', 'true'); err.style.color = ''; err.textContent = bad[1]; bad[0].focus(); return; }
  err.textContent = '';
  const c = byId[S.sel], type = f.type.value, ent = { id: ++uid, d: +f.day.value, h, type, who: 'You', note, mine: true };
  c.entries[S.mi].push(ent);
  f.hours.value = ''; f.note.value = '';
  renderClientList();
  const keepDay = f.day.value;
  renderDetail();
  f.day.value = keepDay;
  renderLog(ent.id);
  f.hours.focus();
  toast(`Logged ${HH(h)} h of ${TYPES[type].label.toLowerCase()} to ${c.name}`);
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  const tab = t.closest && t.closest('[role="tab"]');
  if (tab && /^Arrow(Left|Right)$|^Home$|^End$/.test(e.key)) {
    e.preventDefault();
    const tabs = $$('[role="tab"]'), i = tabs.indexOf(tab);
    const n = tabs[e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : (i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length];
    n.focus(); n.click();
  }
  const pk = t.closest && t.closest('[data-pick]');
  if (pk && /^Arrow(Up|Down)$/.test(e.key)) {
    e.preventDefault();
    const all = $$('[data-pick]'), i = all.indexOf(pk);
    const n = all[clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, all.length - 1)];
    if (n !== pk) n.click();
  }
});
root.addEventListener('pointermove', (e) => {
  const t = e.target;
  if (t.closest('.dag-retainer__chart')) return;
  const bar = t.closest('.dag-retainer__sbar i, .dag-retainer__mini i');
  if (bar) {
    const holder = bar.closest('[data-client]') ? byId[bar.closest('[data-client]').dataset.client] : byId[S.sel];
    const L = ledger(holder)[S.mi], k = Object.keys(TYPES).filter((x) => L.byType[x])[Array.prototype.indexOf.call(bar.parentElement.children, bar)];
    if (k) return showTip(`<span class="dag-retainer__tt">${holder.name}</span>${trow(TYPES[k].label, HH(L.byType[k]) + ' h', TYPES[k].c)}${trow('Share of month', Math.round(L.byType[k] / L.used * 100) + '%')}`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerleave', hideTip);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (S.view === 'detail') renderChart();
});
ro.observe(chart);

/* ------------------------------------------------------------------ mount */
$$('[role="tab"]').forEach((b) => { b.tabIndex = b.getAttribute('aria-selected') === 'true' ? 0 : -1; });
renderMonth();
renderClients(true);
/* gauges start at zero, then sweep to their value on the next frame */
const gauges = $$('.dag-retainer__gauge');
const targets = gauges.map((g) => [g.style.getPropertyValue('--dag-retainer-p'), g.style.getPropertyValue('--dag-retainer-pace')]);
if (!RM) {
  gauges.forEach((g) => { g.style.setProperty('--dag-retainer-p', 0); g.style.setProperty('--dag-retainer-pace', 0); });
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    requestAnimationFrame(() => {
      if (!root.isConnected) return;
      gauges.forEach((g, i) => { g.style.transitionDelay = `${i * 70}ms`; g.style.setProperty('--dag-retainer-p', targets[i][0]); g.style.setProperty('--dag-retainer-pace', targets[i][1]); });
      setTimeout(() => gauges.forEach((g) => { g.style.transitionDelay = ''; }), 1600);
    });
  });
}

css:
.dag-invoices {
  width: 100%;
  height: var(--dag-invoices-h, 680px);
  container-type: inline-size;
  container-name: dag-invoices;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-invoices-bg);
  color: var(--dag-invoices-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-invoices-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-invoices-focus, var(--dag-invoices-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-invoices-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-invoices-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-invoices-num { font-variant-numeric: tabular-nums; }
  & .dag-invoices-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-invoices-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-invoices-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

.dag-invoices {
  /* re-theme with these four */
  --dag-invoices-bg: oklch(0.985 0.003 250);
  --dag-invoices-ink: oklch(0.22 0.02 262);
  --dag-invoices-accent: oklch(0.5 0.18 256);
  --dag-invoices-late: oklch(0.62 0.21 33);
  /* derived */
  --dag-invoices-card: oklch(1 0 0);
  --dag-invoices-side: color-mix(in oklch, var(--dag-invoices-bg), var(--dag-invoices-ink) 3.5%);
  --dag-invoices-line: color-mix(in oklch, var(--dag-invoices-ink) 11%, transparent);
  --dag-invoices-hair: color-mix(in oklch, var(--dag-invoices-ink) 5.5%, transparent);
  --dag-invoices-mute: color-mix(in oklch, var(--dag-invoices-ink) 66%, var(--dag-invoices-bg));
  --dag-invoices-faint: color-mix(in oklch, var(--dag-invoices-ink) 44%, var(--dag-invoices-bg));
  --dag-invoices-b0: oklch(0.71 0.12 245);
  --dag-invoices-b1: oklch(0.8 0.14 82);
  --dag-invoices-b2: oklch(0.71 0.17 55);
  --dag-invoices-b3: var(--dag-invoices-late);
  --dag-invoices-b4: oklch(0.47 0.17 25);
  --dag-invoices-good: oklch(0.58 0.13 158);
  --dag-invoices-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-invoices-out: cubic-bezier(.2, .9, .25, 1);
  --dag-invoices-spring: linear(0, .1 3.5%, .37 9%, .72 15.5%, .97 22%, 1.08 28%, 1.09 33%, 1.05 40%, 1.01 51%, .997 64%, 1);
  color-scheme: light;
  border-radius: 14px;
  box-shadow: inset 0 0 0 1px var(--dag-invoices-line);
}

.dag-invoices__app {
  height: 100%;
  display: grid;
  grid-template-columns: 196px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "side top" "side kpis" "side main";
}

/* ---------- sidebar ---------- */
.dag-invoices__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 14px;
  background: var(--dag-invoices-side); border-right: 1px solid var(--dag-invoices-line); border-radius: 14px 0 0 14px;
}
.dag-invoices__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px;
  & .dag-invoices__mark { width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; color: var(--dag-invoices-card); background: var(--dag-invoices-accent); flex: none; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.03em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dag-invoices-faint); }
}
.dag-invoices__nav {
  display: grid; gap: 2px;
  & button { height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 8px; font-weight: 580; color: var(--dag-invoices-mute); transition: background-color .15s, color .15s; }
  & button span { flex: 1; text-align: left; }
  & button em { font: 650 10.5px var(--dag-invoices-mono); font-style: normal; padding: 1px 6px; border-radius: 99px; color: var(--dag-invoices-card); background: var(--dag-invoices-late); }
  & button em:empty { display: none; }
  & button:hover { background: var(--dag-invoices-hair); color: var(--dag-invoices-ink); }
  & button[aria-current="page"] { color: var(--dag-invoices-accent); background: color-mix(in oklch, var(--dag-invoices-accent) 9%, transparent); }
}
.dag-invoices__bank {
  margin-top: auto; display: grid; gap: 2px; padding: 12px; border-radius: 10px; background: var(--dag-invoices-card); box-shadow: 0 0 0 1px var(--dag-invoices-line);
  & span { font-size: 11px; color: var(--dag-invoices-faint); }
  & b { font: 650 17px var(--dag-invoices-mono); letter-spacing: -.04em; }
  & small { font-size: 11px; color: var(--dag-invoices-mute); }
}

/* ---------- header & kpis ---------- */
.dag-invoices__top { grid-area: top; display: flex; align-items: end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; padding: 18px 22px 12px; }
.dag-invoices__eb { font: 600 10.5px var(--dag-invoices-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dag-invoices-faint); }
.dag-invoices__top h2 { font-size: clamp(19px, 2.3cqi, 27px); font-weight: 780; letter-spacing: -.045em; line-height: 1.05; margin-top: 4px; }
.dag-invoices__search {
  display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px; border-radius: 9px; width: min(280px, 100%);
  background: var(--dag-invoices-card); box-shadow: inset 0 0 0 1px var(--dag-invoices-line); color: var(--dag-invoices-faint);
  transition: box-shadow .15s;
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dag-invoices-accent), 0 0 0 3px color-mix(in oklch, var(--dag-invoices-accent) 16%, transparent); }
  & input { border: 0; outline: 0; background: none; flex: 1; min-width: 0; font-size: 12.5px; color: var(--dag-invoices-ink); }
  & .dag-invoices-i { width: 16px; height: 16px; }
}
.dag-invoices__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; padding: 0 22px 12px;
  & > div { padding: 11px 14px 12px; border-radius: 11px; background: var(--dag-invoices-card); box-shadow: inset 0 0 0 1px var(--dag-invoices-line); display: grid; gap: 2px; }
  & span { font-size: 11.5px; font-weight: 560; color: var(--dag-invoices-mute); }
  & b { font: 650 clamp(18px, 2.1cqi, 23px)/1.1 var(--dag-invoices-mono); letter-spacing: -.05em; }
  & small { font-size: 11.5px; color: var(--dag-invoices-faint); }
  & .is-late b { color: var(--dag-invoices-late); }
}

/* ---------- main ---------- */
.dag-invoices__main { grid-area: main; min-height: 0; padding: 0 22px 18px; display: grid; }
.dag-invoices__view { min-height: 0; display: grid; gap: 12px; }
.dag-invoices__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dag-invoices-card); box-shadow: inset 0 0 0 1px var(--dag-invoices-line); overflow: hidden; }
.dag-invoices__ph {
  padding: 12px 16px 8px;
  & h3 { font-size: 13.5px; font-weight: 700; letter-spacing: -.015em; }
  & p { font-size: 11.5px; color: var(--dag-invoices-faint); margin-top: 1px; }
  &.dag-invoices__ph--row { display: flex; justify-content: space-between; align-items: start; gap: 10px; flex-wrap: wrap; }
}
.dag-invoices__ov { grid-template-columns: minmax(0, 1fr) 286px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "age age" "strip chase"; }
.dag-invoices__agep { grid-area: age; display: grid; grid-template-columns: 180px minmax(0, 1fr); align-items: center; }
.dag-invoices__age {
  display: grid; gap: 8px; padding: 12px 14px 12px 0;
  & .dag-invoices__abar { display: flex; gap: 2px; height: 10px; border-radius: 5px; overflow: hidden; }
  & .dag-invoices__abar i { flex: 0 1 var(--w); background: var(--c); transition: opacity .2s, flex-basis .6s var(--dag-invoices-out); transform-origin: left; animation: dag-invoices-growx .8s var(--dag-invoices-out) both; animation-delay: calc(var(--i) * 70ms); }
  & .dag-invoices__bands { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
  & .dag-invoices__band {
    display: grid; gap: 1px; text-align: left; padding: 7px 10px 8px; border-radius: 9px; position: relative;
    box-shadow: inset 0 0 0 1px var(--dag-invoices-line); transition: background-color .15s, box-shadow .15s;
    &::before { content: ""; position: absolute; left: 10px; right: 10px; top: 0; height: 2.5px; border-radius: 0 0 2px 2px; background: var(--c); }
    & span { font-size: 11px; font-weight: 600; color: var(--dag-invoices-mute); }
    & b { font: 650 14px var(--dag-invoices-mono); letter-spacing: -.04em; }
    & small { font-size: 10.5px; color: var(--dag-invoices-faint); }
    &:hover { background: var(--dag-invoices-hair); }
    &[aria-pressed="true"] { background: color-mix(in oklch, var(--c) 12%, var(--dag-invoices-card)); box-shadow: inset 0 0 0 1.5px var(--c); }
  }
  &:has([aria-pressed="true"]) .dag-invoices__abar i:not(.is-on) { opacity: .2; }
}
.dag-invoices__flt {
  display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 4px 0 10px; border-radius: 12px;
  font-size: 11.5px; font-weight: 600; color: var(--dag-invoices-ink); background: color-mix(in oklch, var(--c, var(--dag-invoices-accent)) 14%, transparent);
  & button { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; color: var(--dag-invoices-mute); }
  & button:hover { background: color-mix(in oklch, var(--dag-invoices-ink) 10%, transparent); color: var(--dag-invoices-ink); }
  & svg { width: 11px; height: 11px; }
}
.dag-invoices__stripp { grid-area: strip; }
.dag-invoices__strip { flex: 1; min-height: 240px; position: relative; margin: 0 8px 6px; }
.dag-invoices__ssvg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dag-invoices__lane { stroke: var(--dag-invoices-hair); }
  & .dag-invoices__ln { fill: var(--dag-invoices-mute); font: 600 10.5px system-ui, sans-serif; }
  & .dag-invoices__bandbg { opacity: .07; }
  & .dag-invoices__bandl { font: 650 9.5px var(--dag-invoices-mono); letter-spacing: .04em; text-transform: uppercase; }
  & .dag-invoices__ax { fill: var(--dag-invoices-faint); font: 500 10px var(--dag-invoices-mono); }
  & .dag-invoices__today { stroke: var(--dag-invoices-ink); stroke-width: 1.5; }
  & .dag-invoices__todayl { fill: var(--dag-invoices-ink); font: 700 10px var(--dag-invoices-mono); letter-spacing: .06em; }
  & .dag-invoices__dot { cursor: pointer; outline: none; transition: opacity .25s; }
  & .dag-invoices__dot .dag-invoices__dc { animation: dag-invoices-drop .75s var(--dag-invoices-spring) both; animation-delay: calc(var(--i) * 28ms + 120ms); transform-box: fill-box; transform-origin: center; }
  & .dag-invoices__dot circle { fill: color-mix(in oklch, var(--c) 72%, transparent); stroke: var(--c); stroke-width: 1.5; transition: stroke-width .15s, fill .15s; }
  & .dag-invoices__dot .dag-invoices__part { fill: var(--dag-invoices-card); stroke: none; opacity: .85; }
  & .dag-invoices__dot.is-disputed circle:first-child { stroke-dasharray: 3 2.5; stroke-width: 2; fill: color-mix(in oklch, var(--c) 40%, transparent); }
  & .dag-invoices__dot:is(:hover, :focus-visible) circle:first-child { stroke: var(--dag-invoices-ink); stroke-width: 2.5; }
  & .dag-invoices__dot.is-dim { opacity: .14; }
}
.dag-invoices__chase { grid-area: chase; }
.dag-invoices__cl {
  flex: 1; min-height: 0; padding: 0 10px 10px; display: grid; align-content: start; gap: 6px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px; padding: 9px 10px; border-radius: 10px; background: var(--dag-invoices-side); animation: dag-invoices-rise .5s var(--dag-invoices-out) both; animation-delay: calc(var(--i) * 60ms + 200ms); }
  & .dag-invoices__cn { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dag-invoices__ca { font: 650 12.5px var(--dag-invoices-mono); text-align: right; letter-spacing: -.03em; }
  & .dag-invoices__cm { font-size: 11px; color: var(--dag-invoices-faint); display: flex; gap: 6px; align-items: center; min-width: 0; }
  & .dag-invoices__cm b { color: var(--c); font-weight: 650; white-space: nowrap; }
}
.dag-invoices__mini {
  height: 24px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 650; white-space: nowrap;
  color: var(--dag-invoices-accent); background: color-mix(in oklch, var(--dag-invoices-accent) 9%, transparent); transition: background-color .15s, color .15s;
  &:hover:not(:disabled) { background: var(--dag-invoices-accent); color: var(--dag-invoices-card); }
  &:disabled { color: var(--dag-invoices-good); background: color-mix(in oklch, var(--dag-invoices-good) 10%, transparent); }
}

/* list */
.dag-invoices__lv { grid-template-columns: minmax(0, 1fr); }
.dag-invoices__tbar { display: flex; align-items: center; gap: 8px 12px; flex-wrap: wrap; padding: 10px 12px; border-bottom: 1px solid var(--dag-invoices-line); min-height: 52px; }
.dag-invoices__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dag-invoices-hair);
  & button { height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dag-invoices-mute); white-space: nowrap; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dag-invoices-ink); }
  & button[aria-checked="true"] { background: var(--dag-invoices-card); color: var(--dag-invoices-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dag-invoices-ink) 18%, transparent), 0 0 0 1px var(--dag-invoices-line); }
}
.dag-invoices__bulk {
  display: none; align-items: center; gap: 6px; margin-left: auto; padding: 3px 3px 3px 12px; border-radius: 10px; background: var(--dag-invoices-ink); color: var(--dag-invoices-card);
  & > span { font-size: 12px; font-weight: 600; margin-right: 4px; white-space: nowrap; }
  & .dag-invoices__btn { background: color-mix(in oklch, var(--dag-invoices-card) 14%, transparent); color: var(--dag-invoices-card); box-shadow: none; }
  & .dag-invoices__btn:hover:not(:disabled) { background: var(--dag-invoices-accent); }
  & .dag-invoices__btn--ghost { background: none; }
}
.dag-invoices__tblp:has(tbody input:checked) .dag-invoices__bulk { display: flex; animation: dag-invoices-rise .3s var(--dag-invoices-out); }
.dag-invoices__btn {
  height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 650; white-space: nowrap;
  box-shadow: inset 0 0 0 1px var(--dag-invoices-line); transition: background-color .15s, color .15s;
  &:hover:not(:disabled) { background: var(--dag-invoices-hair); }
  &:disabled { opacity: .55; }
  &.dag-invoices__btn--pri { background: var(--dag-invoices-accent); color: var(--dag-invoices-card); box-shadow: none; }
  &.dag-invoices__btn--pri:hover:not(:disabled) { background: color-mix(in oklch, var(--dag-invoices-accent), var(--dag-invoices-ink) 25%); }
}
.dag-invoices__tw { flex: 1; min-height: 0; }
.dag-invoices__tblp table {
  font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dag-invoices-card); text-align: left; padding: 10px 10px 8px; font-size: 11px; font-weight: 650; color: var(--dag-invoices-faint); border-bottom: 1px solid var(--dag-invoices-line); white-space: nowrap; }
  & th button { font: inherit; color: inherit; display: inline-flex; gap: 4px; align-items: center; }
  & th button:hover { color: var(--dag-invoices-ink); }
  & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dag-invoices-ink); }
  & th[aria-sort="ascending"] button::after { content: "↑"; }
  & th[aria-sort="descending"] button::after { content: "↓"; }
  & td { padding: 9px 10px; border-bottom: 1px solid var(--dag-invoices-hair); white-space: nowrap; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dag-invoices-hair); }
  & tbody tr:has(input:checked) { background: color-mix(in oklch, var(--dag-invoices-accent) 7%, transparent); }
  & .dag-invoices__ck { width: 36px; padding-left: 14px; }
  & input[type="checkbox"] { width: 15px; height: 15px; margin: 0; vertical-align: middle; cursor: pointer; }
  & .dag-invoices__r { text-align: right; }
  & .dag-invoices__no { font: 600 12px var(--dag-invoices-mono); color: var(--dag-invoices-accent); border-radius: 4px; }
  & .dag-invoices__no:hover { text-decoration: underline; text-underline-offset: 3px; }
  & .dag-invoices__cc { display: grid; line-height: 1.25; & b { font-weight: 600; } & small { font-size: 11.5px; color: var(--dag-invoices-faint); } }
  & .dag-invoices__amt { font: 600 12.5px var(--dag-invoices-mono); letter-spacing: -.03em; }
  & .dag-invoices__amt small { display: block; font-size: 10.5px; color: var(--dag-invoices-faint); }
  & tbody tr.is-paidnow { animation: dag-invoices-flash 1.2s ease-out; }
}
.dag-invoices__chip {
  display: inline-flex; align-items: center; gap: 5px; height: 21px; padding: 0 8px; border-radius: 6px;
  font-size: 11.5px; font-weight: 650; color: color-mix(in oklch, var(--c), var(--dag-invoices-ink) 25%); background: color-mix(in oklch, var(--c) 15%, transparent);
  &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
}
.dag-invoices__empty { padding: 30px 12px; text-align: center; color: var(--dag-invoices-faint); }

/* cash */
.dag-invoices__cv { grid-template-columns: minmax(0, 1fr); }
.dag-invoices__ckey {
  display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dag-invoices-mute);
