  & .dag-invoices__cb { transform-box: fill-box; transform-origin: bottom; animation: dag-invoices-growy .7s var(--dag-invoices-out) both; animation-delay: calc(var(--i) * 40ms); transition: opacity .15s; }
  & .dag-invoices__cost { stroke: var(--dag-invoices-ink); stroke-width: 1.5; stroke-dasharray: 5 4; opacity: .7; }
  & .dag-invoices__divl { stroke: var(--dag-invoices-ink); opacity: .3; }
  & .dag-invoices__sel { fill: var(--dag-invoices-ink); opacity: .05; transition: x .18s var(--dag-invoices-out), opacity .15s; }
  & .dag-invoices__vl { fill: var(--dag-invoices-ink); font: 650 10px var(--dag-invoices-mono); }
}

/* ---------- drawer ---------- */
.dag-invoices__scrim { position: absolute; inset: 0; z-index: 20; border-radius: 14px; cursor: pointer; background: color-mix(in oklch, var(--dag-invoices-ink) 20%, transparent); transition: opacity .3s; @starting-style { opacity: 0; } }
.dag-invoices__drawer {
  position: absolute; z-index: 21; top: 0; right: 0; bottom: 0; width: min(380px, 100%);
  display: flex; flex-direction: column; background: var(--dag-invoices-card); border-radius: 0 14px 14px 0;
  box-shadow: -1px 0 0 var(--dag-invoices-line), -24px 0 50px -24px color-mix(in oklch, var(--dag-invoices-ink) 45%, transparent);
