  & h3 { font-size: 17px; font-weight: 750; letter-spacing: -.03em; margin-top: 2px; }
  & small { font-size: 12px; color: var(--dag-invoices-mute); }
}
.dag-invoices__x { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--dag-invoices-mute); flex: none; &:hover { background: var(--dag-invoices-hair); color: var(--dag-invoices-ink); } }
.dag-invoices__db { flex: 1; min-height: 0; padding: 14px 16px; display: grid; align-content: start; gap: 16px; }
.dag-invoices__damt {
