}
@container dag-invoices (max-width: 760px) {
  .dag-invoices__app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "side" "top" "main"; }
  .dag-invoices__side { flex-direction: row; justify-content: space-between; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dag-invoices-line); border-radius: 14px 14px 0 0; }
  .dag-invoices__nav { display: flex; gap: 4px; }
  .dag-invoices__top { padding: 14px 16px 10px; }
  .dag-invoices__search { width: 100%; }
  .dag-invoices__kpis { grid-auto-flow: column; grid-template-columns: none; grid-auto-columns: minmax(168px, 1fr); overflow-x: auto; scrollbar-width: none; padding: 0 16px 10px; & > div { padding: 9px 12px; } }
  .dag-invoices__app { grid-template-areas: "side" "top" "kpis" "main"; grid-template-rows: auto auto auto minmax(0, 1fr); }
  .dag-invoices__main { display: block; overflow: auto; padding: 0 16px 16px; scrollbar-width: thin; }
  .dag-invoices__view { gap: 12px; }
  .dag-invoices__ov { grid-template-columns: minmax(0, 1fr); grid-template-areas: "age" "strip" "chase"; }
  .dag-invoices__age .dag-invoices__bands { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .dag-invoices__strip { min-height: 330px; }
  .dag-invoices__tw { max-height: 460px; }
  .dag-invoices__cash { min-height: 300px; }
  .dag-invoices__bulk { margin-left: 0; flex-wrap: wrap; }
}
@container dag-invoices (max-width: 460px) {
  .dag-invoices__age .dag-invoices__bands { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dag-invoices__tblp th:nth-child(3), .dag-invoices__tblp td:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dag-invoices {
    & *, & *::before, & *::after { animation: none !important; transition-duration: .01ms !important; }
    & .dag-invoices__toast, & .dag-invoices__tip, & .dag-invoices__drawer, & .dag-invoices__scrim { transition: opacity .15s !important; }
  }
}

