    else INV.filter(isOpen).forEach((v) => {
      const d = dpd(v);
      if (d <= 0 && v.due >= s && v.due <= e) due += balance(v) * RECOVER[0];
      if (d > 0 && !v.disputed && (k === 1 || k === 2)) rec += balance(v) * RECOVER[band(v).k] / 2;
