  const ws = weeks(), pad = { l: 46, r: 12, t: 16, b: 34 };
  const top = Math.max(COSTS, ...ws.map((w) => w.tot)) * 1.12, step = top > 80000 ? 20000 : 10000, ymax = Math.ceil(top / step) * step;
  const slot = (W - pad.l - pad.r) / ws.length, bw = Math.min(46, slot * .62);
  const y = (v) => pad.t + (1 - v / ymax) * (H - pad.t - pad.b);
  cgeo = { ws, slot, pad, W, H, y };
  let g = '';
  for (let v = 0; v <= ymax + 1; v += step) g += `<line class="dag-invoices__gl" x1="${pad.l}" x2="${W - pad.r}" y1="${y(v)}" y2="${y(v)}"/><text class="dag-invoices__ax" x="${pad.l - 6}" y="${y(v) + 3.5}" text-anchor="end">${v ? '€' + v / 1000 + 'k' : '0'}</text>`;
  g += `<rect class="dag-invoices__sel" x="${pad.l + (S.hx ?? 0) * slot}" y="${pad.t}" width="${slot}" height="${H - pad.t - pad.b}" rx="4" style="opacity:${S.hx == null ? 0 : ''}"/>`;
  ws.forEach((w, i) => {
    const x0 = pad.l + i * slot + (slot - bw) / 2;
    if (w.past) g += `<rect class="dag-invoices__cb" x="${x0}" y="${y(w.col)}" width="${bw}" height="${y(0) - y(w.col)}" rx="3" style="--i:${i};fill:var(--dag-invoices-accent)"/>`;
    else {
      g += `<rect class="dag-invoices__cb" x="${x0}" y="${y(w.due)}" width="${bw}" height="${y(0) - y(w.due)}" rx="3" style="--i:${i};fill:color-mix(in oklch, var(--dag-invoices-b0) 50%, var(--dag-invoices-card));stroke:var(--dag-invoices-b0);stroke-width:1.25"/>`;
      if (w.rec) g += `<rect class="dag-invoices__cb" x="${x0}" y="${y(w.due + w.rec)}" width="${bw}" height="${y(w.due) - y(w.due + w.rec)}" rx="3" style="--i:${i};fill:var(--dag-invoices-late);opacity:.75"/>`;
