    const d = dt(w.s);
    g += `<text class="dag-invoices__ax" x="${x0 + bw / 2}" y="${H - 18}" text-anchor="middle">${d.getUTCDate()}</text>${d.getUTCDate() <= 7 || i === 0 ? `<text class="dag-invoices__ax" x="${x0 + bw / 2}" y="${H - 5}" text-anchor="middle" style="font-weight:650">${MON[d.getUTCMonth()]}</text>` : ''}`;
