  const ev = [{ off: v.issued, t: `<b>Issued</b> · Net ${v.terms}`, c: 'var(--dag-invoices-faint)' }];
  if (v.viewed != null) ev.push({ off: v.viewed, t: '<b>Opened</b> by the client', c: 'var(--dag-invoices-faint)' });
  ev.push({ off: v.due, t: '<b>Due</b>', c: 'var(--dag-invoices-ink)', fut: v.due > 0 });
  v.rem.forEach((r, i) => ev.push({ off: r, t: `<b>Reminder ${i + 1}</b> emailed`, c: 'var(--dag-invoices-b1)', k: 'rem' + i }));
  v.part.forEach((p) => ev.push({ off: p.off, t: `<b>Part payment</b> ${EUR(p.amt)}`, c: 'var(--dag-invoices-good)' }));
  if (v.disputed) ev.push({ off: v.rem[v.rem.length - 1] ?? v.due, t: `<b>Disputed</b> — ${v.disputed}`, c: 'var(--dag-invoices-late)' });
  if (v.paidOn != null) ev.push({ off: v.paidOn, t: `<b>Paid</b> ${EUR(v.amount - paidSum(v))}`, c: 'var(--dag-invoices-good)', k: 'paid' });
