    <div class="dag-invoices__db dag-invoices-scroll">
      <div class="dag-invoices__damt"><strong class="dag-invoices-num">${EUR(isOpen(v) ? balance(v) : v.amount)}</strong><div>${chip(v)}${v.part.length && isOpen(v) ? ` <small style="color:var(--dag-invoices-faint);font-size:12px">of ${EUR(v.amount)} invoiced</small>` : ''}</div>
        <div class="dag-invoices__dmeta"><div><span>Issued</span><b>${D(v.issued)}</b></div><div><span>Due</span><b>${D(v.due)}</b></div><div><span>Terms</span><b>Net ${v.terms}</b></div></div></div>
      <ol class="dag-invoices__tl">${ev.map((e) => `<li class="${e.k && e.k === newEv ? 'is-new' : ''}" style="--c:${e.c}"><i></i><span>${e.t}${e.fut ? ' <em style="font-style:normal;color:var(--dag-invoices-faint)">(upcoming)</em>' : ''}</span><time>${D(e.off)}</time></li>`).join('')}</ol>
