/* ------------------------------------------------------------------ actions */
function remind(no) {
  const v = byNo[no];
  if (!v || !isOpen(v) || v.rem.includes(0) || v.disputed) return false;
  v.rem.push(0);
  return true;
}
function pay(no) {
