  if (S.view === 'list') { renderAgeing(); renderTable(flash); }
  if (S.view === 'cash') renderCash();
  if (S.open) renderDrawer(flash && flash.ev);
}
function bulk(kind) {
  const picked = INV.filter((v) => S.sel.has(v.no) && isOpen(v));
  if (!picked.length || S.busy) return;
  if (kind === 'paid') {
    const sum = picked.reduce((s, v) => s + pay(v.no), 0);
    refresh(picked.map((v) => v.no));
    toast(`${picked.length} invoice${picked.length === 1 ? '' : 's'} marked paid · ${EUR(sum)}`);
    return;
  }
  const todo = picked.filter((v) => !v.rem.includes(0) && !v.disputed);
  if (!todo.length) { toast('Everything selected was already chased today or is on hold'); return; }
  S.busy = true;
  let k = 0;
  const lab = $('[data-selsum]');
  lab.textContent = `Sending 0 of ${todo.length}…`;
  syncSel();
  const next = () => {
    if (!root.isConnected) return;
    remind(todo[k++].no);
    lab.textContent = `Sending ${k} of ${todo.length}…`;
    if (k < todo.length) { setTimeout(next, RM ? 0 : 200); return; }
    S.busy = false;
    S.sel.clear();
    refresh();
    toast(`${todo.length} reminder${todo.length === 1 ? '' : 's'} sent${picked.length > todo.length ? ` · ${picked.length - todo.length} skipped (already chased or disputed)` : ''}`);
  };
  setTimeout(next, RM ? 0 : 200);
}

/* ------------------------------------------------------------------ views */
function setView(v) {
  S.view = v;
  $$('[data-go]').forEach((b) => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dag-invoices__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  $('[data-title]').textContent = v === 'overview' ? 'Who owes us, and since when' : v === 'list' ? 'Invoices' : 'Cash in, week by week';
  S.hx = null;
  hideTip();
  refresh();
}
function setBand(k) {
