  if (S.band != null && S.view === 'list' && S.st === 'paid') { S.st = 'open'; $$('[data-st]').forEach((b) => b.setAttribute('aria-checked', b.dataset.st === 'open')); }
  refresh();
}

/* ------------------------------------------------------------------ events */
root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if ((el = t.closest('[data-band]'))) return setBand(+el.dataset.band);
  if ((el = t.closest('[data-st]'))) { S.st = el.dataset.st; $$('[data-st]').forEach((b) => { const on = b === el; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); return renderTable(); }
  if ((el = t.closest('[data-sort]'))) { const k = el.dataset.sort; S.sort = S.sort.key === k ? { key: k, dir: -S.sort.dir } : { key: k, dir: k === 'amount' ? -1 : 1 }; return renderTable(); }
  if ((el = t.closest('[data-inv]'))) return openDrawer(el.dataset.inv, el);
  if ((el = t.closest('[data-open]'))) return openDrawer(el.dataset.open, el);
  if ((el = t.closest('[data-remind]'))) {
    const no = el.dataset.remind;
    if (remind(no)) { refresh({ ev: 'rem' + (byNo[no].rem.length - 1) }); toast(`Reminder emailed to ${CLIENTS[byNo[no].client]} for ${no}`); }
    return;
  }
  if ((el = t.closest('[data-pay]'))) { const no = el.dataset.pay, amt = pay(no); refresh(Object.assign([no], { ev: 'paid' })); return toast(`${no} marked paid · ${EUR(amt)}`); }
  if ((el = t.closest('[data-bulk]'))) {
    if (el.dataset.bulk === 'clear') { S.sel.clear(); renderTable(); return; }
    return bulk(el.dataset.bulk);
  }
  if (t.closest('[data-close]') || t === scrim) return closeDrawer();
});
root.addEventListener('change', (e) => {
  const t = e.target;
  if (t.matches('[data-pick]')) { t.checked ? S.sel.add(t.dataset.pick) : S.sel.delete(t.dataset.pick); syncSel(); }
  if (t.matches('[data-all]')) { shown().forEach((v) => (t.checked ? S.sel.add(v.no) : S.sel.delete(v.no))); renderTable(); }
});
root.addEventListener('input', (e) => {
  if (!e.target.matches('[data-q]')) return;
  S.q = e.target.value.trim().toLowerCase();
  refresh();
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.key === 'Escape' && S.open) { e.preventDefault(); closeDrawer(); return; }
  if ((e.key === 'Enter' || e.key === ' ') && t.matches && t.matches('[data-inv]')) { e.preventDefault(); openDrawer(t.dataset.inv, t); return; }
  const r = t.closest && t.closest('[role="radio"]');
  if (r && /^Arrow(Left|Right)$/.test(e.key)) {
    e.preventDefault();
    const g = $$('[role="radio"]', r.parentElement), i = (g.indexOf(r) + (e.key === 'ArrowRight' ? 1 : -1) + g.length) % g.length;
    g[i].focus(); g[i].click();
  }
  if (t.matches && t.matches('[data-inv]') && /^Arrow/.test(e.key)) {
    e.preventDefault();
    const dots = $$('[data-inv]:not(.is-dim)'), i = dots.indexOf(t);
    const n = dots[clamp(i + (/Right|Down/.test(e.key) ? 1 : -1), 0, dots.length - 1)];
    if (n) n.focus();
  }
});
root.addEventListener('pointermove', (e) => {
  const t = e.target;
  if (t.closest('.dag-invoices__cash')) return;
  const dot = t.closest('[data-inv]');
  if (dot) {
    const v = byNo[dot.dataset.inv], d = dpd(v);
    return showTip(`<span class="dag-invoices__tt">${v.no} · ${CLIENTS[v.client]}</span>${trow(v.project, '')}${trow('Balance', EUR(balance(v)), band(v).c)}${v.part.length ? trow('Part-paid', EUR(paidSum(v))) : ''}${trow('Due', `${D(v.due)} · ${d > 0 ? d + ' days late' : d === 0 ? 'today' : 'in ' + -d + ' days'}`)}${trow('Reminders', v.rem.length || 'none')}${v.disputed ? trow('Status', 'Disputed') : ''}`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerleave', hideTip);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (S.view === 'overview') renderStrip();
  if (S.view === 'cash') renderCash();
});
ro.observe(strip);
ro.observe(cash);

/* ------------------------------------------------------------------ mount */
$$('[data-st]').forEach((b) => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
refresh();

css:
.dag-resource {
  width: 100%;
  height: var(--dag-resource-h, 680px);
  container-type: inline-size;
  container-name: dag-resource;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-resource-bg);
  color: var(--dag-resource-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-resource-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-resource-focus, var(--dag-resource-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-resource-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-resource-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-resource-num { font-variant-numeric: tabular-nums; }
  & .dag-resource-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-resource-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-resource-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

.dag-resource {
  /* re-theme with these four */
  --dag-resource-bg: oklch(0.205 0.022 172);
  --dag-resource-ink: oklch(0.95 0.012 150);
  --dag-resource-accent: oklch(0.87 0.1 86);
  --dag-resource-over: oklch(0.68 0.19 28);
  /* derived */
  --dag-resource-panel: color-mix(in oklch, var(--dag-resource-bg), var(--dag-resource-ink) 4%);
  --dag-resource-raise: color-mix(in oklch, var(--dag-resource-bg), var(--dag-resource-ink) 9%);
  --dag-resource-line: color-mix(in oklch, var(--dag-resource-ink) 11%, transparent);
  --dag-resource-hair: color-mix(in oklch, var(--dag-resource-ink) 6%, transparent);
  --dag-resource-mute: color-mix(in oklch, var(--dag-resource-ink) 68%, var(--dag-resource-bg));
  --dag-resource-faint: color-mix(in oklch, var(--dag-resource-ink) 45%, var(--dag-resource-bg));
  --dag-resource-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-resource-out: cubic-bezier(.16, 1, .3, 1);
  --dag-resource-spring: linear(0, .08 3%, .31 8%, .64 14%, .92 21%, 1.06 27%, 1.09 32%, 1.06 39%, 1.01 50%, .996 63%, 1);
  color-scheme: dark;
  border-radius: 16px;
}

.dag-resource__app {
  height: 100%;
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "rail top" "rail main";
}
.dag-resource__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 16px 0;
  border-right: 1px solid var(--dag-resource-line);
}
.dag-resource__logo { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; margin-bottom: 12px; color: var(--dag-resource-bg); background: var(--dag-resource-accent); & .dag-resource-i { fill: currentColor; stroke: none; } }
.dag-resource__rb {
  position: relative; width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; color: var(--dag-resource-faint);
  transition: background-color .18s, color .18s;
  &:hover { color: var(--dag-resource-ink); background: var(--dag-resource-hair); }
  &[aria-current="page"] { color: var(--dag-resource-accent); background: var(--dag-resource-raise); }
  & em { position: absolute; top: 3px; right: 2px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; display: grid; place-items: center; font: 700 9.5px var(--dag-resource-mono); font-style: normal; color: var(--dag-resource-bg); background: var(--dag-resource-over); }
  & em:empty { display: none; }
}

.dag-resource__top { grid-area: top; display: flex; align-items: end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; padding: 18px 22px 12px; }
.dag-resource__eb { font: 600 10.5px var(--dag-resource-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dag-resource-accent); }
.dag-resource__title h2 { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 700; letter-spacing: -.035em; line-height: 1.08; margin-top: 4px; }
.dag-resource__ctl { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.dag-resource__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dag-resource-hair); box-shadow: inset 0 0 0 1px var(--dag-resource-line);
  & button { height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dag-resource-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dag-resource-ink); }
  & button[aria-checked="true"] { background: var(--dag-resource-ink); color: var(--dag-resource-bg); }
}
.dag-resource__tg {
  display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; color: var(--dag-resource-mute);
  & button { width: 34px; height: 20px; border-radius: 10px; position: relative; background: var(--dag-resource-line); transition: background-color .2s; }
  & button i { position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--dag-resource-ink); transition: translate .35s var(--dag-resource-spring); }
  & button[aria-checked="true"] { background: var(--dag-resource-accent); }
  & button[aria-checked="true"] i { translate: 14px 0; background: var(--dag-resource-bg); }
}

.dag-resource__main { grid-area: main; min-height: 0; padding: 0 22px 18px; display: grid; }
.dag-resource__view { min-height: 0; display: grid; gap: 12px; }
.dag-resource__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 13px; background: var(--dag-resource-panel); box-shadow: inset 0 0 0 1px var(--dag-resource-line); overflow: hidden; }
.dag-resource__ph { padding: 13px 16px 6px; & h3 { font-size: 13.5px; font-weight: 650; } & p { font-size: 11.5px; color: var(--dag-resource-faint); margin-top: 1px; } }
.dag-resource__ss { flex: 1; min-height: 0; }

/* ---------- schedule grid ---------- */
.dag-resource__grid, .dag-resource__pgrid {
  display: grid;
  grid-template-columns: minmax(172px, 1.25fr) repeat(8, minmax(66px, 1fr)) 86px;
  min-width: 780px;
}
.dag-resource__hrow {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; position: sticky; top: 0; z-index: 5;
  background: var(--dag-resource-panel); border-bottom: 1px solid var(--dag-resource-line);
  & > div { padding: 10px 8px 8px; display: grid; gap: 4px; align-content: end; }
  & .dag-resource__wk { border-left: 1px solid var(--dag-resource-hair); }
  & .dag-resource__wk b { font: 650 11px var(--dag-resource-mono); letter-spacing: .02em; }
  & .dag-resource__wk span { font-size: 10.5px; color: var(--dag-resource-faint); }
  & .dag-resource__hl { font: 600 10.5px var(--dag-resource-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-resource-faint); padding-left: 16px; }
}
.dag-resource__tload {
  height: 4px; border-radius: 2px; background: var(--dag-resource-hair); overflow: hidden;
  & i { display: block; height: 100%; width: calc(min(var(--p), 1) * 100%); background: var(--dag-resource-accent); border-radius: inherit; transition: width .5s var(--dag-resource-out); }
  &.is-over i { background: var(--dag-resource-over); }
}
.dag-resource__row {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; grid-auto-rows: 24px; row-gap: 3px;
  padding: 7px 0 6px; border-bottom: 1px solid var(--dag-resource-hair); position: relative;
  transition: background-color .3s;
  &.is-flash { animation: dag-resource-flash 1.4s ease-out; }
}
.dag-resource__who {
  grid-column: 1; display: flex; align-items: center; gap: 10px; padding: 0 10px 0 16px; min-width: 0; align-self: center;
  position: sticky; left: 0; z-index: 3; background: var(--dag-resource-panel);
  & .dag-resource__av { width: 28px; height: 28px; border-radius: 50%; flex: none; display: grid; place-items: center; font: 700 10.5px system-ui, sans-serif; color: var(--dag-resource-bg); background: var(--c); }
  & span:last-child { display: grid; min-width: 0; line-height: 1.2; }
  & b { font-size: 12.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11px; color: var(--dag-resource-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dag-resource__slot {
  border-left: 1px solid var(--dag-resource-hair); margin: -7px 0 -6px;
  &.is-leave { background: repeating-linear-gradient(-45deg, var(--dag-resource-hair) 0 3px, transparent 3px 7px); display: grid; place-items: center; }
  &.is-leave::after { content: attr(data-l); font: 600 9.5px var(--dag-resource-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dag-resource-faint); }
}
.dag-resource__bk {
  grid-row: var(--lane); grid-column: var(--s) / var(--e); margin: 0 3px; z-index: 1; min-width: 0;
  display: flex; align-items: center; gap: 6px; padding: 0 8px; border-radius: 6px; text-align: left;
  font-size: 11.5px; font-weight: 650; color: color-mix(in oklch, var(--c) 25%, oklch(0.18 0.02 170)); white-space: nowrap; overflow: hidden;
  background: var(--c);
  transform-origin: left center;
  transition: filter .15s, box-shadow .15s;
  animation: dag-resource-wipe .7s var(--dag-resource-out) both; animation-delay: calc(var(--r) * 35ms + var(--s) * 20ms);
  & em { font: 650 10.5px var(--dag-resource-mono); font-style: normal; opacity: .8; margin-left: auto; }
  & span { overflow: hidden; text-overflow: ellipsis; }
  &:hover { filter: brightness(1.08); }
  &:focus-visible { outline: 2px solid var(--dag-resource-ink); outline-offset: 1px; }
  &[aria-expanded="true"] { box-shadow: 0 0 0 2px var(--dag-resource-bg), 0 0 0 4px var(--dag-resource-ink); }
  &.is-tent { color: var(--c); background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--c) 26%, transparent) 0 4px, color-mix(in oklch, var(--c) 12%, transparent) 4px 8px); box-shadow: inset 0 0 0 1.25px color-mix(in oklch, var(--c) 70%, transparent); }
  &.is-tent[aria-expanded="true"] { box-shadow: inset 0 0 0 1.25px var(--c), 0 0 0 2px var(--dag-resource-bg), 0 0 0 4px var(--dag-resource-ink); }
}
.dag-resource__ld {
  margin: 0 3px; border-radius: 4px; display: grid; place-items: center;
  font: 600 10px var(--dag-resource-mono); color: var(--dag-resource-faint);
  background: color-mix(in oklch, var(--dag-resource-ink) calc(var(--p) * 9%), transparent);
  transition: background-color .3s, color .3s;
  &.is-full { color: var(--dag-resource-ink); }
  &.is-free { color: var(--dag-resource-accent); }
  &.is-over { color: var(--dag-resource-ink); background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--dag-resource-over) 75%, transparent) 0 3px, color-mix(in oklch, var(--dag-resource-over) 40%, transparent) 3px 6px); }
}
.dag-resource__sum {
  grid-column: 10; display: grid; align-content: center; justify-items: end; padding-right: 14px; line-height: 1.2;
  & b { font: 650 13px var(--dag-resource-mono); letter-spacing: -.03em; }
  & small { font-size: 10.5px; color: var(--dag-resource-faint); }
  &.is-over b { color: var(--dag-resource-over); }
}
.dag-resource__legend {
  display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 9px 16px; border-top: 1px solid var(--dag-resource-line); font-size: 11.5px; color: var(--dag-resource-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 12px; height: 8px; border-radius: 2px; background: var(--c); }
  & i.is-tent { background: repeating-linear-gradient(-45deg, var(--c) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--c); }
  & .dag-resource__lgo i { background: repeating-linear-gradient(-45deg, var(--dag-resource-over) 0 2px, transparent 2px 4px); }
}

/* ---------- by project ---------- */
.dag-resource__prow {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; min-height: 58px;
  border-bottom: 1px solid var(--dag-resource-hair);
  animation: dag-resource-rise .5s var(--dag-resource-out) both; animation-delay: calc(var(--i) * 50ms);
  & .dag-resource__pn { padding: 8px 10px 8px 16px; display: grid; gap: 3px; position: sticky; left: 0; background: var(--dag-resource-panel); z-index: 2; }
  & .dag-resource__pn b { font-size: 12.5px; font-weight: 620; display: flex; align-items: center; gap: 7px; }
  & .dag-resource__pn b i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); flex: none; }
  & .dag-resource__pn small { font-size: 11px; color: var(--dag-resource-faint); }
  & .dag-resource__pc { height: 40px; margin: 0 3px; border-radius: 6px; display: grid; align-content: center; justify-items: center; gap: 3px; background: color-mix(in oklch, var(--c) calc(var(--p) * 60%), transparent); box-shadow: inset 0 0 0 1px var(--dag-resource-hair); }
  & .dag-resource__pc b { font: 650 11.5px var(--dag-resource-mono); }
  & .dag-resource__pc span { display: flex; }
  & .dag-resource__pc span i { width: 18px; height: 18px; border-radius: 50%; margin-left: -5px; font: 700 7.5px/18px system-ui, sans-serif; font-style: normal; letter-spacing: -.02em; text-align: center; color: oklch(0.2 0.02 170); background: var(--c, var(--dag-resource-ink)); box-shadow: 0 0 0 1.5px var(--dag-resource-panel); }
  & .dag-resource__pc span i.is-more { color: var(--dag-resource-ink); background: var(--dag-resource-raise); }
  & .dag-resource__pc span i:first-child { margin-left: 0; }
  &.is-tent .dag-resource__pc { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--c) calc(var(--p) * 45%), transparent) 0 4px, transparent 4px 8px); }
  & .dag-resource__cov { grid-column: 10; padding-right: 12px; display: grid; gap: 4px; justify-items: end; }
  & .dag-resource__cov b { font: 650 12px var(--dag-resource-mono); }
  & .dag-resource__cov small { font-size: 10.5px; color: var(--dag-resource-faint); text-align: right; }
}
.dag-resource__btn {
  height: 24px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 650; white-space: nowrap;
  color: var(--dag-resource-bg); background: var(--dag-resource-accent); transition: filter .15s;
  &:hover:not(:disabled) { filter: brightness(1.1); }
  &.is-ghost { color: var(--dag-resource-ink); background: none; box-shadow: inset 0 0 0 1px var(--dag-resource-line); }
  &.is-ghost:hover:not(:disabled) { background: var(--dag-resource-hair); }
  &:disabled { opacity: .4; }
}

/* ---------- capacity ---------- */
.dag-resource__capv { grid-template-columns: minmax(0, 1fr) 300px; }
.dag-resource__chart { flex: 1; min-height: 240px; position: relative; margin: 0 10px 10px; cursor: crosshair; border-radius: 8px; }
.dag-resource__csvg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dag-resource__gl { stroke: var(--dag-resource-hair); }
  & .dag-resource__ax { fill: var(--dag-resource-faint); font: 500 10px var(--dag-resource-mono); }
  & .dag-resource__cs { transform-box: fill-box; transform-origin: bottom; animation: dag-resource-growy .7s var(--dag-resource-out) both; animation-delay: calc(var(--i) * 45ms); }
  & .dag-resource__cap { fill: none; stroke: var(--dag-resource-ink); stroke-width: 2; stroke-dasharray: 6 4; }
  & .dag-resource__capl { fill: var(--dag-resource-ink); font: 650 10px var(--dag-resource-mono); }
  & .dag-resource__ovr { fill: var(--dag-resource-over); font: 700 10px var(--dag-resource-mono); }
  & .dag-resource__hi { fill: var(--dag-resource-ink); opacity: 0; transition: opacity .15s, x .2s var(--dag-resource-out); }
}
.dag-resource__issues { gap: 0; }
.dag-resource__il {
  padding: 2px 10px 10px; display: grid; gap: 4px; align-content: start; max-height: 50%;
  & li button { width: 100%; display: grid; grid-template-columns: 4px minmax(0, 1fr) auto; gap: 10px; align-items: center; text-align: left; padding: 8px 10px 8px 0; border-radius: 9px; background: var(--dag-resource-raise); transition: background-color .15s; }
  & li button:hover { background: color-mix(in oklch, var(--dag-resource-raise), var(--dag-resource-ink) 6%); }
  & li button > i { align-self: stretch; border-radius: 0 3px 3px 0; background: var(--c); }
  & b { font-size: 12.5px; font-weight: 620; display: block; }
  & small { font-size: 11.5px; color: var(--dag-resource-faint); display: block; }
  & em { font: 650 11.5px var(--dag-resource-mono); font-style: normal; color: var(--c); }
  & .dag-resource__none { font-size: 12px; color: var(--dag-resource-faint); padding: 6px 4px; }
}

/* ---------- editor, tooltip, toast ---------- */
.dag-resource__pop {
  position: absolute; left: 0; top: 0; z-index: 30; width: 270px; padding: 14px; border-radius: 13px;
  background: color-mix(in oklch, var(--dag-resource-bg), var(--dag-resource-ink) 12%); color: var(--dag-resource-ink);
  box-shadow: 0 0 0 1px var(--dag-resource-line), 0 22px 44px -18px oklch(0 0 0 / .75);
  display: grid; gap: 12px;
  transition: opacity .2s, scale .3s var(--dag-resource-spring);
  transform-origin: var(--ox, 20px) 0;
  @starting-style { opacity: 0; scale: .94; }
  & header { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: center; }
  & header i { width: 10px; height: 26px; border-radius: 3px; background: var(--c); }
  & header b { display: block; font-size: 13px; font-weight: 650; }
  & header small { display: block; font-size: 11.5px; color: var(--dag-resource-faint); }
  & .dag-resource__pr { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px; font-size: 12px; color: var(--dag-resource-mute); }
  & .dag-resource__step { display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 8px; background: var(--dag-resource-hair); box-shadow: inset 0 0 0 1px var(--dag-resource-line); }
  & .dag-resource__step button { width: 26px; height: 24px; border-radius: 6px; display: grid; place-items: center; color: var(--dag-resource-ink); transition: background-color .15s; }
  & .dag-resource__step button:hover:not(:disabled) { background: var(--dag-resource-line); }
  & .dag-resource__step button:disabled { opacity: .3; }
  & .dag-resource__step output { min-width: 64px; text-align: center; font: 650 12px var(--dag-resource-mono); }
  & .dag-resource__step svg { width: 14px; height: 14px; }
  & footer { display: flex; justify-content: space-between; gap: 8px; }
}
.dag-resource__x { width: 26px; height: 26px; border-radius: 7px; display: grid; place-items: center; color: var(--dag-resource-mute); &:hover { background: var(--dag-resource-hair); color: var(--dag-resource-ink); } & svg { width: 14px; height: 14px; } }
.dag-resource__tip {
  position: absolute; left: 0; top: 0; z-index: 40; pointer-events: none; min-width: 160px; max-width: 270px;
  padding: 9px 11px; border-radius: 10px; background: var(--dag-resource-ink); color: var(--dag-resource-bg);
