/* ------------------------------------------------------------------ data */
/* Eight weeks from Mon 5 Oct 2026 (ISO weeks 41–48). One day = 7.5 hours. */
const WEEKS = Array.from({ length: 8 }, (_, i) => { const d = new Date(Date.UTC(2026, 9, 5) + i * 6048e5); return { i, iso: 41 + i, label: d.getUTCDate() + ' ' + MON[d.getUTCMonth()] }; });
const DISC_C = { Design: 'oklch(0.78 0.11 32)', Engineering: 'oklch(0.78 0.1 232)', Strategy: 'oklch(0.84 0.1 88)', Production: 'oklch(0.8 0.11 160)' };
const PEOPLE = [
  ['mara', 'Mara Quist', 'Design lead', 'Design', 5, {}],
  ['joel', 'Joel Haines', 'Senior designer', 'Design', 5, {}],
  ['ivy', 'Ivy Chen', 'Product designer', 'Design', 5, { 3: 5 }],
  ['sol', 'Sol Ortega', 'Designer · 4-day week', 'Design', 4, {}],
  ['kofi', 'Kofi Mensah', 'Tech lead', 'Engineering', 5, { 6: 3 }],
  ['lena', 'Lena Vogt', 'Senior engineer', 'Engineering', 5, {}],
  ['arjun', 'Arjun Rao', 'Engineer', 'Engineering', 5, {}],
  ['bea', 'Bea Santos', 'Engineer', 'Engineering', 5, {}],
  ['noor', 'Noor Haddad', 'Strategy director', 'Strategy', 5, {}],
  ['theo', 'Theo Park', 'Strategist', 'Strategy', 5, {}],
  ['ruth', 'Ruth Ellis', 'Producer', 'Production', 5, { 1: 2 }],
  ['max', 'Max Adler', 'Producer', 'Production', 5, {}]
