const PROJ = {
  vela: { name: 'Vela Insurance', job: 'Claims app — release 2', c: 'oklch(0.74 0.14 32)', budget: 98 },
  parcel: { name: 'Parcelpoint', job: 'Driver app v2', c: 'oklch(0.77 0.1 232)', budget: 118 },
  north: { name: 'Northgate Housing', job: 'Tenant portal beta', c: 'oklch(0.8 0.12 160)', budget: 84 },
  ashby: { name: 'Ashby Museum', job: 'Collections site launch', c: 'oklch(0.85 0.1 90)', budget: 18 },
  copper: { name: 'Copperleaf Tea', job: 'Storefront handover', c: 'oklch(0.76 0.13 352)', budget: 14 },
  halden: { name: 'Halden Furniture', job: 'Spring campaign · 70% likely', c: 'oklch(0.81 0.13 62)', tent: true, budget: 36 },
