let bid = 0;
const BOOK = [
  ['mara', 'ashby', 0, 4, 2], ['mara', 'vela', 0, 7, 1.5], ['mara', 'halden', 2, 7, 2],
  ['joel', 'vela', 0, 5, 4], ['joel', 'parcel', 4, 7, 2],
  ['ivy', 'north', 0, 7, 3], ['ivy', 'copper', 0, 1, 2],
  ['sol', 'copper', 0, 1, 3], ['sol', 'internal', 2, 3, 2], ['sol', 'tidewell', 4, 7, 3],
