  ['lena', 'vela', 0, 5, 5], ['lena', 'parcel', 6, 7, 5],
  ['arjun', 'parcel', 0, 7, 4], ['arjun', 'north', 2, 5, 1],
  ['bea', 'north', 0, 7, 4], ['bea', 'copper', 0, 0, 1], ['bea', 'halden', 5, 7, 2],
  ['noor', 'internal', 0, 7, 1.5], ['noor', 'halden', 0, 3, 2], ['noor', 'tidewell', 2, 5, 1.5], ['noor', 'north', 0, 1, 1],
  ['theo', 'vela', 0, 2, 2], ['theo', 'tidewell', 3, 7, 3], ['theo', 'ashby', 0, 1, 1],
  ['ruth', 'vela', 0, 7, 2], ['ruth', 'parcel', 0, 7, 2], ['ruth', 'ashby', 0, 4, 1],
  ['max', 'north', 0, 7, 2], ['max', 'copper', 0, 1, 1.5], ['max', 'halden', 3, 7, 1.5]
