  const ps = people();
  const head = `<div class="dag-resource__hrow" role="row"><div class="dag-resource__hl" role="columnheader">Person</div>${WEEKS.map((w) => {
    const c = ps.reduce((s, p) => s + cap(p, w.i), 0), l = ps.reduce((s, p) => s + load(p.id, w.i), 0);
    return `<div class="dag-resource__wk" role="columnheader" data-wk="${w.i}"><b>W${w.iso}</b><span>${w.label} · ${Math.round(l / c * 100)}%</span><span class="dag-resource__tload${l > c ? ' is-over' : ''}" style="--p:${(l / c).toFixed(3)}"><i></i></span></div>`;
  }).join('')}<div class="dag-resource__hl" role="columnheader" style="padding:10px 14px 8px 0;text-align:right">Load</div></div>`;
