      <div class="dag-resource__who" role="rowheader" style="${span}"><span class="dag-resource__av" style="--c:${DISC_C[p.disc]}" aria-hidden="true">${p.ini}</span><span><b>${p.name}</b><small>${p.role}</small></span></div>
