  pop.style.setProperty('--c', P.c);
  pop.innerHTML = `<header><i></i><div><b>${P.name}${P.tent ? ' · tentative' : ''}</b><small>${p.name} · ${P.job.replace(/ · .*$/, '')}</small></div><button type="button" class="dag-resource__x" data-pclose aria-label="Close editor">${ICON.x}</button></header>
    <div class="dag-resource__pr"><span>Days a week</span><span class="dag-resource__step">${btn('d-', ICON.minus, b.d <= .5, 'Half a day is the smallest booking', 'Half a day less')}<output>${DY(b.d)} d · ${b.d * 7.5} h</output>${btn('d+', ICON.plus, b.d >= p.days, `${p.name.split(' ')[0]} works ${p.days} days a week`, 'Half a day more')}</span></div>
