    else { const gap = P.budget - all; cov = `<b>${DY(all)}/${P.budget} d</b><small style="color:${gap > 0 ? 'var(--dag-resource-accent)' : gap < 0 ? 'var(--dag-resource-over)' : ''}">${gap > 0 ? DY(gap) + ' d unstaffed' : gap < 0 ? DY(-gap) + ' d over budget' : 'fully staffed'}</small>`; }
    if (P.tent) cov += `<button type="button" class="dag-resource__btn" data-confirm="${k}">Confirm</button>`;
    return `<div class="dag-resource__prow${P.tent ? ' is-tent' : ''}" style="--c:${P.c};--i:${i}" data-proj="${k}"><div class="dag-resource__pn"><b><i></i>${P.name}</b><small>${P.job}</small></div>${per.map((x, w) => `<div class="dag-resource__pc" style="grid-column:${w + 2};--p:${(x.d / max * .9 + (x.d ? .1 : 0)).toFixed(2)}" data-pw="${k}:${w}">${x.d ? `<b>${DY(x.d)}d</b><span>${x.who.slice(0, 3).map((id) => `<i style="--c:${DISC_C[byP[id].disc]}">${byP[id].ini}</i>`).join('')}${x.who.length > 3 ? `<i class="is-more">+${x.who.length - 3}</i>` : ''}</span>` : ''}</div>`).join('')}<div class="dag-resource__cov">${cov}</div></div>`;
  }).join('');
  $('.dag-resource__pgrid').innerHTML = head + rows;
}

/* ------------------------------------------------------------------ capacity */
const chart = $('.dag-resource__chart'), csvg = $('.dag-resource__csvg');
let cg = null;
function renderCapacity() {
  const W = chart.clientWidth, H = chart.clientHeight;
  if (W && H) {
    const ps = people(), ids = new Set(ps.map((p) => p.id)), keys = Object.keys(PROJ);
    const data = WEEKS.map((w) => {
      const by = {};
      BOOK.filter((b) => ids.has(b.p) && live(b) && w.i >= b.s && w.i <= b.e).forEach((b) => { by[b.proj] = (by[b.proj] || 0) + b.d; });
      return { w, by, tot: Object.values(by).reduce((s, v) => s + v, 0), cap: ps.reduce((s, p) => s + cap(p, w.i), 0) };
    });
    const pad = { l: 40, r: 14, t: 18, b: 30 }, ymax = Math.ceil(Math.max(...data.map((d) => Math.max(d.tot, d.cap))) * 1.12 / 5) * 5;
    const slot = (W - pad.l - pad.r) / 8, bw = Math.min(56, slot * .56), y = (v) => pad.t + (1 - v / ymax) * (H - pad.t - pad.b);
    cg = { data, slot, pad, y, W, H };
    let g = `<rect class="dag-resource__hi" x="${pad.l}" y="${pad.t - 6}" width="${slot}" height="${H - pad.t - pad.b + 6}" rx="6"/>`;
    const step = ymax > 40 ? 10 : 5;
    for (let v = 0; v <= ymax; v += step) g += `<line class="dag-resource__gl" x1="${pad.l}" x2="${W - pad.r}" y1="${y(v)}" y2="${y(v)}"/><text class="dag-resource__ax" x="${pad.l - 6}" y="${y(v) + 3.5}" text-anchor="end">${v}d</text>`;
    data.forEach((d, i) => {
      const x0 = pad.l + i * slot + (slot - bw) / 2;
      let acc = 0;
      keys.forEach((k) => {
        const v = d.by[k];
        if (!v) return;
        g += `<rect class="dag-resource__cs" x="${x0}" y="${y(acc + v)}" width="${bw}" height="${Math.max(0, y(acc) - y(acc + v) - 1.5)}" rx="2.5" style="--i:${i};fill:${PROJ[k].c};${PROJ[k].tent ? 'opacity:.42;stroke:' + PROJ[k].c + ';stroke-dasharray:3 2;' : ''}"/>`;
        acc += v;
      });
      if (d.tot > d.cap) g += `<text class="dag-resource__ovr" x="${x0 + bw / 2}" y="${y(d.tot) - 6}" text-anchor="middle">+${DY(d.tot - d.cap)}d</text>`;
      g += `<text class="dag-resource__ax" x="${x0 + bw / 2}" y="${H - 16}" text-anchor="middle" style="font-weight:650">W${d.w.iso}</text><text class="dag-resource__ax" x="${x0 + bw / 2}" y="${H - 4}" text-anchor="middle">${d.w.label}</text>`;
    });
    g += `<path class="dag-resource__cap" d="${data.map((d, i) => `${i ? 'L' : 'M'}${pad.l + i * slot} ${y(d.cap)}H${pad.l + (i + 1) * slot}`).join('')}"/><text class="dag-resource__capl" x="${W - pad.r}" y="${y(data[7].cap) - 6}" text-anchor="end">capacity</text>`;
    csvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    csvg.innerHTML = g;
  }
  const { over, free } = issues();
  const item = (x, kind) => `<li><button type="button" data-goto="${x.p.id}" data-wk="${x.s}"><i style="--c:${kind === 'free' ? 'var(--dag-resource-accent)' : 'var(--dag-resource-over)'}"></i><span><b>${x.p.name}</b><small>${wkLabel(x.s, x.e)} · ${x.k === 'leave' ? 'booked while on leave' : x.k === 'over' ? 'more booked than available' : 'free to take work'}</small></span><em style="--c:${kind === 'free' ? 'var(--dag-resource-accent)' : 'var(--dag-resource-over)'}">${x.k === 'free' ? DY(x.amt) + 'd free' : '+' + DY(x.amt) + 'd'}</em></button></li>`;
  $('[data-il="over"]').innerHTML = over.map((x) => item(x, 'over')).join('') || '<li class="dag-resource__none">No conflicts — nobody is booked past capacity.</li>';
  $('[data-il="free"]').innerHTML = free.map((x) => item(x, 'free')).join('') || '<li class="dag-resource__none">Everyone is fully booked.</li>';
}
function capTip(i, cx, cy) {
  if (!cg) return;
  i = clamp(i, 0, 7);
  S.hx = i;
  const hi = csvg.querySelector('.dag-resource__hi');
  if (hi) { hi.setAttribute('x', cg.pad.l + i * cg.slot); hi.style.opacity = '.06'; }
  const d = cg.data[i], rb = chart.getBoundingClientRect();
  const rows = Object.keys(PROJ).filter((k) => d.by[k]).map((k) => trow(PROJ[k].name + (PROJ[k].tent ? ' (t)' : ''), DY(d.by[k]) + ' d', PROJ[k].c)).join('');
  showTip(`<span class="dag-resource__tt">W${d.w.iso} · w/c ${d.w.label}</span>${rows}${trow('Booked', DY(d.tot) + ' d')}${trow('Capacity', DY(d.cap) + ' d')}${trow(d.tot > d.cap ? 'Over by' : 'Spare', DY(Math.abs(d.cap - d.tot)) + ' d')}`, cx ?? rb.left + cg.pad.l + (i + .5) * cg.slot, cy ?? rb.top + cg.y(d.tot));
}
chart.addEventListener('pointermove', (e) => { if (!cg) return; const rb = chart.getBoundingClientRect(); capTip(Math.floor((e.clientX - rb.left - cg.pad.l) / cg.slot), e.clientX, e.clientY); });
const capOff = () => { S.hx = null; hideTip(); const hi = csvg.querySelector('.dag-resource__hi'); if (hi) hi.style.opacity = 0; };
chart.addEventListener('pointerleave', capOff);
chart.addEventListener('blur', capOff);
chart.addEventListener('keydown', (e) => {
  if (!/^(ArrowLeft|ArrowRight|Home|End)$/.test(e.key)) return;
  e.preventDefault();
  capTip(e.key === 'Home' ? 0 : e.key === 'End' ? 7 : (S.hx == null ? 0 : S.hx + (e.key === 'ArrowRight' ? 1 : -1)));
});

/* ------------------------------------------------------------------ orchestration */
function renderBadge() { const n = issues().over.length; $('[data-ob]').textContent = n || ''; }
function renderAll(flip) {
  if (S.view === 'people') renderGrid(flip);
  if (S.view === 'projects') renderProjects();
  if (S.view === 'capacity') renderCapacity();
  renderBadge();
  if (S.edit) { if (BOOK.some((b) => b.id === S.edit && live(b)) && S.view === 'people') { const f = document.activeElement && document.activeElement.dataset ? document.activeElement.dataset.ed : null; renderPop(); placePop(); const n = f && pop.querySelector(`[data-ed="${f}"]`); if (n) (n.disabled ? pop.querySelector('[data-pclose]') : n).focus({ preventScroll: true }); const bar = grid.querySelector(`[data-b="${S.edit}"]`); if (bar) bar.setAttribute('aria-expanded', 'true'); } else closeEdit(false); }
}
function setView(v) {
  S.view = v;
  closeEdit(false);
  $$('[data-go]').forEach((b) => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dag-resource__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  $('[data-title]').textContent = v === 'people' ? 'Who’s on what, next eight weeks' : v === 'projects' ? 'Is every project staffed?' : 'Capacity and conflicts';
  hideTip();
  renderAll(false);
}
function gotoRow(pid) {
  if (S.disc !== 'All' && byP[pid].disc !== S.disc) setDisc('All');
  setView('people');
  const row = grid.querySelector(`[data-row="${pid}"]`);
  if (!row) return;
  row.scrollIntoView({ block: 'center', behavior: RM ? 'auto' : 'smooth' });
  row.classList.remove('is-flash');
  void row.offsetWidth;
  row.classList.add('is-flash');
  const b = row.querySelector('.dag-resource__bk');
  if (b) b.focus({ preventScroll: true });
}
function setDisc(d) {
  S.disc = d;
  $$('[data-disc]').forEach((b) => { const on = b.dataset.disc === d; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  closeEdit(false);
  renderAll(false);
}

/* ------------------------------------------------------------------ events */
root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if ((el = t.closest('[data-disc]'))) return setDisc(el.dataset.disc);
  if ((el = t.closest('[data-tent]'))) {
    S.tent = !S.tent;
    el.setAttribute('aria-checked', S.tent);
    renderAll(S.view === 'people');
    return toast(S.tent ? 'Showing tentative pipeline work' : 'Showing confirmed work only');
  }
  if ((el = t.closest('.dag-resource__bk'))) { if (S.edit === el.dataset.b) return closeEdit(true); return openEdit(el.dataset.b); }
  if ((el = t.closest('[data-ed]'))) { if (!el.disabled) edit(S.edit, el.dataset.ed); return; }
  if (t.closest('[data-pclose]')) return closeEdit(true);
  if ((el = t.closest('[data-confirm]'))) {
    const k = el.dataset.confirm, P = PROJ[k];
    P.tent = false;
    P.job = P.job.replace(/ · .*$/, '');
    const days = BOOK.filter((b) => b.proj === k).reduce((s, b) => s + b.d * (b.e - b.s + 1), 0);
    renderAll(false);
    return toast(`${P.name} confirmed — ${DY(days)} booked days are now firm`);
  }
  if ((el = t.closest('[data-goto]'))) return gotoRow(el.dataset.goto);
  if (S.edit && !t.closest('.dag-resource__pop')) closeEdit(false);
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.key === 'Escape' && S.edit) { e.preventDefault(); closeEdit(true); return; }
  const r = t.closest && t.closest('[role="radio"]');
  if (r && /^Arrow(Left|Right)$/.test(e.key)) {
    e.preventDefault();
    const g = $$('[role="radio"]', r.parentElement), i = (g.indexOf(r) + (e.key === 'ArrowRight' ? 1 : -1) + g.length) % g.length;
    g[i].focus(); g[i].click();
    return;
  }
  const bar = t.closest && t.closest('.dag-resource__bk');
  if (bar && /^Arrow/.test(e.key)) {
    e.preventDefault();
    const op = e.key === 'ArrowUp' ? 'd+' : e.key === 'ArrowDown' ? 'd-' : e.shiftKey ? (e.key === 'ArrowRight' ? 'l+' : 'l-') : (e.key === 'ArrowRight' ? 's+' : 's-');
    const id = bar.dataset.b;
    if (edit(id, op)) {
      const n = grid.querySelector(`[data-b="${id}"]`);
      if (n) n.focus({ preventScroll: true });
      const b = BOOK.find((x) => x.id === id);
      toast(`${PROJ[b.proj].name} · ${byP[b.p].name.split(' ')[0]}: ${wkLabel(b.s, b.e)}, ${DY(b.d)} d a week`);
    }
  }
});
root.addEventListener('pointermove', (e) => {
  const t = e.target;
  if (t.closest('.dag-resource__chart') || t.closest('.dag-resource__pop')) return;
  let el;
  if ((el = t.closest('[data-ld]'))) {
    const [pid, w] = el.dataset.ld.split(':'), p = byP[pid], wi = +w;
    const on = booksOf(pid).filter((b) => wi >= b.s && wi <= b.e);
    return showTip(`<span class="dag-resource__tt">${p.name} · W${WEEKS[wi].iso}</span>${on.map((b) => trow(PROJ[b.proj].name, DY(b.d) + ' d', PROJ[b.proj].c)).join('') || trow('Nothing booked', '')}${p.leave[wi] ? trow('Leave', p.leave[wi] + ' d') : ''}${trow('Available', DY(cap(p, wi)) + ' d')}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('.dag-resource__bk'))) {
    const b = BOOK.find((x) => x.id === el.dataset.b), P = PROJ[b.proj];
    return showTip(`<span class="dag-resource__tt">${P.name}${P.tent ? ' · tentative' : ''}</span>${trow(byP[b.p].name, wkLabel(b.s, b.e))}${trow('Per week', `${DY(b.d)} d · ${b.d * 7.5} h`)}${trow('Total', DY(b.d * (b.e - b.s + 1)) + ' d')}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('[data-pw]'))) {
    const [k, w] = el.dataset.pw.split(':'), wi = +w, ids = new Set(people().map((p) => p.id));
    const on = BOOK.filter((b) => b.proj === k && ids.has(b.p) && wi >= b.s && wi <= b.e);
    if (on.length) return showTip(`<span class="dag-resource__tt">${PROJ[k].name} · W${WEEKS[wi].iso}</span>${on.map((b) => trow(byP[b.p].name, DY(b.d) + ' d')).join('')}`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerleave', hideTip);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (S.view === 'capacity') renderCapacity();
  if (S.edit) placePop();
});
ro.observe(chart);
ro.observe(grid);
$('.dag-resource__ss').addEventListener('scroll', () => { if (S.edit) placePop(); hideTip(); }, { passive: true });

/* ------------------------------------------------------------------ mount */
$$('[data-disc]').forEach((b) => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
renderAll(false);

css:
.dag-pitch {
  width: 100%;
  height: var(--dag-pitch-h, 680px);
  container-type: inline-size;
  container-name: dag-pitch;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-pitch-bg);
  color: var(--dag-pitch-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-pitch-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-pitch-focus, var(--dag-pitch-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-pitch-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-pitch-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-pitch-num { font-variant-numeric: tabular-nums; }
  & .dag-pitch-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-pitch-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-pitch-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

.dag-pitch {
  /* re-theme with these four */
  --dag-pitch-bg: oklch(0.205 0.028 25);
  --dag-pitch-ink: oklch(0.95 0.02 75);
  --dag-pitch-accent: oklch(0.8 0.125 58);
  --dag-pitch-lost: oklch(0.7 0.14 22);
  /* derived */
  --dag-pitch-panel: color-mix(in oklch, var(--dag-pitch-bg), var(--dag-pitch-ink) 4.5%);
  --dag-pitch-raise: color-mix(in oklch, var(--dag-pitch-bg), var(--dag-pitch-ink) 9%);
  --dag-pitch-line: color-mix(in oklch, var(--dag-pitch-ink) 12%, transparent);
  --dag-pitch-hair: color-mix(in oklch, var(--dag-pitch-ink) 6.5%, transparent);
  --dag-pitch-mute: color-mix(in oklch, var(--dag-pitch-ink) 72%, var(--dag-pitch-bg));
  --dag-pitch-faint: color-mix(in oklch, var(--dag-pitch-ink) 50%, var(--dag-pitch-bg));
  --dag-pitch-s0: color-mix(in oklch, var(--dag-pitch-accent) 30%, var(--dag-pitch-panel));
  --dag-pitch-s1: color-mix(in oklch, var(--dag-pitch-accent) 48%, var(--dag-pitch-panel));
  --dag-pitch-s2: color-mix(in oklch, var(--dag-pitch-accent) 66%, var(--dag-pitch-panel));
  --dag-pitch-s3: color-mix(in oklch, var(--dag-pitch-accent) 84%, var(--dag-pitch-panel));
  --dag-pitch-s4: var(--dag-pitch-accent);
  --dag-pitch-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-pitch-out: cubic-bezier(.16, 1, .3, 1);
  --dag-pitch-spring: linear(0, .09 3%, .33 8%, .67 14%, .94 21%, 1.06 27%, 1.08 32%, 1.05 39%, 1.01 50%, .997 63%, 1);
  color-scheme: dark;
  border-radius: 18px;
  user-select: none;
}

.dag-pitch__app {
  height: 100%;
  display: grid;
  grid-template-columns: 176px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "rail top" "rail sum" "rail main";
}

/* ---------- rail ---------- */
.dag-pitch__rail { grid-area: rail; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px; border-right: 1px solid var(--dag-pitch-line); min-height: 0; }
.dag-pitch__brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
.dag-pitch__mark { width: 34px; height: 34px; border-radius: 10px; flex: none; display: grid; place-items: center; background: var(--dag-pitch-accent); color: var(--dag-pitch-bg); & .dag-pitch-i { stroke-width: 2.1; } }
.dag-pitch__bt { display: grid; line-height: 1.2; & b { font-size: 14px; font-weight: 700; letter-spacing: -.02em; } & small { font-size: 11px; color: var(--dag-pitch-faint); } }
.dag-pitch__nav { display: grid; gap: 3px; }
.dag-pitch__nb {
  width: 100%; height: 38px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 10px; position: relative;
  font-size: 13px; font-weight: 600; color: var(--dag-pitch-mute); text-align: left;
  transition: background-color .18s, color .18s;
  &:hover { background: var(--dag-pitch-hair); color: var(--dag-pitch-ink); }
  &[aria-current="page"] { background: var(--dag-pitch-raise); color: var(--dag-pitch-ink); box-shadow: inset 0 0 0 1px var(--dag-pitch-line); }
  &[aria-current="page"] .dag-pitch-i { color: var(--dag-pitch-accent); }
  & em { margin-left: auto; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; display: grid; place-items: center; font: 700 10px var(--dag-pitch-mono); font-style: normal; color: var(--dag-pitch-bg); background: var(--dag-pitch-lost); }
  & em:empty { display: none; }
}
.dag-pitch__railcard {
  margin-top: auto; padding: 12px; border-radius: 12px; background: var(--dag-pitch-panel); box-shadow: inset 0 0 0 1px var(--dag-pitch-line); display: grid; gap: 3px;
  & p { font-size: 12px; color: var(--dag-pitch-mute); line-height: 1.35; }
  & p b { color: var(--dag-pitch-ink); font-weight: 650; }
  & small { font: 500 10.5px var(--dag-pitch-mono); color: var(--dag-pitch-faint); margin-top: 3px; }
}
.dag-pitch__eb { font: 600 10.5px var(--dag-pitch-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dag-pitch-accent); }

/* ---------- header ---------- */
.dag-pitch__top { grid-area: top; display: flex; align-items: end; justify-content: space-between; flex-wrap: wrap; gap: 10px 18px; padding: 18px 20px 12px; }
.dag-pitch__title h2 { margin-top: 4px; font-size: clamp(19px, 2.4cqi, 27px); font-weight: 720; letter-spacing: -.035em; line-height: 1.08; }
.dag-pitch__owners {
  display: flex; gap: 4px; padding: 3px; border-radius: 12px; background: var(--dag-pitch-hair); box-shadow: inset 0 0 0 1px var(--dag-pitch-line);
  & button { height: 30px; display: inline-flex; align-items: center; gap: 6px; padding: 0 10px 0 6px; border-radius: 9px; font-size: 12px; font-weight: 600; color: var(--dag-pitch-mute); transition: background-color .18s, color .18s; }
  & button:first-child { padding-left: 10px; }
  & button:hover { color: var(--dag-pitch-ink); }
  & button[aria-checked="true"] { background: var(--dag-pitch-ink); color: var(--dag-pitch-bg); }
  & i { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font: 700 8.5px system-ui, sans-serif; font-style: normal; color: oklch(0.22 0.03 30); background: var(--c); }
}

/* ---------- target strip ---------- */
.dag-pitch__sum { grid-area: sum; margin: 0 20px; padding: 14px 16px 26px; border-radius: 14px; background: var(--dag-pitch-panel); box-shadow: inset 0 0 0 1px var(--dag-pitch-line); display: grid; gap: 14px; }
.dag-pitch__kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.dag-pitch__kpi {
  display: grid; gap: 1px; min-width: 0;
  & + & { padding-left: 14px; border-left: 1px solid var(--dag-pitch-hair); }
  & span { font-size: 11px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--dag-pitch-faint); }
  & b { font-size: clamp(18px, 2.1cqi, 25px); font-weight: 680; letter-spacing: -.035em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & b.is-bad { color: var(--dag-pitch-lost); }
  & small { font-size: 11.5px; color: var(--dag-pitch-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &.is-hero b { color: var(--dag-pitch-accent); }
}
.dag-pitch__track { position: relative; height: 12px; }
.dag-pitch__segs {
  height: 100%; display: flex; gap: 2px; border-radius: 6px; overflow: hidden; background: var(--dag-pitch-hair);
  & i { height: 100%; width: 0; flex: none; background: var(--dag-pitch-s4); transition: width .9s var(--dag-pitch-spring); }
  & i[data-seg="nego"] { background: var(--dag-pitch-s3); }
  & i[data-seg="prop"] { background: var(--dag-pitch-s2); }
  & i[data-seg="qual"] { background: var(--dag-pitch-s1); }
  & i[data-seg="lead"] { background: repeating-linear-gradient(-45deg, var(--dag-pitch-s1) 0 3px, var(--dag-pitch-s0) 3px 6px); }
  & i:hover { filter: brightness(1.15); }
}
.dag-pitch__tgt {
  position: absolute; top: -5px; bottom: -5px; left: 0; width: 0; transition: left .9s var(--dag-pitch-spring); pointer-events: none;
  & i { position: absolute; inset: 0 auto 0 -1px; width: 2px; border-radius: 1px; background: var(--dag-pitch-ink); }
  & b { position: absolute; right: 7px; bottom: -20px; white-space: nowrap; font: 650 10px var(--dag-pitch-mono); letter-spacing: .02em; color: var(--dag-pitch-ink); }
}

/* ---------- main + views ---------- */
.dag-pitch__main { grid-area: main; min-height: 0; padding: 14px 20px 18px; display: grid; }
.dag-pitch__view { min-height: 0; min-width: 0; }
.dag-pitch__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dag-pitch-panel); box-shadow: inset 0 0 0 1px var(--dag-pitch-line); overflow: hidden; }
.dag-pitch__ph { display: flex; align-items: start; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; padding: 14px 16px 8px; & > div:first-child { flex: 1 1 220px; min-width: 0; } & h3 { font-size: 14px; font-weight: 650; letter-spacing: -.01em; } & p { font-size: 11.5px; color: var(--dag-pitch-faint); margin-top: 2px; } }
.dag-pitch__seg {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--dag-pitch-hair); box-shadow: inset 0 0 0 1px var(--dag-pitch-line);
  & button { height: 24px; padding: 0 10px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--dag-pitch-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dag-pitch-ink); }
  & button[aria-checked="true"] { background: var(--dag-pitch-raise); color: var(--dag-pitch-ink); box-shadow: inset 0 0 0 1px var(--dag-pitch-line); }
}
.dag-pitch__btn {
  height: 32px; padding: 0 14px; border-radius: 9px; font-size: 12.5px; font-weight: 650; white-space: nowrap;
  color: var(--dag-pitch-bg); background: var(--dag-pitch-accent); transition: filter .15s, background-color .15s;
  &:hover:not(:disabled) { filter: brightness(1.08); }
  &.is-ghost { color: var(--dag-pitch-ink); background: transparent; box-shadow: inset 0 0 0 1px var(--dag-pitch-line); }
  &.is-ghost:hover { background: var(--dag-pitch-hair); }
  &:disabled { opacity: .45; }
}

/* ---------- board ---------- */
.dag-pitch__boardv { position: relative; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; }
.dag-pitch__tools { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.dag-pitch__hint { font-size: 11.5px; color: var(--dag-pitch-faint); margin-right: auto; & kbd { font: 600 10px var(--dag-pitch-mono); padding: 1px 5px; border-radius: 4px; background: var(--dag-pitch-hair); box-shadow: inset 0 -1px 0 var(--dag-pitch-line); color: var(--dag-pitch-mute); } }
.dag-pitch__srcchip {
  display: inline-flex; align-items: center; gap: 4px; height: 28px; padding: 0 4px 0 10px; border-radius: 8px; font-size: 12px; color: var(--dag-pitch-mute);
  background: color-mix(in oklch, var(--dag-pitch-accent) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dag-pitch-accent) 40%, transparent);
  & b { color: var(--dag-pitch-ink); font-weight: 650; }
  & button { width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; color: var(--dag-pitch-ink); }
  & button:hover { background: var(--dag-pitch-hair); }
  & .dag-pitch-i { width: 14px; height: 14px; }
}
.dag-pitch__board {
  min-height: 0; height: 100%; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(164px, 1fr); gap: 10px;
  overflow-x: auto; overflow-y: hidden; scroll-snap-type: x proximity; scroll-padding: 0 4px;
}
.dag-pitch__col {
  min-height: 0; display: flex; flex-direction: column; border-radius: 13px; scroll-snap-align: start;
  background: color-mix(in oklch, var(--dag-pitch-panel), transparent 30%); box-shadow: inset 0 0 0 1px var(--dag-pitch-hair);
  transition: background-color .2s, box-shadow .2s;
  & > header { padding: 10px 11px 9px; display: grid; gap: 3px; }
  & > header div { display: flex; align-items: center; gap: 7px; }
  & > header b { font-size: 12.5px; font-weight: 680; letter-spacing: -.005em; }
  & > header div span { font: 650 10px var(--dag-pitch-mono); padding: 1px 5px; border-radius: 5px; color: var(--dag-pitch-bg); background: var(--dag-pitch-s4); background: color-mix(in oklch, var(--dag-pitch-accent) calc(30% + var(--si) * 17.5%), var(--dag-pitch-panel)); }
  & > header p { font: 500 11px var(--dag-pitch-mono); color: var(--dag-pitch-faint); font-variant-numeric: tabular-nums; display: flex; align-items: center; gap: 6px; }
  & > header p em { font-style: normal; color: var(--dag-pitch-accent); }
  & .dag-pitch__n { min-width: 18px; height: 17px; padding: 0 5px; border-radius: 5px; display: grid; place-items: center; color: var(--dag-pitch-ink); background: var(--dag-pitch-hair); }
  &.is-over { background: color-mix(in oklch, var(--dag-pitch-accent) 9%, var(--dag-pitch-panel)); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--dag-pitch-accent) 55%, transparent); }
  &:has(.dag-pitch__card.is-lift) { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--dag-pitch-accent) 55%, transparent); }
}
.dag-pitch__cbar { height: 3px; border-radius: 2px; margin-top: 4px; background: var(--dag-pitch-hair); overflow: hidden; position: relative; &::after { content: ""; position: absolute; inset: 0; transform-origin: left; transform: scaleX(var(--p)); background: color-mix(in oklch, var(--dag-pitch-accent) calc(30% + var(--si) * 17.5%), var(--dag-pitch-panel)); transition: transform .6s var(--dag-pitch-out); } }
.dag-pitch__list { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 8px 10px; display: flex; flex-direction: column; gap: 7px; }
.dag-pitch__empty { font-size: 11.5px; color: var(--dag-pitch-faint); padding: 18px 6px; text-align: center; border-radius: 10px; border: 1px dashed var(--dag-pitch-line); list-style: none; }
.dag-pitch__card {
  position: relative; flex: none; display: grid; gap: 4px; padding: 10px 11px 9px; border-radius: 11px; cursor: grab; touch-action: pan-x pan-y;
  background: var(--dag-pitch-raise); box-shadow: inset 0 0 0 1px var(--dag-pitch-line), 0 1px 0 oklch(0 0 0 / .25);
  transition: box-shadow .2s, background-color .2s, translate .25s var(--dag-pitch-out), scale .3s var(--dag-pitch-spring), rotate .3s var(--dag-pitch-spring);
  .dag-pitch__board:not(.is-settled) & { animation: dag-pitch-rise .55s var(--dag-pitch-out) both; animation-delay: calc(var(--si, 0) * 70ms + var(--i) * 45ms); }
  &:hover { background: color-mix(in oklch, var(--dag-pitch-raise), var(--dag-pitch-ink) 4%); translate: 0 -1px; }
  &:focus-visible { outline: 2px solid var(--dag-pitch-accent); outline-offset: 2px; }
  &.is-open { box-shadow: inset 0 0 0 1.5px var(--dag-pitch-accent); }
  &.is-lift { scale: 1.035; rotate: -1.2deg; z-index: 2; box-shadow: inset 0 0 0 1.5px var(--dag-pitch-accent), 0 18px 34px -14px oklch(0 0 0 / .8); }
  &.is-ph { background: transparent; box-shadow: none; outline: 1.5px dashed color-mix(in oklch, var(--dag-pitch-accent) 70%, transparent); outline-offset: -1.5px; & > * { visibility: hidden; } }
  &.is-landing { visibility: hidden; }
  &.is-won { background: color-mix(in oklch, var(--dag-pitch-accent) 11%, var(--dag-pitch-raise)); }
}
.dag-pitch__col { --si: 0; }
.dag-pitch__c1 { display: flex; align-items: baseline; gap: 6px; min-width: 0; & b { font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: -.01em; } }
.dag-pitch__src { margin-left: auto; flex: none; font: 600 9.5px var(--dag-pitch-mono); letter-spacing: .04em; text-transform: uppercase; color: var(--dag-pitch-faint); }
.dag-pitch__job { font-size: 11.5px; color: var(--dag-pitch-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dag-pitch__c2 { display: flex; align-items: baseline; gap: 7px; flex-wrap: wrap; & strong { font-size: 15px; font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; } & em { font: 500 10.5px var(--dag-pitch-mono); font-style: normal; color: var(--dag-pitch-accent); } }
.dag-pitch__c3 { display: flex; align-items: center; gap: 6px; margin-top: 2px; min-width: 0; font-size: 11px; color: var(--dag-pitch-faint); }
.dag-pitch__av { width: 19px; height: 19px; border-radius: 50%; flex: none; display: grid; place-items: center; font: 700 8px system-ui, sans-serif; color: oklch(0.22 0.03 30); background: var(--c); }
.dag-pitch__next { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; & b { font-weight: 600; color: var(--dag-pitch-mute); } }
.dag-pitch__age { margin-left: auto; flex: none; font: 600 10px var(--dag-pitch-mono); padding: 1px 5px; border-radius: 5px; background: var(--dag-pitch-hair); .is-stale & { color: var(--dag-pitch-bg); background: var(--dag-pitch-lost); } }
.dag-pitch__float {
  position: absolute; left: 0; top: 0; z-index: 60; pointer-events: none; display: grid; gap: 4px; padding: 10px 11px 9px; border-radius: 11px;
  background: color-mix(in oklch, var(--dag-pitch-raise), var(--dag-pitch-ink) 6%); scale: 1.03; rotate: -2deg; cursor: grabbing;
  box-shadow: inset 0 0 0 1.5px var(--dag-pitch-accent), 0 26px 44px -16px oklch(0 0 0 / .85), 0 6px 14px -6px oklch(0 0 0 / .5);
  &.is-won { background: color-mix(in oklch, var(--dag-pitch-accent) 16%, var(--dag-pitch-raise)); }
}
.dag-pitch.is-dragging { cursor: grabbing; & .dag-pitch__card { cursor: grabbing; } }
.dag-pitch__lost {
  position: absolute; left: 50%; bottom: 6px; z-index: 20; display: flex; align-items: center; gap: 8px; height: 44px; padding: 0 22px; border-radius: 12px;
  font-size: 12.5px; font-weight: 650; color: var(--dag-pitch-lost); background: color-mix(in oklch, var(--dag-pitch-bg), var(--dag-pitch-lost) 14%);
  box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--dag-pitch-lost) 55%, transparent), 0 16px 30px -12px oklch(0 0 0 / .7);
  translate: -50% 70px; opacity: 0; pointer-events: none; transition: translate .4s var(--dag-pitch-out), opacity .2s, background-color .15s, scale .3s var(--dag-pitch-spring);
  .dag-pitch.is-dragging & { translate: -50% 0; opacity: 1; pointer-events: auto; }
  &.is-hot { color: var(--dag-pitch-bg); background: var(--dag-pitch-lost); scale: 1.06; }
}

/* ---------- drawer ---------- */
.dag-pitch__drawer {
  position: absolute; z-index: 40; top: 12px; right: 12px; bottom: 12px; width: min(350px, calc(100% - 24px)); overflow: auto; overscroll-behavior: contain; scrollbar-width: thin;
  display: flex; flex-direction: column; gap: 14px; padding: 16px; border-radius: 16px;
  background: color-mix(in oklch, var(--dag-pitch-bg), var(--dag-pitch-ink) 9%);
  box-shadow: inset 0 0 0 1px var(--dag-pitch-line), 0 30px 60px -20px oklch(0 0 0 / .8);
  transition: translate .45s var(--dag-pitch-out), opacity .25s;
  @starting-style { translate: 24px 0; opacity: 0; }
}
.dag-pitch__dh { display: flex; align-items: start; gap: 10px; & > div { flex: 1; min-width: 0; } & h3 { margin-top: 4px; font-size: 19px; font-weight: 720; letter-spacing: -.03em; line-height: 1.15; } & p { font-size: 12.5px; color: var(--dag-pitch-mute); } & .dag-pitch__eb { color: var(--dag-pitch-faint); } }
.dag-pitch__x { width: 30px; height: 30px; flex: none; border-radius: 8px; display: grid; place-items: center; color: var(--dag-pitch-mute); &:hover { background: var(--dag-pitch-hair); color: var(--dag-pitch-ink); } }
.dag-pitch__steps {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px;
  & button { display: grid; gap: 5px; justify-items: start; padding: 0 0 2px; font-size: 10px; font-weight: 600; color: var(--dag-pitch-faint); text-align: left; min-width: 0; }
  & button span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
  & button i { width: 100%; height: 6px; border-radius: 3px; background: var(--dag-pitch-hair); transition: background-color .3s; }
  & button.is-past i { background: var(--dag-pitch-s2); }
  & button[aria-checked="true"] { color: var(--dag-pitch-ink); }
  & button[aria-checked="true"] i { background: var(--dag-pitch-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dag-pitch-accent) 22%, transparent); }
  & button:hover:not([aria-checked="true"]) { color: var(--dag-pitch-mute); & i { background: var(--dag-pitch-line); } }
}
.dag-pitch__facts {
  display: grid; grid-template-columns: 1fr 1fr; border-radius: 12px; box-shadow: inset 0 0 0 1px var(--dag-pitch-line); overflow: hidden;
  & div { padding: 9px 11px; display: grid; gap: 1px; }
  & div:nth-child(odd) { border-right: 1px solid var(--dag-pitch-hair); }
  & div:nth-child(-n+2) { border-bottom: 1px solid var(--dag-pitch-hair); }
  & dt { font-size: 10.5px; color: var(--dag-pitch-faint); }
  & dd { margin: 0; font-size: 14px; font-weight: 650; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
}
.dag-pitch__nextb { padding: 10px 12px; border-radius: 12px; background: var(--dag-pitch-hair); display: grid; gap: 2px; & b { font-size: 13.5px; font-weight: 650; } & small { font-size: 11.5px; color: var(--dag-pitch-faint); } &.is-stale small { color: var(--dag-pitch-lost); } }
.dag-pitch__spread { display: grid; gap: 8px; & .dag-pitch__eb { color: var(--dag-pitch-faint); } }
.dag-pitch__sb {
  display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 5px; align-items: end;
  & span { display: grid; gap: 3px; justify-items: center; }
  & i { width: 100%; height: 44px; border-radius: 5px; background: var(--dag-pitch-hair); position: relative; overflow: hidden; }
  & i em { position: absolute; inset: auto 0 0; height: calc(var(--h) * 100%); background: color-mix(in oklch, var(--dag-pitch-accent) 26%, transparent); transform-origin: bottom; animation: dag-pitch-grow .6s var(--dag-pitch-out) both; animation-delay: calc(var(--i) * 50ms); }
  & i em::after { content: ""; position: absolute; inset: auto 0 0; height: calc(var(--w) * 100%); background: var(--dag-pitch-accent); }
  & b { font: 600 10px var(--dag-pitch-mono); color: var(--dag-pitch-mute); }
  & small { font-size: 10px; color: var(--dag-pitch-faint); }
}
.dag-pitch__last { font-size: 12px; color: var(--dag-pitch-mute); padding-left: 10px; border-left: 2px solid var(--dag-pitch-line); }
.dag-pitch__drawer footer { margin-top: auto; display: flex; justify-content: space-between; gap: 8px; padding-top: 4px; }

/* ---------- lost dialog, tooltip, toast ---------- */
.dag-pitch__scrim { position: absolute; inset: 0; z-index: 70; background: color-mix(in oklch, var(--dag-pitch-bg) 62%, transparent); backdrop-filter: blur(2px); transition: opacity .25s; @starting-style { opacity: 0; } }
.dag-pitch__ask {
  position: absolute; z-index: 71; left: 50%; top: 50%; translate: -50% -50%; width: min(380px, calc(100% - 32px)); padding: 18px; border-radius: 16px; display: grid; gap: 10px;
  background: color-mix(in oklch, var(--dag-pitch-bg), var(--dag-pitch-ink) 10%); box-shadow: inset 0 0 0 1px var(--dag-pitch-line), 0 30px 60px -20px oklch(0 0 0 / .85);
  transition: scale .35s var(--dag-pitch-spring), opacity .2s;
  @starting-style { scale: .94; opacity: 0; }
  & h4 { font-size: 16px; font-weight: 700; letter-spacing: -.02em; }
  & p { font-size: 12.5px; color: var(--dag-pitch-mute); }
  & > .dag-pitch__btn { justify-self: end; }
}
.dag-pitch__askopts { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; & .dag-pitch__btn { height: 40px; white-space: normal; line-height: 1.2; text-align: left; } & .dag-pitch__btn:hover { box-shadow: inset 0 0 0 1px var(--dag-pitch-lost); color: var(--dag-pitch-lost); } }
.dag-pitch__tip {
  position: absolute; left: 0; top: 0; z-index: 80; pointer-events: none; min-width: 170px; max-width: 280px; padding: 9px 11px; border-radius: 10px;
  background: var(--dag-pitch-ink); color: var(--dag-pitch-bg); font-size: 12px; line-height: 1.45; font-variant-numeric: tabular-nums;
  box-shadow: 0 16px 32px -12px oklch(0 0 0 / .7); opacity: 0; transition: opacity .12s;
  &.is-on { opacity: 1; }
  & .dag-pitch__tt { display: block; font: 650 10.5px var(--dag-pitch-mono); letter-spacing: .05em; text-transform: uppercase; opacity: .62; margin-bottom: 3px; }
  & .dag-pitch__tr { display: flex; justify-content: space-between; gap: 16px; }
  & .dag-pitch__tr span { display: inline-flex; align-items: center; gap: 6px; opacity: .82; }
  & .dag-pitch__tr i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .25); }
}
.dag-pitch__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 90; display: flex; align-items: center; gap: 12px; max-width: min(520px, calc(100% - 32px));
  padding: 9px 9px 9px 16px; border-radius: 12px; background: var(--dag-pitch-ink); color: var(--dag-pitch-bg); font-size: 12.5px; font-weight: 600;
  box-shadow: 0 18px 36px -14px oklch(0 0 0 / .7);
  translate: -50% 20px; opacity: 0; pointer-events: none; transition: translate .45s var(--dag-pitch-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  & button { height: 26px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 700; color: var(--dag-pitch-ink); background: var(--dag-pitch-bg); }
  & button:hover { background: color-mix(in oklch, var(--dag-pitch-bg), var(--dag-pitch-ink) 18%); }
  & button[hidden] { display: none; }
}

/* ---------- forecast ---------- */
.dag-pitch__fcv { display: grid; grid-template-columns: minmax(0, 1fr) 290px; gap: 12px; }
.dag-pitch__chart { flex: 1; min-height: 190px; position: relative; margin: 0 10px; cursor: crosshair; border-radius: 10px; }
.dag-pitch__chart svg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dag-pitch__grid line { stroke: var(--dag-pitch-hair); }
  & .dag-pitch__ax { fill: var(--dag-pitch-faint); font: 500 10px var(--dag-pitch-mono); }
  & .dag-pitch__ax.is-m { fill: var(--dag-pitch-mute); font-weight: 650; }
  & .dag-pitch__band { fill: var(--dag-pitch-ink); opacity: 0; transition: x .35s var(--dag-pitch-out), opacity .15s; }
  & .dag-pitch__band.is-sel { opacity: .055; }
  & .dag-pitch__band.is-hov.is-on { opacity: .035; }
  & .dag-pitch__b { transition: y .75s var(--dag-pitch-out), height .75s var(--dag-pitch-out); transition-delay: calc(var(--i) * 40ms); }
  & .is-con { fill: color-mix(in oklch, var(--dag-pitch-ink) 82%, var(--dag-pitch-bg)); }
  & .is-nego { fill: var(--dag-pitch-s3); }
  & .is-prop { fill: var(--dag-pitch-s2); }
  & .is-qual { fill: var(--dag-pitch-s1); }
  & .is-lead { fill: var(--dag-pitch-s0); }
  & .dag-pitch__gap { fill: color-mix(in oklch, var(--dag-pitch-lost) 7%, transparent); stroke: color-mix(in oklch, var(--dag-pitch-lost) 70%, transparent); stroke-width: 1.25; stroke-dasharray: 3 3; opacity: 0; transition: y .75s var(--dag-pitch-out), height .75s var(--dag-pitch-out), opacity .3s; transition-delay: calc(var(--i) * 40ms); }
  & .dag-pitch__gap.is-on { opacity: 1; }
  & .dag-pitch__tot { fill: var(--dag-pitch-ink); font: 650 10.5px var(--dag-pitch-mono); transition: transform .75s var(--dag-pitch-out); transition-delay: calc(var(--i) * 40ms); }
  & .dag-pitch__capl { fill: none; stroke: var(--dag-pitch-ink); stroke-width: 1.5; stroke-dasharray: 6 4; opacity: .7; }
  & .dag-pitch__capt { fill: var(--dag-pitch-ink); font: 650 10px var(--dag-pitch-mono); opacity: .8; }
}
.dag-pitch__ftw { flex: none; margin: 4px 10px 10px; overflow-x: auto; }
.dag-pitch__ft {
  min-width: 460px; font-size: 11.5px; font-variant-numeric: tabular-nums;
  & th, & td { padding: 4px 8px; text-align: right; white-space: nowrap; border-top: 1px solid var(--dag-pitch-hair); }
  & thead th { border-top: 0; padding-bottom: 3px; }
  & th[scope="row"] { text-align: left; font-weight: 550; color: var(--dag-pitch-mute); }
  & td { font-family: var(--dag-pitch-mono); font-size: 11px; color: var(--dag-pitch-mute); transition: background-color .2s; }
