const RM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const GBP = (v) => (v < 0 ? '−' : '') + '£' + Math.round(Math.abs(v)).toLocaleString('en-GB');
const K = (v) => { const a = Math.abs(v), s = v < 0 ? '−' : ''; if (a >= 1e6) return s + '£' + (a / 1e6).toFixed(2) + 'm'; if (a >= 1e3) return s + '£' + String(Math.round(a / 100) / 10).replace(/\.0$/, '') + 'k'; return s + '£' + Math.round(a); };
