const SI = {}; STAGES.forEach((s, i) => { SI[s.k] = i; });
const OPEN = ['nego', 'prop', 'qual', 'lead'];
const OWN = {
  in: { name: 'Iris Novak', role: 'Managing director', c: 'oklch(0.8 0.1 25)', target: 250000 },
