const OTHER = [98000, 92500, 81000, 64000, 52500, 48000]; /* retainers and projects signed before H2 */
const CAPM = 195000; /* what the studio can deliver in a month */
/* last 12 months, excluding the four deals still on the board as won */
const SOURCES = [
