  ['corrie', 'Corrie Health', 'Patient booking redesign', 140000, 'ao', 'Tender', 'qual', 15, 2, 5, 'Shortlist Q&A', 'Wed 7 Oct', 'Through to a shortlist of four'],
  ['northwind', 'Northwind Ferries', 'Brand and booking refresh', 64000, 'cp', 'Referral', 'qual', 9, 1, 4, 'Chemistry meeting', 'Thu 8 Oct', 'Referred by their former CMO'],
  ['ostara', 'Ostara Skincare', 'Subscription storefront', 56000, 'in', 'Inbound', 'qual', 21, 2, 4, 'Confirm budget', 'Fri 9 Oct', 'Budget still sitting with their CFO'],
  ['haverly', 'Haverly Building Society', 'Mortgage tools', 120000, 'jw', 'Tender', 'prop', 8, 1, 4, 'Pitch presentation', 'Tue 13 Oct', 'Written response submitted 24 Sep'],
  ['pinewood', 'Pinewood Schools Trust', 'Parent comms app', 78000, 'ao', 'Referral', 'prop', 4, 1, 3, 'Proposal walkthrough', 'Thu 8 Oct', 'Proposal sent 28 Sep'],
