  ['halden', 'Halden Furniture', 'Spring campaign', 72000, 'in', 'Existing client', 'nego', 11, 1, 4, 'SOW sign-off', 'Fri 9 Oct', 'Verbal yes from their marketing lead'],
  ['marlow', 'Marlow Bikes', 'Configurator phase 2', 84000, 'jw', 'Existing client', 'won', 18, 0, 4, 'Signed', '14 Sep', 'Signed 14 Sep'],
  ['lumen', 'Lumen Dental', 'Booking flow', 42000, 'cp', 'Referral', 'won', 60, -1, 3, 'Signed', '3 Aug', 'Signed 3 Aug'],
  ['ashby', 'Ashby Museum', 'Collections site', 68000, 'ao', 'Tender', 'won', 66, -1, 4, 'Signed', '28 Jul', 'Signed 28 Jul'],
  ['parcel', 'Parcelpoint', 'Driver app v2', 216000, 'jw', 'Referral', 'won', 85, -2, 6, 'Signed', '9 Jul', 'Signed 9 Jul']
