const byId = {}; DEALS.forEach((d) => { byId[d.id] = d; });
const ORDER = {}; STAGES.forEach((s) => { ORDER[s.k] = DEALS.filter((d) => d.stage === s.k).map((d) => d.id); });

/* ------------------------------------------------------------------ state */
const S = { view: 'board', owner: 'all', sort: 'manual', src: null, open: null, lift: null, focus: null, month: 3, fmode: 'weighted', press: null, drag: null, ask: null, settled: false };
const P = (d) => STAGES[SI[d.stage]].p;
const ownerOk = (d) => S.owner === 'all' || d.own === S.owner;
