function restore(s) { STAGES.forEach((st) => { ORDER[st.k] = s.order[st.k].slice(); }); DEALS.forEach((d, i) => { [d.stage, d.days, d.next, d.due, d.lost] = s.d[i]; }); }
function sums() {
  const ds = DEALS.filter((d) => !d.lost && ownerOk(d)), st = {};
  STAGES.forEach((s) => { const x = ds.filter((d) => d.stage === s.k); st[s.k] = { n: x.length, v: x.reduce((a, d) => a + d.v, 0), w: x.reduce((a, d) => a + d.v * s.p, 0) }; });
  const won = st.won.v, open = OPEN.reduce((a, k) => a + st[k].w, 0), openV = OPEN.reduce((a, k) => a + st[k].v, 0), openN = OPEN.reduce((a, k) => a + st[k].n, 0);
