/* ------------------------------------------------------------------ small helpers */
const tip = $('.dag-pitch__tip'), board = $('.dag-pitch__board'), drawer = $('.dag-pitch__drawer'), ask = $('.dag-pitch__ask'), scrim = $('[data-scrim]');
function showTip(html, x, y) {
  tip.innerHTML = html;
  tip.classList.add('is-on');
  const rb = root.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let l = x - rb.left + 14, t = y - rb.top + 14;
  if (l + tw > rb.width - 8) l = x - rb.left - tw - 14;
  if (t + th > rb.height - 8) t = y - rb.top - th - 12;
