}
const hideTip = () => tip.classList.remove('is-on');
const trow = (l, v, c) => `<div class="dag-pitch__tr"><span>${c ? `<i style="--c:${c}"></i>` : ''}${l}</span><b>${v}</b></div>`;
const say = (m) => { const a = $('[data-announce]'); a.textContent = ''; setTimeout(() => { a.textContent = m; }, 30); };
