    const { H, W, pad, slot } = G, top = Math.max(...data.map((r) => r.tot), S.owner === 'all' ? CAPM : 0) * 1.1;
    const n = nice(top), y = (v) => pad.t + (1 - v / n.max) * (H - pad.t - pad.b);
    G.y = y; G.data = data;
    let g = '';
    for (let v = 0; v <= n.max; v += n.step) g += `<line x1="${pad.l}" x2="${W - pad.r}" y1="${y(v)}" y2="${y(v)}"/><text class="dag-pitch__ax" x="${pad.l - 8}" y="${y(v) + 3.5}" text-anchor="end">${K(v)}</text>`;
    $('.dag-pitch__grid', csvg).innerHTML = g;
    data.forEach((r, i) => {
      const grp = csvg.querySelector(`[data-m="${i}"]`);
      let acc = 0;
      KEYS.forEach((k) => { const v = k === 'con' ? r.con : r.pipe(k), el = grp.querySelector(`.is-${k}`); setR(el, y(acc + v), y(acc) - y(acc + v) - (v ? 1.5 : 0)); acc += v; });
      const gap = S.owner === 'all' ? Math.max(0, CAPM - r.tot) : 0, ge = grp.querySelector('.dag-pitch__gap');
      setR(ge, y(r.tot + gap), y(r.tot) - y(r.tot + gap) - 1);
      ge.classList.toggle('is-on', gap > 0);
      const t = grp.querySelector('.dag-pitch__tot');
      t.textContent = K(r.tot);
      t.style.transform = `translateY(${y(r.tot) - 7}px)`;
    });
    const cl = $('.dag-pitch__capl', csvg), ct = $('.dag-pitch__capt', csvg);
    cl.setAttribute('d', S.owner === 'all' ? `M${pad.l} ${y(CAPM)}H${W - pad.r}` : '');
    ct.setAttribute('x', W - pad.r); ct.setAttribute('y', y(CAPM) - 6);
    ct.textContent = S.owner === 'all' ? `Delivery capacity ${K(CAPM)}/mo` : '';
    $('.is-sel', csvg).setAttribute('x', pad.l + S.month * slot);
    $('.is-sel', csvg).style.x = (pad.l + S.month * slot) + 'px';
  }
  const cap = S.owner === 'all', lbl = S.fmode === 'all' ? 'Pipeline, if all land' : S.fmode === 'none' ? 'Pipeline (not counted)' : 'Pipeline, weighted';
  const row = (name, f, cls) => `<tr class="${cls || ''}"><th scope="row">${name}</th>${data.map((r, i) => `<td class="${i === S.month ? 'is-sel' : ''}">${f(r)}</td>`).join('')}</tr>`;
  $('.dag-pitch__ft').innerHTML = `<thead><tr><th scope="col"><span class="dag-pitch-sr">Row</span></th>${MON.map((m, i) => `<th scope="col"><button type="button" data-month="${i}"${i === S.month ? ' aria-current="true"' : ''}>${m}</button></th>`).join('')}</tr></thead><tbody>
    ${row(cap ? 'Contracted' : 'Contracted (won)', (r) => K(r.con))}${row(lbl, (r) => K(r.tot - r.con), 'is-pipe')}${row('Total', (r) => K(r.tot), 'is-tot')}
    ${cap ? row('Against capacity', (r) => { const g = r.tot - CAPM; return `<span class="${g < 0 ? 'is-neg' : 'is-pos'}">${g >= 0 ? '+' : ''}${K(g)}</span>`; }, 'is-gap') : ''}</tbody>`;
  renderMonth(data);
}
function renderMonth(data) {
  const r = data[S.month], list = r.deals.slice().sort((a, b) => b.w - a.w), mode = S.fmode, maxw = Math.max(1, ...list.map((x) => x.f));
  const g = r.tot - CAPM;
  $('.dag-pitch__mside').innerHTML = `<header class="dag-pitch__ph"><div><span class="dag-pitch__eb">Selected month</span><h3>${MONF[S.month]}</h3></div></header>
    <div class="dag-pitch__mbig"><b>${GBP(r.tot)}</b><span>${S.owner === 'all' ? (g < 0 ? `<em class="is-neg">${GBP(-g)} below capacity</em>` : `<em class="is-pos">${GBP(g)} over capacity</em>`) : 'for ' + OWN[S.owner].name}</span></div>
    <p class="dag-pitch__mnote">${S.owner === 'all' ? `${GBP(OTHER[S.month])} is already contracted from earlier work.` : 'Owner view: earlier contracted work is not attributed.'}</p>
    <ul class="dag-pitch__ml dag-pitch-scroll">${list.map((x, i) => { const won = x.d.stage === 'won', show = won ? x.f : mode === 'all' ? x.f : mode === 'none' ? 0 : x.w; return `<li style="--i:${i};--si:${SI[x.d.stage]}"><button type="button" data-opendeal="${x.d.id}"><span><b>${x.d.who}</b><small>${STAGES[SI[x.d.stage]].name}${won ? '' : ' · ' + Math.round(P(x.d) * 100) + '%'} · ${OWN[x.d.own].first}</small></span><i class="dag-pitch__mb"><em style="--p:${(x.f / maxw).toFixed(3)}"></em><em class="is-w" style="--p:${(show / maxw).toFixed(3)}"></em></i><strong>${K(show)}</strong></button></li>`; }).join('') || '<li class="dag-pitch__empty">No signed or open deals deliver in this month yet.</li>'}</ul>`;
}
function hoverMonth(i, cx, cy) {
  if (!G || !G.data) return;
  const r = G.data[i], hb = $('.is-hov', csvg);
  hb.setAttribute('x', G.pad.l + i * G.slot); hb.style.x = (G.pad.l + i * G.slot) + 'px'; hb.classList.add('is-on');
  const rows = [trow(S.owner === 'all' ? 'Contracted' : 'Won', K(r.con), 'var(--dag-pitch-ink)')].concat(OPEN.filter((k) => r.pipe(k)).map((k) => trow(STAGES[SI[k]].name + (S.fmode === 'weighted' ? ' (weighted)' : ''), K(r.pipe(k)), `var(--dag-pitch-s${SI[k]})`)));
  showTip(`<span class="dag-pitch__tt">${MONF[i]}</span>${rows.join('')}${trow('Total', K(r.tot))}${S.owner === 'all' ? trow(r.tot < CAPM ? 'Below capacity' : 'Over capacity', K(Math.abs(CAPM - r.tot))) : ''}`, cx, cy);
}
function monthAt(e) { const rb = chart.getBoundingClientRect(); return clamp(Math.floor((e.clientX - rb.left - G.pad.l) / G.slot), 0, 5); }
chart.addEventListener('pointermove', (e) => { if (!G) return; hoverMonth(monthAt(e), e.clientX, e.clientY); });
chart.addEventListener('pointerleave', () => { hideTip(); const h = $('.is-hov', csvg); if (h) h.classList.remove('is-on'); });
chart.addEventListener('click', (e) => { if (!G) return; S.month = monthAt(e); renderForecast(); });
chart.addEventListener('keydown', (e) => {
  if (!/^(ArrowLeft|ArrowRight|Home|End)$/.test(e.key)) return;
  e.preventDefault();
  S.month = e.key === 'Home' ? 0 : e.key === 'End' ? 5 : clamp(S.month + (e.key === 'ArrowRight' ? 1 : -1), 0, 5);
  renderForecast();
  const rb = chart.getBoundingClientRect();
  if (G) hoverMonth(S.month, rb.left + G.pad.l + (S.month + 0.5) * G.slot, rb.top + 40);
});
chart.addEventListener('blur', hideTip);

/* ------------------------------------------------------------------ win rate */
function renderWins() {
  const rows = SOURCES.map((s) => {
    const live = DEALS.filter((d) => d.src === s.k);
    const w = s.w + live.filter((d) => d.stage === 'won' && !d.lost).length, l = s.l + live.filter((d) => d.lost).length;
    return { ...s, w, l, open: live.filter((d) => !d.lost && d.stage !== 'won').length };
  });
  const max = Math.max(...rows.map((r) => Math.max(r.w, r.l))), W = rows.reduce((a, r) => a + r.w, 0), L = rows.reduce((a, r) => a + r.l, 0);
  $('.dag-pitch__fly').innerHTML = `<div class="dag-pitch__flyh"><span>Source</span><span class="is-c">Lost · Won</span><span>Win rate</span><span>Cycle</span><span>Open</span></div>` + rows.map((r, i) => `<button type="button" class="dag-pitch__fr" data-src="${r.k}" style="--i:${i}" ${r.open ? '' : 'aria-disabled="true" title="No open deals from this source"'} aria-label="${r.k}: won ${r.w}, lost ${r.l}, ${Math.round(r.w / (r.w + r.l) * 100)}% win rate. ${r.open ? 'Show its ' + r.open + ' open deals on the board' : 'No open deals'}">
      <span class="dag-pitch__fn"><b>${r.k}</b><small>${r.w + r.l} decided</small></span>
      <span class="dag-pitch__fb"><i class="is-l" style="--p:${(r.l / max).toFixed(3)}"><em>${r.l}</em></i><i class="is-w" style="--p:${(r.w / max).toFixed(3)}"><em>${r.w}</em></i></span>
      <span class="dag-pitch__fp"><b>${Math.round(r.w / (r.w + r.l) * 100)}%</b><i style="--p:${(r.w / (r.w + r.l)).toFixed(3)}"></i></span>
      <span class="dag-pitch__fd">${r.days} days</span>
      <span class="dag-pitch__fo">${r.open ? r.open + ' open →' : '—'}</span></button>`).join('') +
    `<div class="dag-pitch__flyt"><span><b>${Math.round(W / (W + L) * 100)}%</b> overall · ${W} won of ${W + L} decided</span>${S.owner !== 'all' ? '<span>Win rates are studio-wide; the owner filter does not apply.</span>' : '<span>Referral and existing clients close fastest and most often.</span>'}</div>`;
  const rs = REASONS.map(([k, l, n]) => ({ k, l, n: n + DEALS.filter((d) => d.lost === k).length, add: DEALS.filter((d) => d.lost === k).length }));
  const T = rs.reduce((a, r) => a + r.n, 0);
  $('.dag-pitch__reasons').innerHTML = `<div class="dag-pitch__rstack" aria-hidden="true">${rs.map((r, i) => `<i style="--p:${(r.n / T).toFixed(4)};--i:${i}"></i>`).join('')}</div>` +
    `<ul>${rs.map((r, i) => `<li style="--i:${i}"><i></i><span>${r.l}${r.add ? ` <em>+${r.add} today</em>` : ''}</span><b>${r.n}</b><small>${Math.round(r.n / T * 100)}%</small></li>`).join('')}</ul>` +
    `<p class="dag-pitch__rnote">${T} deals lost in 12 months. Price and timing account for ${Math.round((rs[0].n + rs[2].n) / T * 100)}% — both show up earlier when budget is confirmed at the Qualified stage.</p>`;
}

/* ------------------------------------------------------------------ orchestration */
const TITLES = { board: 'What could we sign by Christmas?', forecast: 'What the pipeline means for revenue', wins: 'Where we win, and why we don’t' };
function renderAll(flip) {
  renderSummary();
  if (S.view === 'board') renderBoard(flip);
  if (S.view === 'forecast') renderForecast();
  if (S.view === 'wins') renderWins();
}
function setView(v) {
  if (S.lift) setDown(false);
  S.view = v;
  closeDrawer(false);
  hideTip();
  $$('[data-go]').forEach((b) => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dag-pitch__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  root.dataset.view = v;
  $('[data-title]').textContent = TITLES[v];
  renderAll(false);
}
function setOwner(k) {
  S.owner = k;
  renderOwners();
  closeDrawer(false);
  renderAll(S.view === 'board');
}

root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if (S.suppress) return;
  if ((el = t.closest('[data-undo]'))) {
    if (!undoSnap) return;
    restore(undoSnap); undoSnap = null;
    closeDrawer(false);
    renderAll(true);
    return toast('Undone — the board is back as it was');
  }
  if (S.ask) {
    if ((el = t.closest('[data-reason]'))) return lose(el.dataset.reason);
    if (t.closest('[data-askcancel]') || t.closest('[data-scrim]')) { const s = S.ask.snap; restore(s); closeAsk(true); renderAll(true); return; }
    return;
  }
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if ((el = t.closest('[data-owner]'))) return setOwner(el.dataset.owner);
  if ((el = t.closest('[data-sort]'))) {
    S.sort = el.dataset.sort;
    $$('[data-sort]').forEach((b) => { b.setAttribute('aria-checked', b === el); b.tabIndex = b === el ? 0 : -1; });
    return renderBoard(true);
  }
  if ((el = t.closest('[data-fmode]'))) {
    S.fmode = el.dataset.fmode;
    $$('[data-fmode]').forEach((b) => { b.setAttribute('aria-checked', b === el); b.tabIndex = b === el ? 0 : -1; });
    return renderForecast();
  }
  if ((el = t.closest('[data-month]'))) { S.month = +el.dataset.month; return renderForecast(); }
  if ((el = t.closest('[data-opendeal]'))) { const id = el.dataset.opendeal; S.src = null; if (!ownerOk(byId[id])) setOwner('all'); setView('board'); focusCard(id); return openDrawer(id); }
  if ((el = t.closest('[data-src]'))) {
    if (el.getAttribute('aria-disabled') === 'true') return;
    S.src = el.dataset.src;
    setView('board');
    toast(`Showing open ${S.src.toLowerCase()} deals`);
    return;
  }
  if (t.closest('[data-clrsrc]')) { S.src = null; renderBoard(true); return toast('Source filter cleared'); }
  if (t.closest('[data-dclose]')) return closeDrawer(true);
  if ((el = t.closest('[data-stage]'))) return stageTo(el.dataset.stage);
  if (t.closest('[data-adv]')) { const d = byId[S.open]; return stageTo(STAGES[SI[d.stage] + 1].k); }
  if (t.closest('[data-lose]')) return openAsk(S.open);
  if ((el = t.closest('.dag-pitch__card'))) { if (S.lift) return; if (S.open === el.dataset.deal) return closeDrawer(true); return openDrawer(el.dataset.deal); }
  if (S.open && !t.closest('.dag-pitch__drawer') && !t.closest('.dag-pitch__toast')) closeDrawer(false);
});

root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (S.ask) {
    if (e.key === 'Escape') { e.preventDefault(); const s = S.ask.snap; restore(s); closeAsk(true); renderAll(true); return; }
    if (e.key === 'Tab') { const f = $$('button', ask); const i = f.indexOf(document.activeElement); if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); } else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); } }
    return;
  }
  if (S.drag && e.key === 'Escape') { e.preventDefault(); endDrag(false); return; }
  const card = t.closest && t.closest('.dag-pitch__card');
  if (card && S.lift) {
    if (/^Arrow/.test(e.key)) { e.preventDefault(); carry(e.key); return; }
    if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); setDown(true); return; }
    if (e.key === 'Escape') { e.preventDefault(); setDown(false); return; }
    if (e.key === 'Tab') { setDown(true); return; }
  }
  if (card) {
    if (e.key === 'Enter') { e.preventDefault(); if (S.open === card.dataset.deal) closeDrawer(true); else openDrawer(card.dataset.deal); return; }
    if (e.key === ' ') { e.preventDefault(); closeDrawer(false); lift(card.dataset.deal); return; }
    if (/^Arrow/.test(e.key)) { e.preventDefault(); arrowFocus(card, e.key); return; }
  }
  if (e.key === 'Escape' && S.open) { e.preventDefault(); closeDrawer(true); return; }
  const r = t.closest && t.closest('[role="radio"]');
  if (r && /^Arrow(Left|Right|Up|Down)$/.test(e.key)) {
    e.preventDefault();
    const g = $$('[role="radio"]', r.parentElement), i = (g.indexOf(r) + (/Right|Down/.test(e.key) ? 1 : -1) + g.length) % g.length;
    g[i].focus(); g[i].click();
  }
});

root.addEventListener('pointerdown', (e) => {
  const card = e.target.closest('.dag-pitch__card');
  if (!card || e.button !== 0 || S.lift || S.ask || !e.isPrimary) return;
  S.press = { id: card.dataset.deal, x0: e.clientX, y0: e.clientY, card };
});
root.addEventListener('pointermove', (e) => {
  if (S.press && !S.drag && Math.hypot(e.clientX - S.press.x0, e.clientY - S.press.y0) > 6) startDrag(e);
  if (S.drag) { S.drag.x = e.clientX; S.drag.y = e.clientY; posFloat(); dragOver(); return; }
  const t = e.target;
  if (t.closest('.dag-pitch__chart')) return;
  const seg = t.closest('[data-seg]');
  if (seg) {
    const k = seg.dataset.seg, m = sums(), s = m.st[k];
    return showTip(`<span class="dag-pitch__tt">${STAGES[SI[k]].name}</span>${trow(s.n + ' deal' + (s.n === 1 ? '' : 's'), GBP(s.v))}${k === 'won' ? '' : trow('At ' + Math.round(STAGES[SI[k]].p * 100) + '%', GBP(s.w))}${trow('Share of forecast', Math.round((k === 'won' ? s.v : s.w) / m.fc * 100) + '%')}`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerup', () => { if (S.drag) endDrag(true); S.press = null; });
root.addEventListener('pointercancel', () => { if (S.drag) endDrag(false); S.press = null; });
root.addEventListener('lostpointercapture', () => { if (S.drag) endDrag(true); });
root.addEventListener('pointerleave', () => { if (!S.drag) hideTip(); });
board.addEventListener('scroll', hideTip, { passive: true });

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (S.view === 'forecast') renderForecast();
});
ro.observe(chart);

/* ------------------------------------------------------------------ mount */
root.dataset.view = 'board';
renderOwners();
renderAll(false);

css:
.dag-health {
  width: 100%;
  height: var(--dag-health-h, 680px);
  container-type: inline-size;
  container-name: dag-health;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-health-bg);
  color: var(--dag-health-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-health-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-health-focus, var(--dag-health-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-health-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-health-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-health-num { font-variant-numeric: tabular-nums; }
  & .dag-health-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-health-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-health-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

@property --dag-health-arc { syntax: "<number>"; inherits: true; initial-value: 0; }

.dag-health {
  /* re-theme with these four */
  --dag-health-bg: oklch(0.972 0.005 95);
  --dag-health-ink: oklch(0.2 0.012 60);
  --dag-health-good: oklch(0.53 0.085 188);
  --dag-health-bad: oklch(0.6 0.16 38);
  /* derived */
  --dag-health-warn: color-mix(in oklch, var(--dag-health-bad), oklch(0.83 0.15 85) 62%);
  --dag-health-panel: color-mix(in oklch, var(--dag-health-bg), oklch(1 0 0) 72%);
  --dag-health-line: color-mix(in oklch, var(--dag-health-ink) 12%, transparent);
  --dag-health-hair: color-mix(in oklch, var(--dag-health-ink) 6.5%, transparent);
  --dag-health-mute: color-mix(in oklch, var(--dag-health-ink) 72%, var(--dag-health-bg));
  --dag-health-faint: color-mix(in oklch, var(--dag-health-ink) 50%, var(--dag-health-bg));
  --dag-health-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-health-out: cubic-bezier(.16, 1, .3, 1);
  --dag-health-spring: linear(0, .09 3%, .34 8%, .68 14%, .95 21%, 1.06 27%, 1.08 32%, 1.05 39%, 1.01 50%, .997 63%, 1);
  color-scheme: light;
  border-radius: 18px;
  box-shadow: inset 0 0 0 1px var(--dag-health-line);
}

.dag-health__app {
  height: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 284px;
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "top top" "strip model" "main model";
  column-gap: 14px;
  padding: 0 18px 18px;
}

/* ---------- top bar ---------- */
.dag-health__top { grid-area: top; display: flex; align-items: center; gap: 18px; height: 58px; margin: 0 -18px 16px; padding: 0 18px; border-bottom: 1px solid var(--dag-health-line); }
.dag-health__brand { display: flex; align-items: center; gap: 10px; & > span:last-child { display: grid; line-height: 1.15; } & b { font-size: 14px; font-weight: 750; letter-spacing: -.02em; } & small { font-size: 11px; color: var(--dag-health-faint); } }
.dag-health__mark { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; color: var(--dag-health-panel); background: var(--dag-health-ink); }
.dag-health__tabs {
  display: flex; gap: 2px; margin-left: 8px;
  & button { position: relative; height: 34px; display: inline-flex; align-items: center; gap: 7px; padding: 0 12px; border-radius: 9px; font-size: 13px; font-weight: 600; color: var(--dag-health-mute); transition: color .15s, background-color .15s; }
  & button:hover { color: var(--dag-health-ink); background: var(--dag-health-hair); }
  & button[aria-current="page"] { color: var(--dag-health-ink); }
  & button[aria-current="page"]::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -12px; height: 2px; border-radius: 1px; background: var(--dag-health-ink); }
  & .dag-health-i { width: 17px; height: 17px; }
}
.dag-health__meta { margin-left: auto; font: 500 11px var(--dag-health-mono); color: var(--dag-health-faint); }
