/* ---------- matrix ---------- */
.dag-health__main { grid-area: main; min-height: 0; display: grid; border-radius: 14px; background: var(--dag-health-panel); box-shadow: inset 0 0 0 1px var(--dag-health-line); overflow: hidden; }
.dag-health__view { min-height: 0; min-width: 0; display: grid; }
.dag-health__tw { min-height: 0; }
.dag-health__t {
  min-width: 720px; font-size: 12.5px;
  & thead th { position: sticky; top: 0; z-index: 3; background: var(--dag-health-panel); padding: 10px 6px 8px; text-align: center; vertical-align: bottom; border-bottom: 1px solid var(--dag-health-line); white-space: nowrap; }
  & thead th button { display: inline-flex; align-items: center; gap: 4px; font: 650 10px var(--dag-health-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-health-faint); padding: 3px 4px; border-radius: 5px; transition: color .15s, background-color .15s; }
  & thead th button:hover { color: var(--dag-health-ink); background: var(--dag-health-hair); }
  & thead th[aria-sort="ascending"] button, & thead th[aria-sort="descending"] button { color: var(--dag-health-ink); }
  & thead th button svg { width: 8px; height: 8px; }
  & thead .is-name { text-align: left; padding-left: 14px; }
  & thead .is-name, & tbody th.is-name { position: sticky; left: 0; }
  & thead .is-name { z-index: 4; }
  & .dag-health__wt { display: grid; grid-template-columns: 1fr; justify-items: center; gap: 3px; margin-top: 4px; font: 650 11px var(--dag-health-mono); color: var(--dag-health-ink); font-variant-numeric: tabular-nums; }
  & .dag-health__wt i { width: 44px; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--dag-health-ink) calc(var(--p) * 200%), var(--dag-health-hair) 0); transition: background .3s; order: 2; }
  & tbody tr { cursor: pointer; transition: background-color .15s; --bc: var(--dag-health-good); }
  & tbody tr.is-watch { --bc: var(--dag-health-warn); }
  & tbody tr.is-risk { --bc: var(--dag-health-bad); }
  & tbody tr:hover, & tbody tr:hover th.is-name { background: color-mix(in oklch, var(--dag-health-panel), var(--dag-health-ink) 3%); }
  & tbody tr.is-open, & tbody tr.is-open th.is-name { background: color-mix(in oklch, var(--dag-health-panel), var(--bc) 8%); }
  & tbody th, & tbody td { padding: 6px; border-bottom: 1px solid var(--dag-health-hair); text-align: center; }
  & tbody th.is-name { text-align: left; padding: 0; z-index: 2; background: var(--dag-health-panel); box-shadow: inset 3px 0 0 var(--bc); transition: box-shadow .4s, background-color .15s; }
  & .dag-health__none td { padding: 40px 12px; color: var(--dag-health-faint); }
}
.dag-health__cn {
  width: 100%; min-width: 0; display: grid; text-align: left; padding: 7px 10px 7px 15px; border-radius: 0;
  & b { display: flex; align-items: center; gap: 5px; font-size: 13px; font-weight: 650; letter-spacing: -.01em; white-space: nowrap; }
  & small { font-size: 11px; color: var(--dag-health-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
