}
.dag-health__flag { color: var(--dag-health-bad); display: inline-grid; & .dag-health-i { width: 13px; height: 13px; stroke-width: 2.2; } }
.dag-health__t td.is-score { min-width: 70px; text-align: left; padding-left: 10px; }
.dag-health__sv { display: block; font-size: 18px; font-weight: 780; letter-spacing: -.04em; line-height: 1.05; font-variant-numeric: tabular-nums; color: color-mix(in oklch, var(--bc) 70%, var(--dag-health-ink)); transition: color .4s; }
.dag-health__sbar { display: block; width: 46px; height: 3px; margin-top: 3px; border-radius: 2px; background: var(--dag-health-hair); overflow: hidden; & em { display: block; height: 100%; width: calc(var(--p) * 100%); background: var(--bc); transition: width .45s var(--dag-health-out), background-color .4s; } }
.dag-health__chip {
  display: inline-grid; place-items: center; min-width: 58px; height: 26px; padding: 0 7px; border-radius: 7px;
  font: 600 11.5px var(--dag-health-mono); letter-spacing: -.02em; white-space: nowrap; font-variant-numeric: tabular-nums;
  background: var(--f); color: var(--dag-health-ink); transition: scale .2s var(--dag-health-spring), box-shadow .15s;
