  .dag-health__t:not(.is-settled) & { animation: dag-health-pop .5s var(--dag-health-out) both; animation-delay: calc(var(--i) * 35ms + var(--j) * 45ms); }
}
.dag-health__t td.is-trend {
  min-width: 112px; white-space: nowrap; padding-right: 12px;
  & svg { display: inline-block; vertical-align: middle; width: 84px; height: 26px; }
  & path { fill: none; stroke: var(--bc); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; transition: stroke .4s; }
  & circle { fill: var(--bc); transition: cy .3s var(--dag-health-out); }
  & small { display: inline-block; width: 24px; margin-left: 4px; text-align: right; font: 650 10.5px var(--dag-health-mono); color: var(--dag-health-faint); vertical-align: middle; }
