}
@supports (animation-timeline: view()) {
  .dag-health__t.is-settled tbody tr { animation: dag-health-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }
}

/* ---------- portfolio map ---------- */
.dag-health__map { position: relative; min-height: 260px; }
.dag-health__msvg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dag-health__gl { stroke: var(--dag-health-hair); }
  & .dag-health__gl.is-v { stroke-dasharray: 2 4; }
  & .dag-health__ax { fill: var(--dag-health-faint); font: 500 10px var(--dag-health-mono); }
  & .dag-health__axl { fill: var(--dag-health-mute); font: 650 10px var(--dag-health-mono); letter-spacing: .04em; }
  & .dag-health__split { stroke: var(--dag-health-ink); stroke-width: 1; stroke-dasharray: 4 4; opacity: .35; }
  & .dag-health__ql { fill: var(--dag-health-faint); font: 700 10px var(--dag-health-mono); letter-spacing: .1em; text-transform: uppercase; }
  & .dag-health__ql.is-bad { fill: var(--dag-health-bad); }
}
.dag-health__zone { &.is-good { fill: color-mix(in oklch, var(--dag-health-good) 7%, transparent); } &.is-watch { fill: color-mix(in oklch, var(--dag-health-warn) 10%, transparent); } &.is-risk { fill: color-mix(in oklch, var(--dag-health-bad) 6%, transparent); } }
.dag-health__dot {
  --c: var(--dag-health-good); cursor: pointer; outline: none;
  transition: transform .9s var(--dag-health-spring), opacity .3s; transition-delay: calc(var(--i) * 30ms);
  &.is-watch { --c: var(--dag-health-warn); }
  &.is-risk { --c: var(--dag-health-bad); }
  & circle { fill: color-mix(in oklab, var(--c) 30%, var(--dag-health-panel)); stroke: var(--c); stroke-width: 2; transition: fill .3s, stroke .4s, r .2s; }
  & text { fill: var(--dag-health-ink); font: 600 11px system-ui, sans-serif; paint-order: stroke; stroke: var(--dag-health-panel); stroke-width: 3px; stroke-linejoin: round; }
  &:hover circle, &.is-open circle { fill: var(--c); }
  &:focus-visible circle { stroke: var(--dag-health-ink); stroke-width: 3; }
  &.is-dim { opacity: .18; }
}

/* ---------- model panel ---------- */
.dag-health__model {
  grid-area: model; min-height: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dag-health-panel); box-shadow: inset 0 0 0 1px var(--dag-health-line); overflow: hidden;
  & > header { position: relative; padding: 14px 16px 10px; & h3 { font-size: 14px; font-weight: 700; letter-spacing: -.015em; } & p { font-size: 11.5px; color: var(--dag-health-faint); margin-top: 2px; padding-right: 26px; } }
  & > footer { display: flex; align-items: end; gap: 10px; padding: 10px 16px 14px; border-top: 1px solid var(--dag-health-hair); & p { flex: 1; font-size: 11.5px; color: var(--dag-health-mute); line-height: 1.4; } & p b { color: var(--dag-health-ink); } & .is-up { color: var(--dag-health-good); font-weight: 650; } & .is-down { color: var(--dag-health-bad); font-weight: 650; } }
}
.dag-health__mclose { display: none; position: absolute; top: 10px; right: 10px; }
