  display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; margin: 0 16px 8px; padding: 3px; border-radius: 10px; background: var(--dag-health-hair);
  & button { height: 28px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dag-health-mute); transition: background-color .15s, color .15s, box-shadow .15s; }
  & button:hover { color: var(--dag-health-ink); }
  & button[aria-checked="true"] { background: var(--dag-health-panel); color: var(--dag-health-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .1), inset 0 0 0 1px var(--dag-health-line); }
}
.dag-health__sliders { flex: 1; min-height: 0; padding: 4px 16px 6px; display: grid; gap: 4px; align-content: start; }
.dag-health__sl {
