  color: var(--dag-health-panel); background: var(--dag-health-ink); transition: background-color .15s, color .15s, box-shadow .15s, opacity .15s;
  & .dag-health-i { width: 16px; height: 16px; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dag-health-ink), var(--dag-health-panel) 16%); }
  &.is-ghost { color: var(--dag-health-ink); background: transparent; box-shadow: inset 0 0 0 1px var(--dag-health-line); }
  &.is-ghost:hover:not(:disabled) { background: var(--dag-health-hair); }
  &[aria-pressed="true"] { color: var(--dag-health-bad); box-shadow: inset 0 0 0 1.5px var(--dag-health-bad); background: color-mix(in oklch, var(--dag-health-bad) 7%, transparent); }
  &:disabled { opacity: .5; }
}
.dag-health__x { width: 30px; height: 30px; flex: none; border-radius: 8px; display: grid; place-items: center; color: var(--dag-health-mute); &:hover { background: var(--dag-health-hair); color: var(--dag-health-ink); } }

/* ---------- drawer ---------- */
.dag-health__drawer {
  position: absolute; z-index: 40; top: 12px; right: 12px; bottom: 12px; width: min(372px, calc(100% - 24px));
  display: flex; flex-direction: column; gap: 14px; padding: 16px 16px 14px; border-radius: 16px; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin;
  background: var(--dag-health-panel); box-shadow: inset 0 0 0 1px var(--dag-health-line), 0 34px 70px -24px oklch(0.2 0.02 60 / .45), 0 8px 18px -10px oklch(0.2 0.02 60 / .25);
  transition: translate .5s var(--dag-health-out), opacity .25s;
