  & h4 { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; font-size: 12px; font-weight: 700; letter-spacing: .01em; margin-bottom: 8px; & span { font: 500 10.5px var(--dag-health-mono); color: var(--dag-health-faint); } }
