.dag-health__dh { display: flex; align-items: start; gap: 10px; & > div { flex: 1; min-width: 0; } & h3 { margin-top: 4px; font-size: 21px; font-weight: 780; letter-spacing: -.04em; line-height: 1.1; } & p { font-size: 12px; color: var(--dag-health-mute); margin-top: 2px; } }
.dag-health__hero { display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 16px; align-items: center; }
.dag-health__ring {
  --c: var(--dag-health-good); position: relative; width: 112px; aspect-ratio: 1; display: grid; place-items: center;
  transition: --dag-health-arc 1s var(--dag-health-out);
  @starting-style { --dag-health-arc: 0; }
  &.is-watch { --c: var(--dag-health-warn); }
  &.is-risk { --c: var(--dag-health-bad); }
  &::before { content: ""; position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from -90deg, var(--c) calc(var(--dag-health-arc) * 1%), var(--dag-health-hair) 0); mask: radial-gradient(farthest-side, transparent calc(100% - 10px), #000 calc(100% - 9.5px)); }
  & span { display: grid; justify-items: center; line-height: 1; }
