.dag-health__hs { display: grid; gap: 8px; font-size: 12.5px; color: var(--dag-health-mute); line-height: 1.45; & b { color: var(--dag-health-ink); font-weight: 650; } & .is-down { color: var(--dag-health-bad); } & .is-up { color: var(--dag-health-good); } }
.dag-health__parts ul { display: grid; }
.dag-health__parts li {
  display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(70px, 1fr) 56px; gap: 10px; align-items: center; padding: 6px 0; border-top: 1px solid var(--dag-health-hair);
  animation: dag-health-pop .45s var(--dag-health-out) both; animation-delay: calc(var(--j, 0) * 40ms + 120ms);
}
.dag-health__pn { display: grid; min-width: 0; & b { font-size: 12.5px; font-weight: 650; } & small { font-size: 10.5px; color: var(--dag-health-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; } }
.dag-health__pb { position: relative; height: 8px; border-radius: 4px; background: var(--dag-health-hair); & em { position: absolute; inset: 0 auto 0 0; width: calc(var(--p) * 100%); border-radius: inherit; background: var(--f); transition: width .5s var(--dag-health-out); } & i { position: absolute; top: -3px; bottom: -3px; left: calc(var(--a) * 100%); width: 2px; border-radius: 1px; background: var(--dag-health-ink); opacity: .55; } }
.dag-health__pv { font: 500 11px var(--dag-health-mono); color: var(--dag-health-faint); text-align: right; font-variant-numeric: tabular-nums; & b { font-size: 12.5px; color: var(--dag-health-ink); font-weight: 700; } }
.dag-health__psum { border-top: 1.5px solid var(--dag-health-ink) !important; font-size: 12px; font-weight: 700; }
.dag-health__trend svg {
  width: 100%; height: auto; cursor: crosshair;
  & .dag-health__ax { fill: var(--dag-health-faint); font: 500 9px var(--dag-health-mono); }
  & .dag-health__tl { fill: none; stroke: var(--dag-health-ink); stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
  & .dag-health__tl.is-draw { stroke-dasharray: 1; stroke-dashoffset: 1; animation: dag-health-draw 1.1s var(--dag-health-out) .15s forwards; }
  & .dag-health__td { fill: var(--dag-health-panel); stroke-width: 1.6; stroke: var(--dag-health-good); }
  & .dag-health__td.is-watch { stroke: var(--dag-health-warn); }
  & .dag-health__td.is-risk { stroke: var(--dag-health-bad); }
  & .dag-health__th { opacity: 0; transition: opacity .12s; pointer-events: none; }
  & .dag-health__th.is-on { opacity: 1; }
  & .dag-health__th line { stroke: var(--dag-health-ink); stroke-dasharray: 2 2; }
  & .dag-health__th rect { fill: var(--dag-health-ink); }
  & .dag-health__th text { fill: var(--dag-health-panel); font: 600 9.5px var(--dag-health-mono); }
  & .dag-health__th text.is-a { opacity: .7; }
