/* ---------- tooltip + toast ---------- */
.dag-health__tip {
  position: absolute; left: 0; top: 0; z-index: 80; pointer-events: none; min-width: 190px; max-width: 290px; padding: 9px 11px; border-radius: 10px;
  background: var(--dag-health-ink); color: var(--dag-health-panel); font-size: 12px; line-height: 1.45; font-variant-numeric: tabular-nums;
  box-shadow: 0 18px 36px -14px oklch(0.2 0.02 60 / .55); opacity: 0; transition: opacity .12s;
  &.is-on { opacity: 1; }
  & .dag-health__tt { display: block; font: 650 10.5px var(--dag-health-mono); letter-spacing: .05em; text-transform: uppercase; opacity: .65; margin-bottom: 3px; }
  & .dag-health__tr { display: flex; justify-content: space-between; gap: 16px; }
  & .dag-health__tr span { opacity: .78; }
}
.dag-health__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 90; max-width: min(480px, calc(100% - 32px)); padding: 10px 16px; border-radius: 11px;
  background: var(--dag-health-ink); color: var(--dag-health-panel); font-size: 12.5px; font-weight: 600; pointer-events: none;
  translate: -50% 18px; opacity: 0; transition: translate .45s var(--dag-health-out), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@keyframes dag-health-pop { from { opacity: 0; transform: scale(.82); } }
@keyframes dag-health-draw { to { stroke-dashoffset: 0; } }
@keyframes dag-health-reveal { from { opacity: .15; transform: translateY(14px); } }

/* ---------- container responsiveness ---------- */
@container dag-health (max-width: 1060px) {
  .dag-health__app { grid-template-columns: minmax(0, 1fr) 252px; }
  .dag-health__bands { grid-template-columns: repeat(4, minmax(88px, 104px)); }
  .dag-health__bands small { font-size: 10px; }
}
@container dag-health (max-width: 900px) {
  .dag-health__app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "strip" "main"; }
  .dag-health__mbtn { display: inline-flex; }
  .dag-health__meta { display: none; }
  .dag-health__tabs { margin-right: auto; }
  .dag-health__model {
    position: absolute; z-index: 45; top: 66px; right: 12px; bottom: 12px; width: min(320px, calc(100% - 24px));
    box-shadow: inset 0 0 0 1px var(--dag-health-line), 0 34px 70px -24px oklch(0.2 0.02 60 / .45);
    translate: calc(100% + 24px) 0; visibility: hidden; transition: translate .45s var(--dag-health-out), visibility 0s .45s;
  }
  .dag-health.is-model .dag-health__model { translate: 0 0; visibility: visible; transition: translate .45s var(--dag-health-out), visibility 0s; }
  .dag-health__mclose { display: grid; }
  .dag-health__strip { grid-template-columns: minmax(0, 1fr); }
  .dag-health__bands { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@container dag-health (max-width: 520px) {
  .dag-health__app { padding: 0 12px 12px; }
  .dag-health__top { margin: 0 -12px 12px; padding: 0 12px; gap: 8px; height: 54px; }
  .dag-health__brand > span:last-child { display: none; }
  .dag-health__tabs { margin-left: 0; & button { padding: 0 9px; } & button[aria-current="page"]::after { bottom: -10px; } }
