const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const GBPK = (k) => (k >= 1000 ? '£' + (k / 1000).toFixed(2) + 'm' : '£' + Math.round(k) + 'k');
const SGN = (v, d = 0) => (v > 0 ? '+' : v < 0 ? '−' : '±') + Math.abs(v).toFixed(d);
const OUT = 'cubic-bezier(.16,1,.3,1)';
const ICON = {
  x: '<svg class="dag-health-i" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  flag: '<svg class="dag-health-i" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 21V4.5"/><path d="M6 5h11l-2.5 4L17 13H6"/></svg>',
  cal: '<svg class="dag-health-i" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5.5" width="16" height="14.5" rx="2"/><path d="M4 10h16M8.5 3.5v4M15.5 3.5v4"/></svg>',
  up: '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M5 2 8.5 7.5h-7z" fill="currentColor"/></svg>',
  down: '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M5 8 1.5 2.5h7z" fill="currentColor"/></svg>'
};

/* ------------------------------------------------------------------ data */
/* Six signals, each normalised to 0–100 by a fixed rule. The score is their weighted mean,
   so changing a weight never changes a cell — only scores, bands, order and trends. */
const SIG = [
  { k: 'margin', name: 'Margin', desc: 'Project margin, last two quarters', fmt: (v) => v + '%', long: (v) => `${v}% margin`, norm: (v) => (v - 15) / 30 },
  { k: 'paid', name: 'Paid on time', short: 'Paid', desc: 'Average days late paying invoices', fmt: (v) => (v ? v + 'd late' : 'on time'), long: (v) => (v ? `invoices paid ${v} days late on average` : 'invoices paid on time'), norm: (v) => 1 - v / 45 },
  { k: 'scope', name: 'Scope', desc: 'Unplanned hours as a share of all hours', fmt: (v) => v + '%', long: (v) => `${v}% of hours unplanned`, norm: (v) => 1 - v / 30 },
  { k: 'mood', name: 'Sentiment', desc: 'Latest pulse survey, out of ten', fmt: (v) => v.toFixed(1), long: (v) => `a pulse score of ${v.toFixed(1)} out of 10`, norm: (v) => (v - 4) / 6 },
  { k: 'contact', name: 'Contact', desc: 'Days since a senior conversation', fmt: (v) => v + 'd', long: (v) => `${v} days since a senior conversation`, norm: (v) => 1 - (v - 7) / 53 },
  { k: 'growth', name: 'Growth', desc: 'Fees against the same period last year', fmt: (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v) + '%', long: (v) => `fees ${v >= 0 ? 'up' : 'down'} ${Math.abs(v)}% on last year`, norm: (v) => (v + 30) / 60 }
];
const PRESETS = { balanced: [5, 3, 3, 4, 2, 3], finance: [7, 6, 3, 1, 1, 2], relationship: [2, 1, 2, 7, 5, 3] };
const LEADS = { RC: 'Ruth Calder', OH: 'Omar Haddad', LF: 'Lena Fischer', SA: 'Sam Achebe' };
const MON = ['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep'];
const MONF = ['October 2025', 'November 2025', 'December 2025', 'January 2026', 'February 2026', 'March 2026', 'April 2026', 'May 2026', 'June 2026', 'July 2026', 'August 2026', 'September 2026'];
/*  id        name                       lead  fees £k since  margin late scope mood contact growth   drift (how much better it was a year ago) */
const CLIENTS = [
  ['vela', 'Vela Insurance', 'RC', 612, 2019, [29, 31, 22, 5.8, 9, 6], 26],
  ['parcel', 'Parcelpoint', 'OH', 488, 2021, [38, 4, 8, 8.4, 5, 22], -11],
  ['north', 'Northgate Housing Trust', 'LF', 356, 2020, [41, 12, 12, 7.6, 14, 4], 3],
  ['marlow', 'Marlow Bikes', 'OH', 298, 2022, [26, 18, 27, 6.9, 21, -8], 20],
  ['halden', 'Halden Furniture', 'RC', 214, 2018, [31, 6, 18, 6.2, 33, 2], 5],
  ['copper', 'Copperleaf Tea', 'SA', 176, 2023, [44, 2, 6, 8.9, 6, 31], -13],
  ['ashby', 'Ashby Museum', 'LF', 142, 2024, [33, 9, 15, 7.2, 28, -12], 9],
  ['lumen', 'Lumen Dental', 'SA', 128, 2025, [35, 22, 9, 8.1, 12, 15], -6],
  ['oak', 'Oaktree Credit Union', 'RC', 118, 2021, [36, 15, 19, 7.9, 17, -3], 1],
  ['quarry', 'Quarry Lane Brewing', 'SA', 96, 2022, [22, 71, 11, 6.5, 44, -24], 29],
  ['tide', 'Tidewell Pharmacy', 'LF', 84, 2024, [39, 7, 5, 8.7, 4, 40], -9],
  ['sable', 'Sable Audio', 'OH', 64, 2023, [27, 38, 24, 5.1, 52, -35], 33]
