      <footer><button type="button" class="dag-health__btn is-ghost" data-flag aria-pressed="false">${ICON.flag}<span>Flag for review</span></button><button type="button" class="dag-health__btn" data-checkin>${ICON.cal}<span>Book a check-in</span></button></footer>`;
  }
