  const x = (m) => pad.l + m * (W - pad.l - pad.r) / 11, y = (v) => pad.t + (1 - v / 100) * (H - pad.t - pad.b);
  const d = c.trend.map((v, m) => `${m ? 'L' : 'M'}${x(m).toFixed(1)} ${y(v).toFixed(1)}`).join('');
  svg.innerHTML = `<rect class="dag-health__zone is-good" x="${pad.l}" y="${y(100)}" width="${W - pad.l - pad.r}" height="${y(70) - y(100)}"/><rect class="dag-health__zone is-watch" x="${pad.l}" y="${y(70)}" width="${W - pad.l - pad.r}" height="${y(50) - y(70)}"/><rect class="dag-health__zone is-risk" x="${pad.l}" y="${y(50)}" width="${W - pad.l - pad.r}" height="${y(0) - y(50)}"/>` +
    [0, 50, 70, 100].map((v) => `<text class="dag-health__ax" x="${pad.l - 5}" y="${y(v) + 3}" text-anchor="end">${v}</text>`).join('') +
