/* ------------------------------------------------------------------ model panel */
const sliders = $('.dag-health__sliders');
sliders.innerHTML = SIG.map((s, i) => `<div class="dag-health__sl" style="--j:${i}"><div class="dag-health__slh"><span><b>${s.name}</b><small>${s.desc}</small></span><output data-out="${i}"></output></div><input type="range" min="0" max="10" step="1" value="${S.w[i]}" data-w="${i}" aria-label="${s.name} weight, 0 to 10"></div>`).join('');
