    `<b>${moved.length} client${moved.length === 1 ? '' : 's'}</b> change band against Balanced: ` + moved.slice(0, 3).map((c) => `${c.name} <span class="${order[c.band] > order[BASE[c.id]] ? 'is-up' : 'is-down'}">${order[c.band] > order[BASE[c.id]] ? '↑' : '↓'} ${BAND[c.band]}</span>`).join(', ') + (moved.length > 3 ? ` and ${moved.length - 3} more` : '');
