  if ((el = t.closest('[data-dot]'))) { if (S.open === el.dataset.dot) return closeDrawer(true); return openDrawer(el.dataset.dot); }
  if ((el = t.closest('tr[data-c]'))) { S.focus = el.dataset.c; return openDrawer(el.dataset.c); }
