css:
.dag-approvals {
  width: 100%;
  height: var(--dag-approvals-h, 680px);
  container-type: inline-size;
  container-name: dag-approvals;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dag-approvals-bg);
  color: var(--dag-approvals-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dag-approvals-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dag-approvals-focus, var(--dag-approvals-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dag-approvals-i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dag-approvals-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dag-approvals-num { font-variant-numeric: tabular-nums; }
  & .dag-approvals-scroll {
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklch, var(--dag-approvals-ink) 24%, transparent) transparent;
    &::-webkit-scrollbar { width: 8px; height: 8px; }
    &::-webkit-scrollbar-track { background: transparent; }
    &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dag-approvals-ink) 22%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  }
}

.dag-approvals {
  /* re-theme with these four */
  --dag-approvals-bg: oklch(0.215 0.008 70);
  --dag-approvals-ink: oklch(0.94 0.014 85);
  --dag-approvals-accent: oklch(0.83 0.15 80);
  --dag-approvals-flag: oklch(0.72 0.15 33);
  /* derived */
  --dag-approvals-ok: color-mix(in oklch, oklch(0.8 0.13 152), var(--dag-approvals-ink) 10%);
  --dag-approvals-panel: color-mix(in oklch, var(--dag-approvals-bg), var(--dag-approvals-ink) 4%);
  --dag-approvals-raise: color-mix(in oklch, var(--dag-approvals-bg), var(--dag-approvals-ink) 8.5%);
  --dag-approvals-line: color-mix(in oklch, var(--dag-approvals-ink) 12%, transparent);
  --dag-approvals-hair: color-mix(in oklch, var(--dag-approvals-ink) 6.5%, transparent);
  --dag-approvals-mute: color-mix(in oklch, var(--dag-approvals-ink) 70%, var(--dag-approvals-bg));
  --dag-approvals-faint: color-mix(in oklch, var(--dag-approvals-ink) 48%, var(--dag-approvals-bg));
  --dag-approvals-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dag-approvals-out: cubic-bezier(.16, 1, .3, 1);
  --dag-approvals-spring: linear(0, .09 3%, .34 8%, .68 14%, .95 21%, 1.06 27%, 1.08 32%, 1.05 39%, 1.01 50%, .997 63%, 1);
  color-scheme: dark;
  border-radius: 16px;
}

.dag-approvals__app { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); }

/* ---------- header ---------- */
.dag-approvals__head { display: grid; grid-template-columns: auto minmax(220px, 1fr) auto; align-items: center; gap: 12px 24px; padding: 14px 20px; border-bottom: 1px solid var(--dag-approvals-line); }
.dag-approvals__brand { display: flex; align-items: center; gap: 12px; & h2 { font-size: clamp(18px, 2.1cqi, 23px); font-weight: 720; letter-spacing: -.035em; line-height: 1.1; margin-top: 3px; } }
.dag-approvals__mark { width: 36px; height: 36px; flex: none; border-radius: 50%; display: grid; place-items: center; color: var(--dag-approvals-bg); background: var(--dag-approvals-accent); & .dag-approvals-i { stroke-width: 2.1; } }
.dag-approvals__eb { font: 600 10.5px var(--dag-approvals-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dag-approvals-accent); }
.dag-approvals__prog { display: grid; gap: 6px; min-width: 0; & p { font-size: 12px; color: var(--dag-approvals-mute); line-height: 1.4; font-variant-numeric: tabular-nums; } & p b { color: var(--dag-approvals-ink); } & p span { color: var(--dag-approvals-faint); font-size: 11.5px; } }
.dag-approvals__pbar {
  display: flex; gap: 2px; height: 8px; border-radius: 4px; overflow: hidden; max-width: 420px;
  & i { flex: 0 1 0; min-width: 0; transition: flex-grow .7s var(--dag-approvals-spring); }
  & [data-pb="approved"] { background: var(--dag-approvals-ok); }
  & [data-pb="back"] { background: var(--dag-approvals-flag); }
  & [data-pb="pending"] { background: color-mix(in oklch, var(--dag-approvals-accent) 55%, var(--dag-approvals-panel)); }
  & [data-pb="missing"] { background: repeating-linear-gradient(-45deg, var(--dag-approvals-line) 0 3px, transparent 3px 6px); box-shadow: inset 0 0 0 1px var(--dag-approvals-line); }
}
.dag-approvals__hctl { display: flex; align-items: center; gap: 10px; }
.dag-approvals__seg {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dag-approvals-hair); box-shadow: inset 0 0 0 1px var(--dag-approvals-line);
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dag-approvals-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dag-approvals-ink); }
  & button[aria-checked="true"] { background: var(--dag-approvals-ink); color: var(--dag-approvals-bg); }
}
.dag-approvals__bulk {
  position: relative; overflow: hidden; height: 34px; padding: 0 14px; border-radius: 10px; font-size: 12.5px; font-weight: 700; white-space: nowrap;
  color: var(--dag-approvals-bg); background: var(--dag-approvals-accent); transition: filter .15s, opacity .2s;
  & span { position: relative; }
  & .dag-approvals__bfill { position: absolute; inset: 0; background: var(--dag-approvals-ok); transform-origin: left; transform: scaleX(var(--p, 0)); transition: transform .3s var(--dag-approvals-out); }
  &:hover:not(:disabled) { filter: brightness(1.06); }
  &:disabled { opacity: .45; }
  &.is-run { cursor: progress; }
}

/* ---------- queue view ---------- */
.dag-approvals__view { min-height: 0; min-width: 0; }
.dag-approvals__qv { display: grid; grid-template-columns: 300px minmax(0, 1fr); }
.dag-approvals__queue { min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--dag-approvals-line); background: color-mix(in oklch, var(--dag-approvals-bg), black 12%); }
.dag-approvals__qf {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; margin: 12px 12px 8px; padding: 3px; border-radius: 10px; background: var(--dag-approvals-hair);
  & button { height: 28px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dag-approvals-mute); transition: background-color .15s, color .15s; }
  & button span { font: 650 10.5px var(--dag-approvals-mono); padding: 0 5px; border-radius: 5px; background: var(--dag-approvals-hair); }
  & button:hover { color: var(--dag-approvals-ink); }
  & button[aria-checked="true"] { color: var(--dag-approvals-ink); background: var(--dag-approvals-raise); box-shadow: inset 0 0 0 1px var(--dag-approvals-line); }
  & button[aria-checked="true"] span { color: var(--dag-approvals-bg); background: var(--dag-approvals-accent); }
}
.dag-approvals__ql { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 8px 8px; display: flex; flex-direction: column; gap: 3px; outline: none; }
.dag-approvals__qi {
  position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; grid-template-areas: "av t h" "av t s"; align-items: center; column-gap: 10px; row-gap: 2px;
  padding: 8px 10px 8px 12px; border-radius: 11px; cursor: pointer; transition: background-color .15s;
  .dag-approvals__ql:not(.is-settled) & { animation: dag-approvals-in .5s var(--dag-approvals-out) both; animation-delay: calc(var(--i) * 35ms); }
  &:hover { background: var(--dag-approvals-hair); }
  &[aria-selected="true"] { background: var(--dag-approvals-raise); box-shadow: inset 0 0 0 1px var(--dag-approvals-line); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dag-approvals-accent); }
  &:focus-visible { outline-offset: -2px; }
  & > .dag-approvals__av { grid-area: av; }
  & .dag-approvals__st { grid-area: s; justify-self: end; }
}
.dag-approvals__qt { grid-area: t; display: grid; min-width: 0; & b { font-size: 13px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } & small { font-size: 11px; color: var(--dag-approvals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }
.dag-approvals__qh { grid-area: h; display: flex; align-items: baseline; gap: 6px; justify-self: end; & b { font: 650 12px var(--dag-approvals-mono); } & small { display: none; } }
.dag-approvals__av { width: 30px; height: 30px; border-radius: 50%; flex: none; display: grid; place-items: center; font: 700 10.5px system-ui, sans-serif; color: oklch(0.22 0.02 70); background: oklch(0.8 0.08 var(--h, 80)); &.is-lg { width: 42px; height: 42px; font-size: 14px; } &.is-ghost { color: var(--dag-approvals-faint); background: none; box-shadow: inset 0 0 0 1.5px var(--dag-approvals-line); border: 1px dashed transparent; } }
.dag-approvals__st {
  display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px; border-radius: 6px; font-size: 10.5px; font-weight: 650; white-space: nowrap;
  & .dag-approvals-i { width: 12px; height: 12px; stroke-width: 2.4; }
  &.is-flag { color: var(--dag-approvals-flag); background: color-mix(in oklch, var(--dag-approvals-flag) 15%, transparent); }
  &.is-clean { color: var(--dag-approvals-ok); background: color-mix(in oklch, var(--dag-approvals-ok) 12%, transparent); }
  &.is-ok { color: var(--dag-approvals-bg); background: var(--dag-approvals-ok); }
  &.is-back { color: var(--dag-approvals-bg); background: var(--dag-approvals-flag); }
}
.dag-approvals__miss {
  padding: 10px 12px 12px; border-top: 1px solid var(--dag-approvals-line); display: grid; gap: 6px;
  & h4 { font: 650 10.5px var(--dag-approvals-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-approvals-faint); display: flex; gap: 6px; }
  & h4 span { color: var(--dag-approvals-flag); }
}
.dag-approvals__mi { display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 10px; align-items: center; & span:nth-child(2) { display: grid; min-width: 0; } & b { font-size: 12.5px; font-weight: 600; } & small { font-size: 11px; color: var(--dag-approvals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }
.dag-approvals__empty { padding: 30px 16px; text-align: center; font-size: 12.5px; color: var(--dag-approvals-faint); }

/* ---------- buttons ---------- */
.dag-approvals__btn {
  height: 32px; display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 650; white-space: nowrap;
  color: var(--dag-approvals-bg); background: var(--dag-approvals-accent); transition: filter .15s, background-color .15s, opacity .15s, scale .2s var(--dag-approvals-spring);
  & .dag-approvals-i { width: 15px; height: 15px; stroke-width: 2.1; }
  & kbd { font: 650 10px var(--dag-approvals-mono); padding: 1px 5px; border-radius: 4px; background: oklch(0 0 0 / .14); }
  &:hover:not(:disabled) { filter: brightness(1.07); }
  &:active:not(:disabled) { scale: .97; }
  &.is-ok { background: var(--dag-approvals-ok); }
  &.is-warn { background: var(--dag-approvals-flag); }
  &.is-ghost { color: var(--dag-approvals-ink); background: transparent; box-shadow: inset 0 0 0 1px var(--dag-approvals-line); }
  &.is-ghost kbd { background: var(--dag-approvals-hair); color: var(--dag-approvals-mute); }
  &.is-ghost:hover:not(:disabled) { background: var(--dag-approvals-hair); filter: none; }
  &.is-sm { height: 26px; padding: 0 9px; font-size: 11.5px; border-radius: 7px; }
  &.is-icon { width: 26px; padding: 0; }
  &:disabled { opacity: .42; }
}
.dag-approvals__x { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--dag-approvals-mute); &:hover { background: var(--dag-approvals-hair); color: var(--dag-approvals-ink); } & .dag-approvals-i { width: 16px; height: 16px; } }

/* ---------- sheet ---------- */
.dag-approvals__sheet { position: relative; min-height: 0; min-width: 0; display: grid; }
.dag-approvals__sw {
  min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dag-approvals-line) transparent;
  padding: 16px 20px 20px; display: flex; flex-direction: column; gap: 14px;
  &.is-in { animation: dag-approvals-swap .45s var(--dag-approvals-out) both; }
}
.dag-approvals__sh { display: flex; align-items: center; flex-wrap: wrap; gap: 10px 12px; & .dag-approvals__acts { margin-left: auto; display: flex; gap: 8px; } }
.dag-approvals__sn { min-width: 0; flex: 1 1 200px; & h3 { font-size: 18px; font-weight: 720; letter-spacing: -.03em; } & p { font-size: 12px; color: var(--dag-approvals-faint); } }
.dag-approvals__stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-radius: 12px; background: var(--dag-approvals-panel); box-shadow: inset 0 0 0 1px var(--dag-approvals-line);
  & div { padding: 9px 13px; display: grid; gap: 1px; }
  & div + div { border-left: 1px solid var(--dag-approvals-hair); }
  & dt { font-size: 10.5px; color: var(--dag-approvals-faint); text-transform: uppercase; letter-spacing: .05em; font-weight: 600; }
  & dd { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & dd small { font: 600 11px var(--dag-approvals-mono); color: var(--dag-approvals-faint); letter-spacing: 0; }
  & dd.is-bad { color: var(--dag-approvals-flag); }
}
.dag-approvals__bq { margin: 0; padding: 10px 14px; border-radius: 10px; border-left: 3px solid var(--dag-approvals-flag); background: color-mix(in oklch, var(--dag-approvals-flag) 8%, transparent); font-size: 12.5px; white-space: pre-line; color: var(--dag-approvals-mute); & span { display: block; font: 650 10px var(--dag-approvals-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-approvals-flag); margin-bottom: 4px; } }
.dag-approvals__gw { flex: none; border-radius: 12px; box-shadow: inset 0 0 0 1px var(--dag-approvals-line); overflow-x: auto; }
.dag-approvals__g {
  min-width: 600px; font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th, & td { padding: 0 6px; border-bottom: 1px solid var(--dag-approvals-hair); text-align: center; }
  & thead th { padding: 10px 4px 8px; font-weight: 600; vertical-align: bottom; }
  & thead th b { display: block; font-size: 11.5px; font-weight: 650; }
  & thead th small { display: block; font: 500 10px var(--dag-approvals-mono); color: var(--dag-approvals-faint); }
  & thead th.is-long b { color: var(--dag-approvals-flag); }
  & .is-entry { text-align: left; padding-left: 14px; width: 40%; position: sticky; left: 0; z-index: 1; background: color-mix(in oklch, var(--dag-approvals-bg), var(--dag-approvals-ink) 2%); }
  & thead .is-entry, & thead .is-tot { font: 600 10px var(--dag-approvals-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-approvals-faint); }
  .is-in & tbody tr { animation: dag-approvals-in .45s var(--dag-approvals-out) both; animation-delay: calc(var(--i) * 50ms + 80ms); }
  & tbody th { padding: 9px 10px 9px 14px; font-weight: 400; }
  & tbody th > i { float: left; width: 8px; height: 8px; margin: 5px 9px 0 0; border-radius: 2px; background: var(--c); }
  & tbody th > span { display: grid; min-width: 0; }
  & tbody th b { font-size: 12.5px; font-weight: 640; display: flex; align-items: baseline; gap: 6px; }
  & tbody th b em { font: 600 9.5px var(--dag-approvals-mono); font-style: normal; letter-spacing: .05em; text-transform: uppercase; color: var(--dag-approvals-faint); }
  & tbody th small { font-size: 11px; color: var(--dag-approvals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 260px; }
  & .is-miss { color: var(--dag-approvals-flag); font-weight: 600; }
  & td { font: 550 12px var(--dag-approvals-mono); height: 44px; min-width: 42px; transition: background-color .2s, box-shadow .2s; }
  & td.is-we, & th.is-we { background: color-mix(in oklch, var(--dag-approvals-ink) 2.5%, transparent); }
  & td.is-flag { color: var(--dag-approvals-flag); background: color-mix(in oklch, var(--dag-approvals-flag) 11%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dag-approvals-flag) 50%, transparent); }
  & td.is-ping { animation: dag-approvals-ping 1.1s var(--dag-approvals-out); }
  & .is-tot { font-weight: 700; color: var(--dag-approvals-ink); }
  & tfoot th, & tfoot td { height: 36px; border-bottom: 0; font-weight: 700; }
  & tfoot th { font: 600 10px var(--dag-approvals-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dag-approvals-faint); }
  & tfoot td.is-over { color: var(--dag-approvals-flag); }
  & [data-cell]:not(:empty) { cursor: help; }
}
.dag-approvals__db {
  position: relative; width: 20px; height: 46px; margin: 0 auto 7px; border-radius: 4px; background: var(--dag-approvals-hair); display: flex; flex-direction: column-reverse; overflow: hidden;
  & i { flex: none; height: calc(var(--h) * 100%); transform-origin: bottom; }
  & .is-bill { background: var(--dag-approvals-accent); }
  & .is-non { background: color-mix(in oklch, var(--dag-approvals-ink) 45%, var(--dag-approvals-bg)); }
  & .is-leave { background: repeating-linear-gradient(-45deg, var(--dag-approvals-faint) 0 2px, transparent 2px 4px); }
  & em { position: absolute; left: 0; right: 0; bottom: calc(var(--g) * 100%); height: 1.5px; background: var(--dag-approvals-ink); opacity: .55; }
  .is-long & .is-bill { background: var(--dag-approvals-flag); }
  .is-in & i { animation: dag-approvals-grow .65s var(--dag-approvals-out) both; animation-delay: calc(var(--i) * 45ms + 120ms); }
}
.dag-approvals__g thead th[data-day] { cursor: help; }
.dag-approvals__fl {
  & h4 { font-size: 12.5px; font-weight: 700; margin-bottom: 6px; display: flex; gap: 8px; align-items: baseline; }
  & h4 span { font: 500 11px var(--dag-approvals-mono); color: var(--dag-approvals-faint); }
  & ul { display: grid; gap: 4px; }
  & li { display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px 8px 8px 10px; border-radius: 11px; background: var(--dag-approvals-panel); box-shadow: inset 0 0 0 1px var(--dag-approvals-hair); transition: background-color .25s; }
  .is-in & li { animation: dag-approvals-in .4s var(--dag-approvals-out) both; animation-delay: calc(var(--i) * 50ms + 160ms); }
  & li.is-ok { background: transparent; }
  & li.is-ok .dag-approvals__ft b { text-decoration: line-through; text-decoration-color: var(--dag-approvals-faint); color: var(--dag-approvals-mute); }
  & li.is-ok .dag-approvals__fi { color: var(--dag-approvals-ok); background: color-mix(in oklch, var(--dag-approvals-ok) 12%, transparent); }
}
.dag-approvals__fi { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; color: var(--dag-approvals-flag); background: color-mix(in oklch, var(--dag-approvals-flag) 14%, transparent); transition: color .25s, background-color .25s; & .dag-approvals-i { width: 16px; height: 16px; } }
.dag-approvals__ft { display: grid; min-width: 0; & b { font-size: 12.5px; font-weight: 640; } & small { font-size: 11.5px; color: var(--dag-approvals-faint); text-wrap: pretty; } }
.dag-approvals__fa { display: flex; gap: 4px; }
.dag-approvals__none { font-size: 12px; color: var(--dag-approvals-faint); padding: 10px 12px; border-radius: 10px; border: 1px dashed var(--dag-approvals-line); }

/* ---------- send-back composer ---------- */
.dag-approvals__cmp {
  position: absolute; z-index: 20; left: 16px; right: 16px; bottom: 16px; max-width: 560px; margin-inline: auto; padding: 14px; border-radius: 14px; display: grid; gap: 10px;
  background: var(--dag-approvals-raise); box-shadow: inset 0 0 0 1px var(--dag-approvals-line), 0 -10px 50px -10px oklch(0 0 0 / .55), 0 24px 50px -20px oklch(0 0 0 / .7);
  transition: translate .45s var(--dag-approvals-out), opacity .2s;
  @starting-style { translate: 0 24px; opacity: 0; }
  & header { display: flex; align-items: center; justify-content: space-between; & b { font-size: 14px; font-weight: 700; } }
  & label { display: grid; gap: 5px; font-size: 11px; font-weight: 600; color: var(--dag-approvals-faint); text-transform: uppercase; letter-spacing: .05em; }
  & textarea { resize: none; padding: 9px 11px; border-radius: 9px; border: 0; font: 13px/1.45 system-ui, sans-serif; text-transform: none; letter-spacing: 0; color: var(--dag-approvals-ink); background: var(--dag-approvals-bg); box-shadow: inset 0 0 0 1px var(--dag-approvals-line); outline: none; transition: box-shadow .15s; }
  & textarea:focus-visible { box-shadow: inset 0 0 0 1.5px var(--dag-approvals-accent); }
  & textarea[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--dag-approvals-flag); }
  & footer { display: flex; justify-content: flex-end; gap: 8px; }
}
.dag-approvals__why {
  display: flex; flex-wrap: wrap; gap: 5px;
  & button { height: 26px; padding: 0 10px; border-radius: 13px; font-size: 11.5px; font-weight: 600; color: var(--dag-approvals-mute); box-shadow: inset 0 0 0 1px var(--dag-approvals-line); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dag-approvals-ink); }
  & button[aria-checked="true"] { color: var(--dag-approvals-bg); background: var(--dag-approvals-flag); box-shadow: none; }
}
.dag-approvals__err { font-size: 12px; color: var(--dag-approvals-flag); }

/* ---------- by project ---------- */
.dag-approvals__pv { display: grid; padding: 16px 20px 18px; }
.dag-approvals__proj { min-height: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dag-approvals-panel); box-shadow: inset 0 0 0 1px var(--dag-approvals-line); overflow: hidden; }
.dag-approvals__ph { display: flex; align-items: start; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; padding: 14px 16px 10px; & > div:first-child { flex: 1 1 280px; } & h3 { font-size: 14px; font-weight: 680; } & p { font-size: 11.5px; color: var(--dag-approvals-faint); margin-top: 2px; } }
.dag-approvals__pl { flex: 1; min-height: 0; overflow-y: auto; padding: 0 10px 12px; display: grid; align-content: start; gap: 3px; }
.dag-approvals__pr { border-radius: 11px; transition: background-color .2s; animation: dag-approvals-in .45s var(--dag-approvals-out) both; animation-delay: calc(var(--i) * 45ms); &.is-open { background: var(--dag-approvals-hair); } }
.dag-approvals__prh {
  width: 100%; display: grid; grid-template-columns: minmax(150px, 1fr) minmax(180px, 2.2fr) 130px 20px; align-items: center; gap: 16px; padding: 10px; text-align: left; border-radius: 11px;
  &:hover { background: var(--dag-approvals-hair); }
}
.dag-approvals__pn { display: grid; min-width: 0; & b { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 650; } & b i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); } & small { font-size: 11px; color: var(--dag-approvals-faint); padding-left: 17px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }
.dag-approvals__pbr {
  position: relative; height: 16px; display: flex; gap: 2px; border-radius: 4px; background: var(--dag-approvals-hair);
  & i { height: 100%; width: calc(var(--w) * 100%); border-radius: 3px; transform-origin: left; animation: dag-approvals-wipe .8s var(--dag-approvals-out) both; animation-delay: calc(var(--i, 0) * 45ms + 150ms); transition: width .5s var(--dag-approvals-out); }
  & .is-a { background: var(--c); }
  & .is-w { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--c) 80%, transparent) 0 3px, color-mix(in oklch, var(--c) 30%, transparent) 3px 6px); }
  & .is-b { background: color-mix(in oklch, var(--dag-approvals-flag) 50%, transparent); }
  & em { position: absolute; top: -4px; bottom: -4px; left: calc(var(--x) * 100%); width: 2px; margin-left: -1px; border-radius: 1px; background: var(--dag-approvals-ink); }
}
.dag-approvals__pnum { display: grid; justify-items: end; & b { font: 650 13px var(--dag-approvals-mono); } & small { font: 500 10.5px var(--dag-approvals-mono); color: var(--dag-approvals-faint); } & .is-over { color: var(--dag-approvals-flag); } & .is-under { color: var(--dag-approvals-accent); } }
.dag-approvals__chev { color: var(--dag-approvals-faint); transition: rotate .35s var(--dag-approvals-spring); .is-open & { rotate: 180deg; } }
.dag-approvals__pd {
  display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--dag-approvals-out);
  .is-open & { grid-template-rows: 1fr; }
  & > div { min-height: 0; overflow: hidden; }
  & ul { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 4px 14px; padding: 2px 12px 12px 27px; }
  & li { display: grid; grid-template-columns: 24px minmax(0, 1fr) auto auto; gap: 8px; align-items: center; font-size: 12px; }
  & .dag-approvals__av { width: 24px; height: 24px; font-size: 8.5px; }
  & li b { font: 600 11.5px var(--dag-approvals-mono); }
  & li em { font-style: normal; font-size: 10px; font-weight: 650; padding: 1px 6px; border-radius: 5px; color: var(--dag-approvals-mute); background: var(--dag-approvals-hair); }
  & li em.is-approved { color: var(--dag-approvals-bg); background: var(--dag-approvals-ok); }
  & li em.is-back { color: var(--dag-approvals-bg); background: var(--dag-approvals-flag); }
}
.dag-approvals__pt { padding: 10px 10px 0; font-size: 11.5px; color: var(--dag-approvals-faint); border-top: 1px solid var(--dag-approvals-hair); margin-top: 6px; }

/* ---------- tooltip + toast ---------- */
.dag-approvals__tip {
  position: absolute; left: 0; top: 0; z-index: 80; pointer-events: none; min-width: 180px; max-width: 290px; padding: 9px 11px; border-radius: 10px;
  background: var(--dag-approvals-ink); color: var(--dag-approvals-bg); font-size: 12px; line-height: 1.45; font-variant-numeric: tabular-nums;
  box-shadow: 0 16px 32px -12px oklch(0 0 0 / .7); opacity: 0; transition: opacity .12s;
  &.is-on { opacity: 1; }
  & .dag-approvals__tt { display: block; font: 650 10.5px var(--dag-approvals-mono); letter-spacing: .05em; text-transform: uppercase; opacity: .62; margin-bottom: 3px; }
  & .dag-approvals__tr { display: flex; justify-content: space-between; gap: 14px; }
  & .dag-approvals__tr span { display: inline-flex; align-items: center; gap: 6px; opacity: .82; }
  & .dag-approvals__tr i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & .dag-approvals__tn { margin-top: 3px; font-style: italic; opacity: .8; }
