      <div><dt>Leave</dt><dd>${H(t - work)} h</dd></div>
    </dl>
    ${p.status === 'back' ? `<blockquote class="dag-approvals__bq"><span>Sent back with this note</span>${p.note.replace(/</g, '&lt;')}</blockquote>` : ''}
    <div class="dag-approvals__gw dag-approvals-scroll"><table class="dag-approvals__g">
      <thead><tr><th scope="col" class="is-entry">Entry</th>${DAYS.map((d, i) => { const segs = [['bill', sum(p.entries.filter((e) => PROJ[e.p].bill).map((e) => e.h[i]))], ['non', sum(p.entries.filter((e) => !PROJ[e.p].bill && !PROJ[e.p].leave).map((e) => e.h[i]))], ['leave', sum(p.entries.filter((e) => PROJ[e.p].leave).map((e) => e.h[i]))]]; return `<th scope="col" class="${i > 4 ? 'is-we' : ''}${day[i] > 10 ? ' is-long' : ''}" data-day="${i}"><span class="dag-approvals__db" style="--i:${i}">${segs.map(([k, v]) => (v ? `<i class="is-${k}" style="--h:${(v / max).toFixed(3)}"></i>` : '')).join('')}<em style="--g:${(7.5 / max).toFixed(3)}"></em></span><b>${d}</b><small>${DATE[i]}</small></th>`; }).join('')}<th scope="col" class="is-tot">Total</th></tr></thead>
      <tbody>${p.entries.map((e, ei) => { const P = PROJ[e.p]; return `<tr style="--i:${ei}"><th scope="row" class="is-entry"><i style="--c:${P.c}"></i><span><b>${P.name}<em>${P.bill ? '' : P.leave ? 'leave' : 'non-billable'}</em></b><small>${e.t}${e.note ? ' · ' + e.note : ' · <span class="is-miss">no note</span>'}</small></span></th>${e.h.map((h, d) => `<td class="${d > 4 ? 'is-we' : ''}${ping(ei, d) ? ' is-flag' : ''}" data-cell="${ei}:${d}">${h ? H(h) : ''}</td>`).join('')}<td class="is-tot">${H(sum(e.h))}</td></tr>`; }).join('')}</tbody>
      <tfoot><tr><th scope="row" class="is-entry">Day total</th>${day.map((h, d) => `<td class="${d > 4 ? 'is-we' : ''}${h > 10 ? ' is-over' : ''}">${h ? H(h) : '–'}</td>`).join('')}<td class="is-tot${t < p.contract ? ' is-over' : ''}" data-cell="tot">${H(t)}</td></tr></tfoot>
    </table></div>
    <section class="dag-approvals__fl" aria-label="Flags">
      <h4>${p.flags.length ? `Flags <span>${o.length} open of ${p.flags.length}</span>` : 'No flags'}</h4>
      ${p.flags.length ? `<ul>${p.flags.map((f, i) => { const ok = p.ok.has(f.id); return `<li class="${ok ? 'is-ok' : ''}" style="--i:${i}"><span class="dag-approvals__fi is-${f.k}">${IC[f.k]}</span><span class="dag-approvals__ft"><b>${f.title}</b><small>${ok ? 'Accepted by you · ' : ''}${f.why}</small></span><span class="dag-approvals__fa"><button type="button" class="dag-approvals__btn is-ghost is-sm is-icon" data-show="${f.id}" aria-label="Show in the grid: ${f.title}" title="Show in the grid">${IC.eye}</button>${pend ? (ok ? `<button type="button" class="dag-approvals__btn is-ghost is-sm" data-unaccept="${f.id}">Undo</button>` : `<button type="button" class="dag-approvals__btn is-ghost is-sm" data-accept="${f.id}">Accept</button>`) : ''}</span></li>`; }).join('')}</ul>` : '<p class="dag-approvals__none">Nothing unusual: no long days, weekend work, missing notes or closed projects.</p>'}
    </section>
    ${S.compose ? composeHTML(p) : ''}
  </div>`;
}
function composeHTML(p) {
  const o = open(p), first = p.name.split(' ')[0];
  const msg = o.length ? `Hi ${first}, could you look at these before I approve week 39?\n` + o.map((f) => '– ' + f.title).join('\n') : `Hi ${first}, could you check week 39 and resubmit?`;
  return `<form class="dag-approvals__cmp" data-cmp novalidate aria-label="Send back to ${p.name}">
    <header><b>Send back to ${first}</b><button type="button" class="dag-approvals__x" data-cclose aria-label="Cancel">${IC.x}</button></header>
    <div class="dag-approvals__why" role="group" aria-label="What needs fixing">${[['split', 'Split the long day'], ['notes', 'Add notes'], ['move', 'Move time off the closed project'], ['missing', 'Add the missing hours']].map(([k, l]) => `<button type="button" role="checkbox" aria-checked="false" data-why="${k}">${l}</button>`).join('')}</div>
    <label><span>Message</span><textarea name="msg" rows="4" required minlength="12">${msg}</textarea></label>
    <p class="dag-approvals__err" data-err hidden>Write at least a short note so ${first} knows what to change.</p>
    <footer><button type="button" class="dag-approvals__btn is-ghost" data-cclose>Cancel</button><button type="submit" class="dag-approvals__btn is-warn">${IC.back}Send back</button></footer>
  </form>`;
}

/* ------------------------------------------------------------------ actions */
function after(id) {
  const l = list();
  if (!l.length) return;
  const i = PEOPLE.findIndex((p) => p.id === id);
  const nx = l.find((p) => p.n > i) || l[0];
  S.sel = nx.id;
}
function collapse(id, then) {
  const el = qlist.querySelector(`[data-p="${id}"]`);
  if (!el || RM || inFilter(byId[id])) { then(); return; }
  const h = el.offsetHeight;
  el.animate([{ height: h + 'px', opacity: 1, transform: 'none' }, { height: '0px', opacity: 0, transform: 'translateX(24px)', paddingTop: '0px', paddingBottom: '0px', marginTop: '-6px' }], { duration: 300, easing: OUT, fill: 'forwards' }).onfinish = then;
}
function approve(id, quiet) {
  const p = byId[id];
  if (!p || p.status !== 'pending' || open(p).length) return false;
  p.status = 'approved';
  if (!quiet) {
    const prev = S.sel;
    if (S.filter !== 'done') after(id);
    collapse(id, () => { renderAll(true); });
    toast(`Approved ${p.name} · ${H(tot(p))} h`, () => { p.status = 'pending'; S.sel = prev; renderAll(true); });
  }
  return true;
}
function sendBack(id, msg) {
  const p = byId[id];
  p.status = 'back';
  p.note = msg;
  S.compose = false;
  const prev = S.sel;
  if (S.filter !== 'done') after(id);
  collapse(id, () => renderAll(true));
  toast(`Sent back to ${p.name.split(' ')[0]} with your note`, () => { p.status = 'pending'; p.note = ''; S.sel = prev; renderAll(true); });
}
function runBulk() {
  const ids = PEOPLE.filter(clean).map((p) => p.id);
  if (!ids.length || S.bulk) return;
  S.bulk = true;
  const btn = $('[data-bulk]'), lab = $('[data-bulkl]');
  btn.classList.add('is-run');
  btn.setAttribute('aria-busy', 'true');
  btn.setAttribute('aria-disabled', 'true');
  let k = 0;
  const step = () => {
    if (!root.isConnected) return;
    if (k < ids.length) {
      approve(ids[k], true);
      k++;
      btn.style.setProperty('--p', k / ids.length);
      lab.textContent = `Approving ${k} of ${ids.length}…`;
      if (!inFilter(byId[S.sel])) after(S.sel);
      renderQueue(true); renderFilters(); renderHead(); renderSheet();
      setTimeout(step, RM ? 30 : 170);
      return;
    }
    S.bulk = false;
    btn.classList.remove('is-run');
    btn.removeAttribute('aria-busy');
    btn.removeAttribute('aria-disabled');
    btn.style.setProperty('--p', 0);
    renderAll(false);
    toast(`${ids.length} clean timesheets approved`, () => { ids.forEach((id) => { byId[id].status = 'pending'; }); renderAll(true); });
  };
  btn.style.setProperty('--p', 0);
  setTimeout(step, 60);
}
function ping(sel) {
  const cells = $$(sel, sheet);
  cells.forEach((c) => { c.classList.remove('is-ping'); void c.offsetWidth; c.classList.add('is-ping'); });
  if (cells[0]) cells[0].scrollIntoView({ block: 'nearest', inline: 'nearest' });
}
function showFlag(fid) {
  const p = byId[S.sel], f = p.flags.find((x) => x.id === fid);
  if (!f) return;
  if (f.k === 'long') ping(`[data-cell$=":${f.d}"]`);
  else if (f.k === 'weekend') ping(`[data-cell="${f.e}:5"], [data-cell="${f.e}:6"]`);
  else if (f.k === 'short') ping('[data-cell="tot"]');
  else ping(`[data-cell^="${f.e}:"]`);
}

/* ------------------------------------------------------------------ by project */
function renderProjects() {
  const pv = (k) => PEOPLE.map((p) => ({ p, h: sum(p.entries.filter((e) => e.p === k).map((e) => sum(e.h))) })).filter((x) => x.h);
  const rows = Object.entries(PROJ).filter(([, P]) => !P.leave && (S.ph === 'all' || P.bill)).map(([k, P]) => {
    const who = pv(k), a = sum(who.filter((x) => x.p.status === 'approved').map((x) => x.h)), b = sum(who.filter((x) => x.p.status === 'back').map((x) => x.h)), w = sum(who.filter((x) => x.p.status === 'pending').map((x) => x.h));
    return { k, P, who, a, b, w, t: a + b + w };
  }).sort((x, y) => y.t - x.t);
  const max = Math.max(...rows.map((r) => Math.max(r.t, r.P.plan))) * 1.05, T = sum(rows.map((r) => r.t));
  $('.dag-approvals__pl').innerHTML = rows.map((r, i) => {
    const v = r.t - r.P.plan, ex = S.openProj === r.k;
    return `<div class="dag-approvals__pr${ex ? ' is-open' : ''}" style="--i:${i};--c:${r.P.c}">
      <button type="button" class="dag-approvals__prh" data-proj="${r.k}" aria-expanded="${ex}">
        <span class="dag-approvals__pn"><b><i></i>${r.P.name}</b><small>${r.P.job}</small></span>
        <span class="dag-approvals__pbr"><i class="is-a" style="--w:${(r.a / max).toFixed(4)}"></i><i class="is-w" style="--w:${(r.w / max).toFixed(4)}"></i><i class="is-b" style="--w:${(r.b / max).toFixed(4)}"></i>${r.P.plan ? `<em style="--x:${(r.P.plan / max).toFixed(4)}"></em>` : ''}</span>
        <span class="dag-approvals__pnum"><b>${H(r.t)} h</b><small>${r.P.plan ? `plan ${r.P.plan} h · <span class="${v > 0 ? 'is-over' : 'is-under'}">${v > 0 ? '+' : '−'}${H(Math.abs(v))}</span>` : r.P.closed ? '<span class="is-over">closed, no plan</span>' : 'no plan'}</small></span>
        <svg class="dag-approvals-i dag-approvals__chev" viewBox="0 0 24 24" aria-hidden="true"><path d="m8 10 4 4 4-4"/></svg>
      </button>
      <div class="dag-approvals__pd"><div><ul>${r.who.sort((x, y) => y.h - x.h).map((x) => `<li>${av(x.p)}<span>${x.p.name}</span><b>${H(x.h)} h</b><em class="is-${x.p.status}">${x.p.status === 'approved' ? 'Approved' : x.p.status === 'back' ? 'Sent back' : 'Waiting'}</em></li>`).join('')}</ul></div></div>
    </div>`;
  }).join('') + `<p class="dag-approvals__pt">${H(T)} h across ${rows.length} ${S.ph === 'all' ? 'projects, studio time included' : 'billable projects'} · ${H(sum(rows.map((r) => r.a)))} h approved so far</p>`;
}

/* ------------------------------------------------------------------ orchestration */
function renderAll(flip) {
  renderHead();
  renderFilters();
  if (S.view === 'queue') { renderQueue(flip); renderSheet(); }
  else renderProjects();
}
function refresh() { renderHead(); renderFilters(); renderQueue(false); renderSheet(); }
function setView(v) {
  S.view = v;
  $$('[data-go]').forEach((b) => { b.setAttribute('aria-checked', b.dataset.go === v); b.tabIndex = b.dataset.go === v ? 0 : -1; });
  $$('.dag-approvals__view').forEach((el) => { el.hidden = el.dataset.view !== v; });
  hideTip();
  renderAll(false);
}
const typing = (t) => t && t.closest && t.closest('textarea, input, select');

root.addEventListener('click', (e) => {
  const t = e.target;
  let el;
  if (t.closest('[data-undo]')) { if (undoFn) { const f = undoFn; undoFn = null; f(); toast('Undone'); } return; }
  if ((el = t.closest('[data-go]'))) return setView(el.dataset.go);
  if (t.closest('[data-bulk]')) return runBulk();
  if ((el = t.closest('[data-filter]'))) { S.filter = el.dataset.filter; const l = list(); if (l.length && !l.some((p) => p.id === S.sel)) S.sel = l[0].id; return renderAll(false); }
  if ((el = t.closest('[data-p]'))) return select(el.dataset.p, false);
  if ((el = t.closest('[data-nudge]'))) { const m = MISSING.find((x) => x.id === el.dataset.nudge); m.nudged = '10:42'; renderQueue(false); return toast(`Reminder sent to ${m.name}: week 39 is due`); }
  if (t.closest('[data-approve]')) return approve(S.sel);
  if (t.closest('[data-back]')) { S.compose = true; renderSheet(); const ta = $('[data-cmp] textarea', sheet); if (ta) ta.focus({ preventScroll: true }); return; }
  if (t.closest('[data-cclose]')) { S.compose = false; renderSheet(); const b = $('[data-back]', sheet); if (b) b.focus({ preventScroll: true }); return; }
  if ((el = t.closest('[data-why]'))) {
    const on = el.getAttribute('aria-checked') !== 'true', ta = $('[data-cmp] textarea', sheet), line = '– ' + el.textContent;
    el.setAttribute('aria-checked', on);
    ta.value = on ? ta.value.replace(/\s*$/, '') + '\n' + line : ta.value.split('\n').filter((l) => l !== line).join('\n');
    return;
  }
  if (t.closest('[data-reopen]')) { const p = byId[S.sel], was = p.status; p.status = 'pending'; p.note = ''; renderAll(true); return toast(`${p.name} is back in the queue`, () => { p.status = was; renderAll(true); }); }
  if ((el = t.closest('[data-accept]'))) { const p = byId[S.sel]; p.ok.add(el.dataset.accept); refresh(); const n = open(p).length; toast(n ? `Flag accepted · ${n} still open` : `All flags accepted · ${p.name.split(' ')[0]} is ready to approve`); return; }
  if ((el = t.closest('[data-unaccept]'))) { const p = byId[S.sel]; p.ok.delete(el.dataset.unaccept); refresh(); return; }
  if ((el = t.closest('[data-show]'))) return showFlag(el.dataset.show);
  if ((el = t.closest('[data-ph]'))) { S.ph = el.dataset.ph; $$('[data-ph]').forEach((b) => { b.setAttribute('aria-checked', b === el); b.tabIndex = b === el ? 0 : -1; }); return renderProjects(); }
  if ((el = t.closest('[data-proj]'))) {
    const k = el.dataset.proj, row = el.parentElement, was = S.openProj;
    S.openProj = was === k ? null : k;
    $$('.dag-approvals__pr').forEach((r) => { const on = r.querySelector('[data-proj]').dataset.proj === S.openProj; r.classList.toggle('is-open', on); r.querySelector('[data-proj]').setAttribute('aria-expanded', on); });
    return row;
  }
});
root.addEventListener('submit', (e) => {
  const f = e.target.closest('[data-cmp]');
  if (!f) return;
  e.preventDefault();
  const v = f.msg.value.trim(), err = $('[data-err]', f);
  if (v.length < 12) { err.hidden = false; f.msg.setAttribute('aria-invalid', 'true'); f.msg.focus(); return; }
  sendBack(S.sel, v);
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.key === 'Escape' && S.compose) { e.preventDefault(); S.compose = false; renderSheet(); const b = $('[data-back]', sheet); if (b) b.focus({ preventScroll: true }); return; }
  if (typing(t) || e.metaKey || e.ctrlKey || e.altKey) return;
  const r = t.closest && t.closest('[role="radio"]');
  if (r && /^Arrow(Left|Right)$/.test(e.key)) {
    e.preventDefault();
    const g = $$('[role="radio"]', r.parentElement), i = (g.indexOf(r) + (e.key === 'ArrowRight' ? 1 : -1) + g.length) % g.length;
    g[i].focus(); g[i].click(); return;
  }
  if (S.view !== 'queue') return;
  const inList = t.closest && t.closest('.dag-approvals__ql');
  const k = e.key.toLowerCase();
  if (k === 'j' || k === 'k' || (inList && (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End'))) {
    e.preventDefault();
    const l = list(), i = l.findIndex((p) => p.id === S.sel);
    const n = e.key === 'Home' ? 0 : e.key === 'End' ? l.length - 1 : Math.max(0, Math.min(l.length - 1, i + (k === 'j' || e.key === 'ArrowDown' ? 1 : -1)));
    if (l[n]) select(l[n].id, true);
    return;
  }
  if (k === 'a') { e.preventDefault(); const p = byId[S.sel]; if (p && p.status === 'pending') { if (open(p).length) toast(`Accept or send back ${open(p).length} open flag${open(p).length === 1 ? '' : 's'} first`); else approve(S.sel); } return; }
  if (k === 's') { e.preventDefault(); const p = byId[S.sel]; if (p && p.status === 'pending') { S.compose = true; renderSheet(); const ta = $('[data-cmp] textarea', sheet); if (ta) ta.focus({ preventScroll: true }); } }
});
root.addEventListener('pointermove', (e) => {
  const t = e.target;
  let el;
  if ((el = t.closest('[data-day]'))) {
    const p = byId[S.sel], d = +el.dataset.day, rows = p.entries.filter((x) => x.h[d]).map((x) => trow(`${PROJ[x.p].name} · ${x.t}`, H(x.h[d]) + ' h', PROJ[x.p].c));
    return showTip(`<span class="dag-approvals__tt">${DAYS[d]} ${DATE[d]} Sep</span>${rows.join('') || trow('Nothing logged', '')}${trow('Day total', H(dayTot(p)[d]) + ' h')}`, e.clientX, e.clientY);
  }
  if ((el = t.closest('[data-cell]')) && el.textContent.trim() && el.dataset.cell !== 'tot') {
    const p = byId[S.sel], [ei, d] = el.dataset.cell.split(':').map(Number), x = p.entries[ei];
    return showTip(`<span class="dag-approvals__tt">${DAYS[d]} ${DATE[d]} Sep · ${H(x.h[d])} h</span>${trow(PROJ[x.p].name, x.t, PROJ[x.p].c)}<div class="dag-approvals__tn">${x.note || 'No note'}</div>`, e.clientX, e.clientY);
  }
  hideTip();
});
root.addEventListener('pointerleave', hideTip);
qlist.addEventListener('scroll', hideTip, { passive: true });

/* ------------------------------------------------------------------ mount */
renderAll(false);
